INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c768b264-bc65-4cb5-9057-971d376a1fe1', '春盡日宴罷感事獨吟', '春尽日宴罷感事独吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五年三月今朝盡，客散筵空獨掩扉。","病共樂天相伴住，春隨樊子一時歸。","閑聽鶯語移時立，思逐楊花觸處飛。","金帶縋腰衫委地，年年衰瘦不勝衣。"]', '["五年三月今朝尽，客散筵空独掩扉。","病共乐天相伴住，春隨樊子一时归。","闲听鶯語移时立，思逐楊花觸处飞。","金带縋腰衫委地，年年衰瘦不勝衣。"]', '诗', 'shi', '', NULL, '春盡日宴罷感事獨吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768287b6-de28-4e1a-90b7-b1446f1dca99', '病中辱崔宣城長句見寄兼有觥綺之贈因以四韻總而酬之', '病中辱崔宣城长句见寄兼有觥綺之贈因以四韻總而酬之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["劉[楨]病發經春臥，謝朓詩來盡日吟。","三道舊誇收片玉，一章新喜獲雙金。","信題霞綺緘情重，酒試銀觥表分深。","科第門生滿霄漢，歲寒少得似君心。"]', '["劉[楨]病發經春臥，謝朓诗来尽日吟。","三道旧誇收片玉，一章新喜獲雙金。","信題霞綺緘情重，酒試銀觥表分深。","科第门生满霄漢，歲寒少得似君心。"]', '诗', 'shi', '', NULL, '病中辱崔宣城長句見寄兼有觥綺之贈因以四韻總而酬之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b210956-7ecb-4dc9-921c-8d13afe96856', '前有別楊柳枝絕句夢得繼和云春盡絮飛留不得隨風好去落誰家又復戲答', '前有別楊柳枝絕句梦得繼和云春尽絮飞留不得隨风好去落誰家又复戲答', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳老春深日又斜，任他飛向別人家。","誰能更學孩童戲，尋逐春風捉柳花。"]', '["柳老春深日又斜，任他飞向別人家。","誰能更学孩童戲，尋逐春风捉柳花。"]', '诗', 'shi', '', NULL, '前有別楊柳枝絕句夢得繼和云春盡絮飛留不得隨風好去落誰家又復戲答 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca6b012-2f1d-45ea-bb0b-3ae116f50ee2', '池上早夏', '池上早夏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水積春塘晚，陰交夏木繁。","舟船如野渡，籬落似江村。","靜拂琴牀席，香開酒庫門。","慵閑無一事，時弄小嬌孫。"]', '["水積春塘晚，陰交夏木繁。","舟船如野渡，籬落似江村。","静拂琴牀席，香开酒庫门。","慵闲無一事，时弄小嬌孫。"]', '诗', 'shi', '', NULL, '池上早夏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b774ae7-0663-4e01-a218-08b63efa9e47', '談氏外孫生三日喜是男偶吟成篇兼戲呈夢得', '談氏外孫生三日喜是男偶吟成篇兼戲呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉芽珠顆小男兒，羅薦蘭湯欲罷時。","芣苢春來盈女手，梧桐老去長孫枝。","慶傳媒氏燕先賀，喜報談家烏預知。","明日貧翁具雞黍，應須酬賽引雛詩。"]', '["玉芽珠顆小男兒，羅薦蘭湯欲罷时。","芣苢春来盈女手，梧桐老去长孫枝。","慶傳媒氏燕先賀，喜報談家烏預知。","明日貧翁具雞黍，應須酬賽引雛诗。"]', '诗', 'shi', '', NULL, '談氏外孫生三日喜是男偶吟成篇兼戲呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71220610-5c41-494c-a80c-10e133f9c7ae', '開成大行皇帝挽歌詞四首奉敕撰進 一', '开成大行皇帝挽歌词四首奉敕撰進 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["御宇恢皇化，傳家叶至公。","華夷臣妾內，堯舜弟兄中。","制度移民俗，文章變國風。","開成與貞觀，實錄事多同。"]', '["御宇恢皇化，傳家叶至公。","华夷臣妾內，堯舜弟兄中。","制度移民俗，文章变国风。","开成與貞观，實錄事多同。"]', '诗', 'shi', '', NULL, '開成大行皇帝挽歌詞四首奉敕撰進 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfafe1b8-afa3-4363-bc05-c1fd37399b4d', '開成大行皇帝挽歌詞四首奉敕撰進 二', '开成大行皇帝挽歌词四首奉敕撰進 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晏駕辭雙闕，靈儀出九衢。","上雲歸碧落，下席葬蒼梧。","蓂晚餘堯曆，龜新啓夏圖。","三朝聯棣萼，從古帝王無。"]', '["晏駕辞雙闕，靈儀出九衢。","上云归碧落，下席葬蒼梧。","蓂晚餘堯曆，龟新啓夏圖。","三朝聯棣萼，從古帝王無。"]', '诗', 'shi', '', NULL, '開成大行皇帝挽歌詞四首奉敕撰進 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff0267f-d5cf-4399-baba-16d2516b337b', '開成大行皇帝挽歌詞四首奉敕撰進 三', '开成大行皇帝挽歌词四首奉敕撰進 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嚴恭七月禮，哀慟萬人心。","地感勝秋氣，天愁結夕陰。","鼎湖龍漸遠，濛汜日初沈。","唯有雲韶樂，長留治世音。"]', '["嚴恭七月禮，哀慟万人心。","地感勝秋氣，天愁結夕陰。","鼎湖龙漸远，濛汜日初沈。","唯有云韶乐，长留治世音。"]', '诗', 'shi', '', NULL, '開成大行皇帝挽歌詞四首奉敕撰進 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de8d604f-875d-404c-8f8a-adcfb804dfd8', '開成大行皇帝挽歌詞四首奉敕撰進 四', '开成大行皇帝挽歌词四首奉敕撰進 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["化成同軌表清平，恩結連枝感聖明。","帝與九齡雖吉夢，山呼萬歲是虛聲。","月低儀仗辭蘭路，風引笳簫入柏城。","老病龍髯攀不及，東周退傅最傷情。"]', '["化成同軌表清平，恩結連枝感聖明。","帝與九齡雖吉梦，山呼万歲是虛声。","月低儀仗辞蘭路，风引笳簫入柏城。","老病龙髯攀不及，东周退傅最傷情。"]', '诗', 'shi', '', NULL, '開成大行皇帝挽歌詞四首奉敕撰進 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6283f898-8e2c-45c7-967d-4290286f4115', '時熱少客因詠所懷', '时熱少客因詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["冠櫛心多懶，逢迎興漸微。","況當時熱甚，幸遇客來稀。","濕灑池邊地，涼開竹下扉。","露牀青篾簟，風架白蕉衣。","院靜留僧宿，樓空放妓歸。","衰殘強歡宴，此事久知非。"]', '["冠櫛心多懶，逢迎兴漸微。","況當时熱甚，幸遇客来稀。","濕灑池邊地，涼开竹下扉。","露牀青篾簟，风架白蕉衣。","院静留僧宿，楼空放妓归。","衰殘強歡宴，此事久知非。"]', '诗', 'shi', '', NULL, '時熱少客因詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c2aec3b-3a61-4625-9671-adc1df710075', '宣州崔大夫閤老忽以近詩數十首見示吟諷之下竊有所喜因成長句寄題郡齋', '宣州崔大夫閤老忽以近诗數十首见示吟諷之下竊有所喜因成长句寄題郡斋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謝玄暉歿吟聲寢，郡閣寥寥筆硯閑。","無復新詩題壁上，虛教遠岫列窗間。","忽驚歌雪今朝至，必恐文星昨夜還。","再喜宣城章句動，飛觴遙賀敬亭山。"]', '["謝玄暉歿吟声寢，郡閣寥寥笔硯闲。","無复新诗題壁上，虛教远岫列窗间。","忽驚歌雪今朝至，必恐文星昨夜還。","再喜宣城章句动，飞觴遙賀敬亭山。"]', '诗', 'shi', '', NULL, '宣州崔大夫閤老忽以近詩數十首見示吟諷之下竊有所喜因成長句寄題郡齋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a349ea-e298-4684-a604-c09ad7942195', '足疾', '足疾', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["足疾無加亦不瘳，綿春歷夏復經秋。","開顏且酌尊中酒，代步多乘池上舟。","幸有眼前衣食在，兼無身後子孫憂。","應須學取陶彭澤，但委心形任去留。"]', '["足疾無加亦不瘳，綿春歷夏复經秋。","开顏且酌尊中酒，代步多乘池上舟。","幸有眼前衣食在，兼無身後子孫憂。","應須学取陶彭澤，但委心形任去留。"]', '诗', 'shi', '', NULL, '足疾 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81955419-6668-4531-a8d1-e624f2020c80', '晚池汎舟遇景成詠贈呂處士', '晚池汎舟遇景成詠贈呂处士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["岸淺橋平池面寬，飄然輕櫂汎澄瀾。","風宜扇引開懷入，樹愛舟行仰臥看。","別境客稀知不易，能詩人少詠應難。","唯憐呂叟時相伴，同把磻溪舊釣竿。"]', '["岸淺橋平池面寬，飄然轻櫂汎澄瀾。","风宜扇引开懷入，樹愛舟行仰臥看。","別境客稀知不易，能诗人少詠應难。","唯怜呂叟时相伴，同把磻溪旧釣竿。"]', '诗', 'shi', '', NULL, '晚池汎舟遇景成詠贈呂處士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b11d99-9994-4ff0-a8db-d85d1b7ed065', '夢微之', '梦微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜來攜手夢同遊，晨起盈巾淚莫收。","漳浦老身三度病，咸陽草樹八迴秋。","君埋泉下泥銷骨，我寄人間雪滿頭。","阿衛韓郎相次去，夜臺茫昧得知不。"]', '["夜来携手梦同游，晨起盈巾泪莫收。","漳浦老身三度病，咸陽草樹八迴秋。","君埋泉下泥銷骨，我寄人间雪满头。","阿衛韓郎相次去，夜台茫昧得知不。"]', '诗', 'shi', '', NULL, '夢微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c6f35e8-6d5e-4204-8966-2d6731db7242', '感秋詠意', '感秋詠意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["炎涼遷次速如飛，又脫生衣著熟衣。","遶壁闇蛩無限思，戀巢寒燕未能歸。","須知流輩年年失，莫歎衰容日日非。","舊語相傳聊自慰，世間七十老人稀。"]', '["炎涼遷次速如飞，又脫生衣著熟衣。","遶壁闇蛩無限思，戀巢寒燕未能归。","須知流輩年年失，莫歎衰容日日非。","旧語相傳聊自慰，世间七十老人稀。"]', '诗', 'shi', '', NULL, '感秋詠意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf1cfc21-3d0f-4d3c-b078-4b12314de8ea', '老病幽獨偶吟所懷', '老病幽独偶吟所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眼漸昏昏耳漸聾，滿頭霜雪半身風。","已將身出浮雲外，猶寄形於逆旅中。","觴詠罷來賓閣閉，笙歌散後妓房空。","世緣俗念消除盡，別是人間清淨翁。"]', '["眼漸昏昏耳漸聾，满头霜雪半身风。","已將身出浮云外，猶寄形於逆旅中。","觴詠罷来賓閣閉，笙歌散後妓房空。","世緣俗念消除尽，別是人间清淨翁。"]', '诗', 'shi', '', NULL, '老病幽獨偶吟所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4006dcb1-2ecf-4a2c-a415-a4f437e6e489', '和楊尚書罷相後夏日遊永安水亭兼招本曹楊侍郎同行', '和楊尚书罷相後夏日游永安水亭兼招本曹楊侍郎同行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["道行無喜退無憂，舒卷如雲得自由。","良冶動時爲哲匠，巨川濟了作虛舟。","竹亭陰合偏宜夏，水檻風涼不待秋。","遙愛翩翩雙紫鳳，入同官署出同遊。"]', '["道行無喜退無憂，舒卷如云得自由。","良冶动时爲哲匠，巨川濟了作虛舟。","竹亭陰合偏宜夏，水檻风涼不待秋。","遙愛翩翩雙紫鳳，入同官署出同游。"]', '诗', 'shi', '', NULL, '和楊尚書罷相後夏日遊永安水亭兼招本曹楊侍郎同行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddb3ee4-eb64-4104-8e48-d22e53bd6c11', '在家出家', '在家出家', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衣食支吾婚嫁畢，從今家事不相仍。","夜眠身是投林鳥，朝飯心同乞食僧。","清唳數聲松下鶴，寒光一點竹間燈。","中宵入定跏趺坐，女喚妻呼多不應。"]', '["衣食支吾婚嫁畢，從今家事不相仍。","夜眠身是投林鸟，朝飯心同乞食僧。","清唳數声松下鹤，寒光一点竹间灯。","中宵入定跏趺坐，女喚妻呼多不應。"]', '诗', 'shi', '', NULL, '在家出家 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03372351-cdb4-4cc7-ab64-399e0c87ebba', '夜涼', '夜涼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["露白風清庭戶涼，老人先著夾衣裳。","舞腰歌袖拋何處，唯對無弦琴一張。"]', '["露白风清庭戶涼，老人先著夾衣裳。","舞腰歌袖拋何处，唯对無弦琴一張。"]', '诗', 'shi', '', NULL, '夜涼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a31154-38ba-4fe8-81a9-9e24b6f5f23c', '繼之尚書自余病來寄遺非一又蒙覽醉吟先生傳題詩以美之今以此篇用伸酬謝', '繼之尚书自余病来寄遺非一又蒙覽醉吟先生傳題诗以美之今以此篇用伸酬謝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衰殘與世日相疎，惠好唯君分有餘。","茶藥贈多因病久，衣裳寄早及寒初。","交情鄭重金相似，詩韻清鏘玉不如。","醉傅狂言人盡笑，獨知我者是尚書。"]', '["衰殘與世日相疎，惠好唯君分有餘。","茶藥贈多因病久，衣裳寄早及寒初。","交情鄭重金相似，诗韻清鏘玉不如。","醉傅狂言人尽笑，独知我者是尚书。"]', '诗', 'shi', '', NULL, '繼之尚書自余病來寄遺非一又蒙覽醉吟先生傳題詩以美之今以此篇用伸酬謝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0653223-b1fb-4104-ae2d-70545d323985', '五年秋病後獨宿香山寺三絕句 一', '五年秋病後独宿香山寺三絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["經年不到龍門寺，今夜何人知我情。","還向暢師房裏宿，新秋月色舊灘聲。"]', '["經年不到龙门寺，今夜何人知我情。","還向暢師房裏宿，新秋月色旧灘声。"]', '诗', 'shi', '', NULL, '五年秋病後獨宿香山寺三絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('984c61cc-704d-43f8-aed1-67c08511127d', '五年秋病後獨宿香山寺三絕句 二', '五年秋病後独宿香山寺三絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["飲徒歌伴今何在，雨散雲飛盡不迴。","從此香山風月夜，祗應長是一身來。"]', '["饮徒歌伴今何在，雨散云飞尽不迴。","從此香山风月夜，祗應长是一身来。"]', '诗', 'shi', '', NULL, '五年秋病後獨宿香山寺三絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9e5322-b071-484e-bb3e-42e4d8f5347b', '五年秋病後獨宿香山寺三絕句 三', '五年秋病後独宿香山寺三絕句 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["石盆泉畔石樓頭，十二年來晝夜遊。","更過今年年七十，假如無病亦宜休。"]', '["石盆泉畔石楼头，十二年来晝夜游。","更過今年年七十，假如無病亦宜休。"]', '诗', 'shi', '', NULL, '五年秋病後獨宿香山寺三絕句 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e57c3520-1757-4943-adea-0f05e4b0caf0', '題香山新經堂招僧', '題香山新經堂招僧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙滿秋堂月滿庭，香花漠漠磬泠泠。","誰能來此尋真諦，白老新開一藏經。"]', '["煙满秋堂月满庭，香花漠漠磬泠泠。","誰能来此尋真諦，白老新开一藏經。"]', '诗', 'shi', '', NULL, '題香山新經堂招僧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f8b1fd9-1e0d-4736-a90d-5aa587ce1b13', '偶題鄧公', '偶題鄧公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["偶因攜酒尋村客，聊復迴車訪薜蘿。","且值雪寒相慰問，不妨春暖更經過。","翁居山下年空老，我得人間事校多。","一種共翁頭似雪，翁無衣食自如何。"]', '["偶因携酒尋村客，聊复迴车訪薜蘿。","且值雪寒相慰问，不妨春暖更經過。","翁居山下年空老，我得人间事校多。","一種共翁头似雪，翁無衣食自如何。"]', '诗', 'shi', '', NULL, '偶題鄧公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2117e226-371a-4a3c-aa42-696c6bf035cf', '早入皇城贈王留守僕射', '早入皇城贈王留守僕射', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["津橋殘月曉沈沈，風露淒清禁署深。","城柳宮槐謾搖落，悲愁不到貴人心。"]', '["津橋殘月晓沈沈，风露淒清禁署深。","城柳宮槐謾搖落，悲愁不到貴人心。"]', '诗', 'shi', '', NULL, '早入皇城贈王留守僕射 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9a37d1-b354-4aa8-b4ce-d9da6b817cd7', '寄題廬山舊草堂兼呈二林寺道侶', '寄題廬山旧草堂兼呈二林寺道侶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十年前草堂主，而今雖在鬢如絲。","登山尋水應無力，不似江州司馬時。","漸伏酒魔休放醉，猶殘口業未拋詩。","君行過到鑪峰下，爲報東林長老知。"]', '["三十年前草堂主，而今雖在鬢如絲。","登山尋水應無力，不似江州司马时。","漸伏酒魔休放醉，猶殘口業未拋诗。","君行過到鑪峰下，爲報东林长老知。"]', '诗', 'shi', '', NULL, '寄題廬山舊草堂兼呈二林寺道侶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8654133-e05f-4b4c-baf1-8bc7966b9105', '改業', '改業', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["先生老去飲無興，居士病來閑有餘。","猶覺醉吟多放逸，不如禪定更清虛。","柘枝紫袖教丸藥，羯鼓蒼頭遣種蔬。","却被山僧戲相問，一時改業意何如。"]', '["先生老去饮無兴，居士病来闲有餘。","猶覺醉吟多放逸，不如禪定更清虛。","柘枝紫袖教丸藥，羯鼓蒼头遣種蔬。","却被山僧戲相问，一时改業意何如。"]', '诗', 'shi', '', NULL, '改業 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9735a2df-9045-42e0-ade6-475619a761b7', '山下留別佛光和尚', '山下留別佛光和尚', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勞師送我下山行，此別何人識此情。","我已七旬師九十，當知後會在他生。"]', '["勞師送我下山行，此別何人識此情。","我已七旬師九十，當知後會在他生。"]', '诗', 'shi', '', NULL, '山下留別佛光和尚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76311dbf-41e9-48b4-a738-4022d541cba7', '山中五絕句 嶺上雲', '山中五絕句 嶺上云', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嶺上白雲朝未散，田中青麥旱將枯。","自生自滅成何事，能逐東風作雨無。"]', '["嶺上白云朝未散，田中青麦旱將枯。","自生自滅成何事，能逐东风作雨無。"]', '诗', 'shi', '', NULL, '山中五絕句 嶺上雲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d34db24d-053b-4a0b-b861-bbedf317216d', '山中五絕句 石上苔', '山中五絕句 石上苔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漠漠斑斑石上苔，幽芳靜綠絕纖埃。","路傍凡草榮遭遇，曾得七香車輾來。"]', '["漠漠斑斑石上苔，幽芳静綠絕纖埃。","路傍凡草榮遭遇，曾得七香车輾来。"]', '诗', 'shi', '', NULL, '山中五絕句 石上苔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00fad44c-5847-4ff0-92b3-3ec81105050b', '山中五絕句 林下樗', '山中五絕句 林下樗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香檀文桂苦雕鐫，生理何曾得自全。","知我無材老樗否，一枝不損盡天年。"]', '["香檀文桂苦雕鐫，生理何曾得自全。","知我無材老樗否，一枝不損尽天年。"]', '诗', 'shi', '', NULL, '山中五絕句 林下樗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17434cae-0b68-4b7c-8f62-05ed4428ac19', '山中五絕句 澗中魚', '山中五絕句 澗中鱼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海水桑田欲變時，風濤翻覆沸天池。","鯨吞蛟鬬波成血，深澗遊魚樂不知。"]', '["海水桑田欲变时，风濤翻覆沸天池。","鯨吞蛟鬬波成血，深澗游鱼乐不知。"]', '诗', 'shi', '', NULL, '山中五絕句 澗中魚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e09cee2a-8dbe-4303-ba9f-ac0279b1f0a1', '山中五絕句 洞中蝙蝠', '山中五絕句 洞中蝙蝠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["千年鼠化白蝙蝠，黑洞深藏避網羅。","遠害全身誠得計，一生幽暗又如何。"]', '["千年鼠化白蝙蝠，黑洞深藏避網羅。","远害全身誠得計，一生幽暗又如何。"]', '诗', 'shi', '', NULL, '山中五絕句 洞中蝙蝠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18766ea9-e1df-444c-a56d-b0a4843ff534', '自戲三絕句 心問身', '自戲三絕句 心问身', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["心問身云何泰然，嚴冬暖被日高眠。","放君快活知恩否，不早朝來十一年。"]', '["心问身云何泰然，嚴冬暖被日高眠。","放君快活知恩否，不早朝来十一年。"]', '诗', 'shi', '', NULL, '自戲三絕句 心問身 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7d52d0-b7b9-41f4-9254-106b8de0f247', '自戲三絕句 身報心', '自戲三絕句 身報心', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["心是身王身是宮，君今居在我宮中。","是君家舍君須愛，何事論恩自說功。"]', '["心是身王身是宮，君今居在我宮中。","是君家舍君須愛，何事論恩自说功。"]', '诗', 'shi', '', NULL, '自戲三絕句 身報心 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b16d4ce-f736-432f-827b-9edb2be3c5d6', '自戲三絕句 心重荅身', '自戲三絕句 心重荅身', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["因我疎慵休罷早，遣君安樂歲時多。","世間老苦人何限，不放君閑奈我何。"]', '["因我疎慵休罷早，遣君安乐歲时多。","世间老苦人何限，不放君闲奈我何。"]', '诗', 'shi', '', NULL, '自戲三絕句 心重荅身 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('865c8b7f-47aa-42d6-910d-aba4b40661f7', '會昌元年春五絕句 病後喜過劉家', '會昌元年春五絕句 病後喜過劉家', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽憶前年初病後，此生甘分不銜杯。","誰能料得今春事，又向劉家飲酒來。"]', '["忽憶前年初病後，此生甘分不銜杯。","誰能料得今春事，又向劉家饮酒来。"]', '诗', 'shi', '', NULL, '會昌元年春五絕句 病後喜過劉家 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8877da7f-b340-444b-a6c3-097bc064d5c0', '會昌元年春五絕句 贈舉之僕射', '會昌元年春五絕句 贈舉之僕射', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雞毬餳粥屢開筵，談笑謳吟間管弦。","一月三迴寒食會，春光應不負今年。"]', '["雞毬餳粥屢开筵，談笑謳吟间管弦。","一月三迴寒食會，春光應不負今年。"]', '诗', 'shi', '', NULL, '會昌元年春五絕句 贈舉之僕射 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e40f33c-0c2c-4e21-81d5-61913fae3475', '會昌元年春五絕句 盧尹賀夢得會中作', '會昌元年春五絕句 盧尹賀梦得會中作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病聞川守賀筵開，起伴尚書飲一杯。","任意少年長笑我，老人自覓老人來。"]', '["病闻川守賀筵开，起伴尚书饮一杯。","任意少年长笑我，老人自覓老人来。"]', '诗', 'shi', '', NULL, '會昌元年春五絕句 盧尹賀夢得會中作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fdd3f37-29db-4c8a-893b-93dd3a972f59', '會昌元年春五絕句 題朗之槐亭', '會昌元年春五絕句 題朗之槐亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春風可惜無多日，家醞唯殘軟半瓶。","猶望君歸同一醉，籃舁早晚入槐亭。"]', '["春风可惜無多日，家醞唯殘軟半瓶。","猶望君归同一醉，籃舁早晚入槐亭。"]', '诗', 'shi', '', NULL, '會昌元年春五絕句 題朗之槐亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('302a138d-357b-42dc-819e-b27baf841844', '會昌元年春五絕句 勸夢得酒', '會昌元年春五絕句 勸梦得酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["誰人功畫麒麟閣，何客新投魑魅鄉。","兩處榮枯君莫問，殘春更醉兩三場。"]', '["誰人功畫麒麟閣，何客新投魑魅乡。","兩处榮枯君莫问，殘春更醉兩三場。"]', '诗', 'shi', '', NULL, '會昌元年春五絕句 勸夢得酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf240c0-5d5f-4eeb-95d7-c0abfa924ddd', '過裴令公宅二絕句 一', '過裴令公宅二絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風吹楊柳出牆枝，憶得同歡共醉時。","每到集賢坊地過，不曾一度不低眉。"]', '["风吹楊柳出牆枝，憶得同歡共醉时。","每到集賢坊地過，不曾一度不低眉。"]', '诗', 'shi', '', NULL, '過裴令公宅二絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c250379-fbcc-47d8-9b91-ee9a9c6f401c', '過裴令公宅二絕句 二', '過裴令公宅二絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["梁王舊館雪濛濛，愁殺鄒枚二老翁。","假使明朝深一尺，亦無人到兔園中。"]', '["梁王旧館雪濛濛，愁殺鄒枚二老翁。","假使明朝深一尺，亦無人到兔园中。"]', '诗', 'shi', '', NULL, '過裴令公宅二絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7977cdb8-5956-4380-ba7a-6c9f4098e8c0', '百日假滿少傅官停自喜言懷', '百日假满少傅官停自喜言懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長告今朝滿十旬，從茲蕭灑便終身。","老嫌手重拋牙笏，病喜頭輕換角巾。","疎傅不朝懸組綬，尚平無累畢婚姻。","人言世事何時了，我是人間事了人。"]', '["长告今朝满十旬，從茲蕭灑便終身。","老嫌手重拋牙笏，病喜头轻換角巾。","疎傅不朝懸組綬，尚平無累畢婚姻。","人言世事何时了，我是人间事了人。"]', '诗', 'shi', '', NULL, '百日假滿少傅官停自喜言懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea321309-c893-472c-866b-83a66dc7e5bf', '早熱', '早熱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["畏景又加旱，火雲殊未收。","籬暄飢有雀，池涸渴無鷗。","岸幘頭仍痛，褰裳汗亦流。","若爲當此日，遷客向炎州。"]', '["畏景又加旱，火云殊未收。","籬暄飢有雀，池涸渴無鷗。","岸幘头仍痛，褰裳汗亦流。","若爲當此日，遷客向炎州。"]', '诗', 'shi', '', NULL, '早熱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28933305-6ab0-4b29-b8ad-48b25fad93d7', '題崔少尹上林坊新居', '題崔少尹上林坊新居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["坊靜居新深且幽，忽疑縮地到滄洲。","宅東籬缺嵩峰出，堂後池開洛水流。","高下三層盤野徑，沿洄十里汎漁舟。","若能爲客烹雞黍，願伴田蘇日日遊。"]', '["坊静居新深且幽，忽疑縮地到滄洲。","宅东籬缺嵩峰出，堂後池开洛水流。","高下三層盤野徑，沿洄十里汎漁舟。","若能爲客烹雞黍，願伴田蘇日日游。"]', '诗', 'shi', '', NULL, '題崔少尹上林坊新居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('443e6b24-9d07-42cd-bd89-757bbd0b4e3b', '新澗亭', '新澗亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙蘿初合澗新開，閑上西亭日幾迴。","老病歸山應未得，且移泉石就身來。"]', '["煙蘿初合澗新开，闲上西亭日幾迴。","老病归山應未得，且移泉石就身来。"]', '诗', 'shi', '', NULL, '新澗亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c6c689c-cdec-40db-a4e5-84f57be9ff80', '對酒有懷寄李十九郎中', '对酒有懷寄李十九郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往年江外拋桃葉，去歲樓中別柳枝。","寂寞春來一杯酒，此情唯有李君知。"]', '["往年江外拋桃葉，去歲楼中別柳枝。","寂寞春来一杯酒，此情唯有李君知。"]', '诗', 'shi', '', NULL, '對酒有懷寄李十九郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de18a792-527a-42c5-836f-41c7aad429c7', '楊六尚書頻寄新詩詩中多有思閑相就之志因書鄙意報而諭之', '楊六尚书頻寄新诗诗中多有思闲相就之志因书鄙意報而諭之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君年殊未及懸車，未合將閑逐老夫。","身健正宜金印綬，位高方稱白髭鬚。","若論塵事何由了，但問雲心自在無。","進退是非俱是夢，丘中闕下亦何殊。"]', '["君年殊未及懸车，未合將闲逐老夫。","身健正宜金印綬，位高方稱白髭鬚。","若論塵事何由了，但问云心自在無。","進退是非俱是梦，丘中闕下亦何殊。"]', '诗', 'shi', '', NULL, '楊六尚書頻寄新詩詩中多有思閑相就之志因書鄙意報而諭之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12177bfb-8386-43af-852e-34c9bcf91d28', '偶吟自慰兼呈夢得', '偶吟自慰兼呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["且喜同年滿七旬，莫嫌衰病莫嫌貧。","已爲海內有名客，又占世間長命人。","耳裏聲聞新將相，眼前失盡故交親。","尊榮富壽難兼得，閑坐思量最要身。"]', '["且喜同年满七旬，莫嫌衰病莫嫌貧。","已爲海內有名客，又占世间长命人。","耳裏声闻新將相，眼前失尽故交親。","尊榮富壽难兼得，闲坐思量最要身。"]', '诗', 'shi', '', NULL, '偶吟自慰兼呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12716a9-f259-4051-8ae9-68af2ed88fe5', '寄潮州楊繼之', '寄潮州楊繼之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["相府潮陽俱夢中，夢中何者是窮通。","他時事過方應悟，不獨榮空辱亦空。"]', '["相府潮陽俱梦中，梦中何者是窮通。","他时事過方應悟，不独榮空辱亦空。"]', '诗', 'shi', '', NULL, '寄潮州楊繼之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33bebb08-6d90-4e4a-861e-ca4a4be1c986', '雪暮偶與夢得同致仕裴賓客王尚書飲', '雪暮偶與梦得同致仕裴賓客王尚书饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃昏慘慘雪霏霏，白首相歡醉不歸。","四箇老人三百歲人間此會亦應稀。"]', '["黄昏慘慘雪霏霏，白首相歡醉不归。","四箇老人三百歲人间此會亦應稀。"]', '诗', 'shi', '', NULL, '雪暮偶與夢得同致仕裴賓客王尚書飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dae3384d-bc09-486e-bc2f-1e44997fb773', '雪朝乘興欲詣李司徒留守先以五韻戲之', '雪朝乘兴欲詣李司徒留守先以五韻戲之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜寒生酒思，曉雪引詩情。","熱飲一兩醆，冷吟三五聲。","鋪花憐地凍，銷玉畏天晴。","好拂烏巾出，宜披鶴氅行。"]', '["夜寒生酒思，晓雪引诗情。","熱饮一兩醆，冷吟三五声。","鋪花怜地凍，銷玉畏天晴。","好拂烏巾出，宜披鹤氅行。"]', '诗', 'shi', '', NULL, '雪朝乘興欲詣李司徒留守先以五韻戲之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df56a349-6b98-41b5-9d47-c60776ff18da', '贈思黯', '贈思黯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲憐清淺愛潺湲，一日三迴到水邊。","若道歸仁灘更好，主人何故別三年。"]', '["爲怜清淺愛潺湲，一日三迴到水邊。","若道归仁灘更好，主人何故別三年。"]', '诗', 'shi', '', NULL, '贈思黯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('735b9974-1bab-4357-8f2d-a9f44df03d23', '聽歌六絕句 聽都子歌', '听歌六絕句 听都子歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["都子新歌有性靈，一聲格轉已堪聽。","更聽唱到嫦娥字，猶有樊家舊典刑。"]', '["都子新歌有性靈，一声格轉已堪听。","更听唱到嫦娥字，猶有樊家旧典刑。"]', '诗', 'shi', '', NULL, '聽歌六絕句 聽都子歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54177233-5b0d-48eb-a485-9a680046ee82', '聽歌六絕句 樂世', '听歌六絕句 乐世', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["管急弦繁拍漸稠，綠腰宛轉曲終頭。","誠知樂世聲聲樂，老病人聽未免愁。"]', '["管急弦繁拍漸稠，綠腰宛轉曲終头。","誠知乐世声声乐，老病人听未免愁。"]', '诗', 'shi', '', NULL, '聽歌六絕句 樂世 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e27f703-5220-4393-b2ae-876c4ec0e4a4', '聽歌六絕句 水調', '听歌六絕句 水調', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五言一徧最殷勤，調少情多似有因。","不會當時翻曲意，此聲腸斷爲何人。"]', '["五言一徧最殷勤，調少情多似有因。","不會當时翻曲意，此声腸斷爲何人。"]', '诗', 'shi', '', NULL, '聽歌六絕句 水調 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3b81ef3-019d-47db-ac40-544f6fdcfe1c', '聽歌六絕句 想夫憐', '听歌六絕句 想夫怜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉管朱弦莫急催，容聽歌送十分杯。","長愛夫憐第二句，請君重唱夕陽開。"]', '["玉管朱弦莫急催，容听歌送十分杯。","长愛夫怜第二句，請君重唱夕陽开。"]', '诗', 'shi', '', NULL, '聽歌六絕句 想夫憐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a64345f-9b5d-4b44-b8f8-5a388db3c175', '聽歌六絕句 何滿子', '听歌六絕句 何满子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世傳滿子是人名，臨就刑時曲始成。","一曲四調歌八疊，從頭便是斷腸聲。"]', '["世傳满子是人名，臨就刑时曲始成。","一曲四調歌八叠，從头便是斷腸声。"]', '诗', 'shi', '', NULL, '聽歌六絕句 何滿子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a994a3c7-5cdf-4115-b293-c2c6a91aa4db', '聽歌六絕句 離別難', '听歌六絕句 離別难', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綠楊陌上送行人，馬去車迴一望塵。","不覺別時紅淚盡，歸來無淚可霑巾。"]', '["綠楊陌上送行人，马去车迴一望塵。","不覺別时紅泪尽，归来無泪可霑巾。"]', '诗', 'shi', '', NULL, '聽歌六絕句 離別難 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1320e4b6-9ba5-4ac5-9d57-1195a90e96b7', '閑樂', '闲乐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["坐安臥穩輿平肩，倚杖披衫遶四邊。","空腹三杯卯後酒，曲肱一覺醉中眠。","更無忙苦吟閑樂，恐是人間自在天。"]', '["坐安臥穩輿平肩，倚杖披衫遶四邊。","空腹三杯卯後酒，曲肱一覺醉中眠。","更無忙苦吟闲乐，恐是人间自在天。"]', '诗', 'shi', '', NULL, '閑樂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08abce08-f0a4-47e9-b5e6-944b4ec778b9', '立秋夕涼風忽至炎暑稍消即事詠懷寄汴州節度使李二十尚書', '立秋夕涼风忽至炎暑稍消即事詠懷寄汴州節度使李二十尚书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嫋嫋簷樹動，好風西南來。","紅缸霏微滅，碧幌飄颻開。","披襟有餘涼，拂簟無纖埃。","但喜煩暑退，不惜光陰催。","河秋稍清淺，月午方裴回。","或行或坐臥，體適心悠哉。","美人在浚都，旌旗繞樓臺。","雖非滄溟阻，難見如蓬萊。","蟬迎節又換，雁送書未迴。","君位日寵重，我年日摧頹。","無因風月下，一舉平生杯。"]', '["嫋嫋簷樹动，好风西南来。","紅缸霏微滅，碧幌飄颻开。","披襟有餘涼，拂簟無纖埃。","但喜煩暑退，不惜光陰催。","河秋稍清淺，月午方裴回。","或行或坐臥，體適心悠哉。","美人在浚都，旌旗繞楼台。","雖非滄溟阻，难见如蓬萊。","蟬迎節又換，雁送书未迴。","君位日寵重，我年日摧頹。","無因风月下，一舉平生杯。"]', '诗', 'shi', '', NULL, '立秋夕涼風忽至炎暑稍消即事詠懷寄汴州節度使李二十尚書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c643deb-e874-4235-bf81-fc419dee5bd6', '開成二年夏聞新蟬贈夢得', '开成二年夏闻新蟬贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十載與君別，常感新蟬鳴。","今年共君聽，同在洛陽城。","噪處知林靜，聞時覺景清。","涼風忽嫋嫋，秋思先秋生。","殘槿花邊立，老槐陰下行。","雖無索居恨，還動長年情。","且喜未聾耳，年年聞此聲。"]', '["十載與君別，常感新蟬鳴。","今年共君听，同在洛陽城。","噪处知林静，闻时覺景清。","涼风忽嫋嫋，秋思先秋生。","殘槿花邊立，老槐陰下行。","雖無索居恨，還动长年情。","且喜未聾耳，年年闻此声。"]', '诗', 'shi', '', NULL, '開成二年夏聞新蟬贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca155661-0860-40b8-832e-9586a9506164', '題牛相公歸仁里宅新成小灘', '題牛相公归仁里宅新成小灘', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平生見流水，見此轉留連。","況此朱門內，君家新引泉。","伊流決一帶，洛石砌千拳。","與君三伏月，滿耳作潺湲。","深處碧磷磷，淺處清濺濺。","碕岸束嗚咽，沙汀散淪漣。","翻浪雪不盡，澄波空共鮮。","兩岸灩澦口，一泊瀟湘天。","曾作天南客，漂流六七年。","何山不倚杖，何水不停船。","巴峽聲心裏，松江色眼前。","今朝小灘上，能不思悠然。"]', '["平生见流水，见此轉留連。","況此朱门內，君家新引泉。","伊流決一带，洛石砌千拳。","與君三伏月，满耳作潺湲。","深处碧磷磷，淺处清濺濺。","碕岸束嗚咽，沙汀散淪漣。","翻浪雪不尽，澄波空共鲜。","兩岸灩澦口，一泊瀟湘天。","曾作天南客，漂流六七年。","何山不倚杖，何水不停船。","巴峽声心裏，松江色眼前。","今朝小灘上，能不思悠然。"]', '诗', 'shi', '', NULL, '題牛相公歸仁里宅新成小灘 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('918ab730-fa0e-4685-b721-132962a8ceb6', '春日閑居三首 一', '春日闲居三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陶云愛吾廬，吾亦愛吾屋。","屋中有琴書，聊以慰幽獨。","是時三月半，花落庭蕪綠。","舍上晨鳩鳴，窗間春睡足。","睡足起閑坐，景晏方櫛沐。","今日非十齋，庖童饋魚肉。","飢來恣餐歠，冷熱隨所欲。","飽竟快搔爬，筋骸無檢束。","豈徒暢肢體，兼欲遺耳目。","便可傲松喬，何假杯中淥。"]', '["陶云愛吾廬，吾亦愛吾屋。","屋中有琴书，聊以慰幽独。","是时三月半，花落庭蕪綠。","舍上晨鳩鳴，窗间春睡足。","睡足起闲坐，景晏方櫛沐。","今日非十斋，庖童饋鱼肉。","飢来恣餐歠，冷熱隨所欲。","飽竟快搔爬，筋骸無檢束。","豈徒暢肢體，兼欲遺耳目。","便可傲松喬，何假杯中淥。"]', '诗', 'shi', '', NULL, '春日閑居三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('447cc32b-af24-4cc5-ab72-6ea0b448f8d4', '春日閑居三首 二', '春日闲居三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["廣池春水平，羣魚恣遊泳。","新林綠陰成，衆鳥欣相鳴。","時我亦瀟灑，適無累與病。","魚鳥人則殊，同歸於遂性。","緬思山梁雉，時哉感孔聖。","聖人不得所，慨然歎時命。","我今對鱗羽，取樂成謠詠。","得所仍得時，吾生一何幸。"]', '["廣池春水平，羣鱼恣游泳。","新林綠陰成，衆鸟欣相鳴。","时我亦瀟灑，適無累與病。","鱼鸟人則殊，同归於遂性。","緬思山梁雉，时哉感孔聖。","聖人不得所，慨然歎时命。","我今对鱗羽，取乐成謠詠。","得所仍得时，吾生一何幸。"]', '诗', 'shi', '', NULL, '春日閑居三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2790dba2-3032-49dc-bba2-03667283e210', '春日閑居三首 三', '春日闲居三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勞者不覺歌，歌其勞苦事。","逸者不覺歌，歌其逸樂意。","問我逸如何，閑居多興味。","問我樂如何，閑官少憂累。","又問俸厚薄，百千隨月至。","又問年幾何，七十行欠二。","所得皆過望，省躬良可媿。","馬閑無羈絆，鶴老有祿位。","設自爲化工，優饒只如是。","安得不歌詠，默默受天賜。"]', '["勞者不覺歌，歌其勞苦事。","逸者不覺歌，歌其逸乐意。","问我逸如何，闲居多兴味。","问我乐如何，闲官少憂累。","又问俸厚薄，百千隨月至。","又问年幾何，七十行欠二。","所得皆過望，省躬良可媿。","马闲無羈絆，鹤老有祿位。","設自爲化工，優饒只如是。","安得不歌詠，默默受天賜。"]', '诗', 'shi', '', NULL, '春日閑居三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11870117-0aed-4c28-95ec-cb1e149fdbbb', '小閣閑坐', '小閣闲坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閣前竹蕭蕭，閣下水潺潺。","拂簟卷簾坐，清風生其間。","靜聞新蟬鳴，遠見飛鳥還。","但有巾挂壁，而無客叩關。","二疎返故里，四老歸舊山。","吾亦適所願，求閑而得閑。"]', '["閣前竹蕭蕭，閣下水潺潺。","拂簟卷簾坐，清风生其间。","静闻新蟬鳴，远见飞鸟還。","但有巾挂壁，而無客叩关。","二疎返故里，四老归旧山。","吾亦適所願，求闲而得闲。"]', '诗', 'shi', '', NULL, '小閣閑坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd40d75d-42c3-41bd-8681-4aa255146eee', '遊平泉宴浥澗宿香山石樓贈座客', '游平泉宴浥澗宿香山石楼贈座客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["逸少集蘭亭，季倫宴金谷。","金谷太繁華，蘭亭闕絲竹。","何如今日會，浥澗平泉曲。","杯酒與管弦，貧中隨分足。","紫鮮林筍嫩，紅潤園桃熟。","採摘助盤筵，芳滋盈口腹。","閑吟暮雲碧，醉藉春草綠。","舞妙豔流風，歌清叩寒玉。","古詩惜晝短，勸我令秉燭。","是夜勿言歸，相攜石樓宿。"]', '["逸少集蘭亭，季倫宴金谷。","金谷太繁华，蘭亭闕絲竹。","何如今日會，浥澗平泉曲。","杯酒與管弦，貧中隨分足。","紫鲜林筍嫩，紅潤园桃熟。","採摘助盤筵，芳滋盈口腹。","闲吟暮云碧，醉藉春草綠。","舞妙豔流风，歌清叩寒玉。","古诗惜晝短，勸我令秉燭。","是夜勿言归，相携石楼宿。"]', '诗', 'shi', '', NULL, '遊平泉宴浥澗宿香山石樓贈座客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c051c79-9237-4762-bb8b-f890a42989b5', '池上幽境', '池上幽境', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["褭褭過水橋，微微入林路。","幽境深誰知，老身閑獨步。","行行何所愛，遇物自成趣。","平滑青盤石，低密綠陰樹。","石上一素琴，樹下雙草屨。","此是榮先生，坐禪三樂處。"]', '["褭褭過水橋，微微入林路。","幽境深誰知，老身闲独步。","行行何所愛，遇物自成趣。","平滑青盤石，低密綠陰樹。","石上一素琴，樹下雙草屨。","此是榮先生，坐禪三乐处。"]', '诗', 'shi', '', NULL, '池上幽境 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d83fdb-34d8-439a-b4e5-e4f37d12cc71', '夏日閑放', '夏日闲放', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["時暑不出門，亦無賓客至。","靜室深下簾，小庭新掃地。","褰裳復岸幘，閑傲得自恣。","朝景枕簟清，乘涼一覺睡。","午餐何所有，魚肉一兩味。","夏服亦無多，蕉紗三五事。","資身既給足，長物徒煩費。","若比簞瓢人，吾今太富貴。"]', '["时暑不出门，亦無賓客至。","静室深下簾，小庭新掃地。","褰裳复岸幘，闲傲得自恣。","朝景枕簟清，乘涼一覺睡。","午餐何所有，鱼肉一兩味。","夏服亦無多，蕉紗三五事。","資身既給足，长物徒煩費。","若比簞瓢人，吾今太富貴。"]', '诗', 'shi', '', NULL, '夏日閑放 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ce3eb7-49dc-4d66-8e3d-0d9e29da8287', '和思黯居守獨飲偶醉見示六韻時夢得和篇先成頗爲麗絕時添兩韻繼而美之', '和思黯居守独饮偶醉见示六韻时梦得和篇先成頗爲丽絕时添兩韻繼而美之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宮漏滴漸闌，城烏啼復歇。","此時若不醉，爭奈千門月。","主人中夜起，妓燭前羅列。","歌袂默收聲，舞鬟低赴節。","弦吟玉柱品，酒透金杯熱。","朱顏忽已酡，清奏猶未闋。","妍詞黯先唱，逸韻劉繼發。","鏗然雙雅音，金石相磨戛。"]', '["宮漏滴漸闌，城烏啼复歇。","此时若不醉，爭奈千门月。","主人中夜起，妓燭前羅列。","歌袂默收声，舞鬟低赴節。","弦吟玉柱品，酒透金杯熱。","朱顏忽已酡，清奏猶未闋。","妍词黯先唱，逸韻劉繼發。","鏗然雙雅音，金石相磨戛。"]', '诗', 'shi', '', NULL, '和思黯居守獨飲偶醉見示六韻時夢得和篇先成頗爲麗絕時添兩韻繼而美之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85e874f-0079-43d5-8677-b07b86f3bf68', '和夢得洛中早春見贈七韻', '和梦得洛中早春见贈七韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衆皆賞春色，君獨憐春意。","春意竟如何，老夫知此味。","燭餘減夜漏，衾暖添朝睡。","恬和臺上風，虛潤池邊地。","開遲花養豔，語懶鶯含思。","似訝隔年齋，如勸迎春醉。","何日同宴遊，心期二月二。"]', '["衆皆賞春色，君独怜春意。","春意竟如何，老夫知此味。","燭餘減夜漏，衾暖添朝睡。","恬和台上风，虛潤池邊地。","开遲花養豔，語懶鶯含思。","似訝隔年斋，如勸迎春醉。","何日同宴游，心期二月二。"]', '诗', 'shi', '', NULL, '和夢得洛中早春見贈七韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53084e93-55af-42ff-98d7-6b3c05f7b2d5', '櫻桃花下有感而作', '櫻桃花下有感而作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["藹藹美周宅，櫻繁春日斜。","一爲洛下客，十見池上花。","爛熳豈無意，爲君占年華。","風光饒此樹，歌舞勝諸家。","失盡白頭伴，長成紅粉娃。","停杯兩相顧，堪喜亦堪嗟。"]', '["藹藹美周宅，櫻繁春日斜。","一爲洛下客，十见池上花。","爛熳豈無意，爲君占年华。","风光饒此樹，歌舞勝諸家。","失尽白头伴，长成紅粉娃。","停杯兩相顧，堪喜亦堪嗟。"]', '诗', 'shi', '', NULL, '櫻桃花下有感而作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9952183-9f8b-47a5-97db-ca095c95eb28', '洗竹', '洗竹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["布衾寒擁頸，氈履溫承足。","獨立冰池前，久看洗霜竹。","先除老且病，次去纖而曲。","剪棄猶可憐，琅玕十餘束。","青青復籊籊，頗異凡草木。","依然若有情，回頭語僮僕。","小者截魚竿，大者編茅屋。","勿作篲與箕，而令糞土辱。"]', '["布衾寒擁頸，氈履溫承足。","独立冰池前，久看洗霜竹。","先除老且病，次去纖而曲。","剪棄猶可怜，琅玕十餘束。","青青复籊籊，頗異凡草木。","依然若有情，回头語僮僕。","小者截鱼竿，大者編茅屋。","勿作篲與箕，而令糞土辱。"]', '诗', 'shi', '', NULL, '洗竹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec71e4f-1e6f-4f25-8fc6-40b2622e372b', '新沐浴', '新沐浴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["形適外無恙，心恬內無憂。","夜來新沐浴，肌髮舒且柔。","寬裁夾烏帽，厚絮長白裘。","裘溫裹我足，帽暖覆我頭。","先進酒一杯，次舉粥一甌。","半酣半飽時，四體春悠悠。","是月歲陰暮，慘冽天地愁。","白日冷無光，黃河凍不流。","何處征戍行，何人羈旅遊。","窮途絕糧客，寒獄無燈囚。","勞生彼何苦，遂性我何優。","撫心但自媿，孰知其所由。"]', '["形適外無恙，心恬內無憂。","夜来新沐浴，肌髮舒且柔。","寬裁夾烏帽，厚絮长白裘。","裘溫裹我足，帽暖覆我头。","先進酒一杯，次舉粥一甌。","半酣半飽时，四體春悠悠。","是月歲陰暮，慘冽天地愁。","白日冷無光，黄河凍不流。","何处征戍行，何人羈旅游。","窮途絕糧客，寒獄無灯囚。","勞生彼何苦，遂性我何優。","撫心但自媿，孰知其所由。"]', '诗', 'shi', '', NULL, '新沐浴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe1bf48-ea99-43d1-af81-2bf42aa8ea0e', '三年除夜', '三年除夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晰晰燎火光，氳氳臘酒香。","嗤嗤童稚戲，迢迢歲夜長。","堂上書帳前，長幼合成行。","以我年最長，次第來稱觴。","七十期漸近，萬綠心已忘。","不唯少歡樂，兼亦無悲傷。","素屏應居士，青衣侍孟光。","夫妻老相對，各坐一繩牀。"]', '["晰晰燎火光，氳氳臘酒香。","嗤嗤童稚戲，迢迢歲夜长。","堂上书帳前，长幼合成行。","以我年最长，次第来稱觴。","七十期漸近，万綠心已忘。","不唯少歡乐，兼亦無悲傷。","素屏應居士，青衣侍孟光。","夫妻老相对，各坐一繩牀。"]', '诗', 'shi', '', NULL, '三年除夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0d6427-7125-4b0c-bdb2-399004d33a0d', '自題小園', '自題小园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不鬬門館華，不鬬林園大。","但鬬爲主人，一坐十餘載。","迴看甲乙第，列在都城內。","素垣夾朱門，藹藹遙相對。","主人安在哉，富貴去不迴。","池乃爲魚鑿，林乃爲禽栽。","何如小園主，拄杖閑即來。","親賓有時會，琴酒連夜開。","以此聊自足，不羨大池臺。"]', '["不鬬门館华，不鬬林园大。","但鬬爲主人，一坐十餘載。","迴看甲乙第，列在都城內。","素垣夾朱门，藹藹遙相对。","主人安在哉，富貴去不迴。","池乃爲鱼鑿，林乃爲禽栽。","何如小园主，拄杖闲即来。","親賓有时會，琴酒連夜开。","以此聊自足，不羨大池台。"]', '诗', 'shi', '', NULL, '自題小園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b806e551-5624-46fa-a51c-68ca730aacc5', '病中宴坐', '病中宴坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有酒病不飲，有詩慵不吟。","頭眩罷垂鉤，手痹休援琴。","竟日悄無事，所居閑且深。","外安支離體，中養希夷心。","窗戶納秋景，竹木澄夕陰。","宴坐小池畔，清風時動襟。"]', '["有酒病不饮，有诗慵不吟。","头眩罷垂鉤，手痹休援琴。","竟日悄無事，所居闲且深。","外安支離體，中養希夷心。","窗戶納秋景，竹木澄夕陰。","宴坐小池畔，清风时动襟。"]', '诗', 'shi', '', NULL, '病中宴坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efaf5330-dc43-4226-817d-642472e4ba0a', '戒藥', '戒藥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["促促急景中，蠢蠢微塵裏。","生涯有分限，愛戀無終已。","早夭羨中年，中年羨暮齒。","暮齒又貪生，服食求不死。","朝吞太陽精，夕吸秋石髓。","徼福反成災，藥誤者多矣。","以之資嗜慾，又望延甲子。","天人陰隲間，亦恐無此理。","域中有真道，所說不如此。","後身始身存，吾聞諸老氏。"]', '["促促急景中，蠢蠢微塵裏。","生涯有分限，愛戀無終已。","早夭羨中年，中年羨暮齒。","暮齒又貪生，服食求不死。","朝吞太陽精，夕吸秋石髓。","徼福反成災，藥誤者多矣。","以之資嗜慾，又望延甲子。","天人陰隲间，亦恐無此理。","域中有真道，所说不如此。","後身始身存，吾闻諸老氏。"]', '诗', 'shi', '', NULL, '戒藥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf8e156-c142-4307-9c60-04daadbb556a', '贈夢得', '贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前日君家飲，昨日王家宴。","今日過我廬，三日三會面。","當歌聊自放，對酒交相勸。","爲我盡一杯，與君發三願。","一願世清平，二願身強健。","三願臨老頭，數與君相見。"]', '["前日君家饮，昨日王家宴。","今日過我廬，三日三會面。","當歌聊自放，对酒交相勸。","爲我尽一杯，與君發三願。","一願世清平，二願身強健。","三願臨老头，數與君相见。"]', '诗', 'shi', '', NULL, '贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9a4c9d-7551-4045-a59d-5afb4c7b7167', '逸老', '逸老', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白日下駸駸，青天高浩浩。","人生在其中，適時即爲好。","勞我以少壯，息我以衰老。","順之多吉壽，違之或凶夭。","我初五十八，息老雖非早。","一閑十三年，所得亦不少。","況加祿仕後，衣食常溫飽。","又從風疾來，女嫁男婚了。","胷中一無事，浩氣凝襟抱。","飄若雲信風，樂於魚在藻。","桑榆坐已暮，鐘漏行將曉。","皤然七十翁，亦足稱壽考。","筋骸本非實，一束芭蕉草。","眷屬偶相依，一夕同栖鳥。","去何有顧戀，住亦無憂惱。","生死尚復然，其餘安足道。","是故臨老心，冥然合玄造。"]', '["白日下駸駸，青天高浩浩。","人生在其中，適时即爲好。","勞我以少壯，息我以衰老。","順之多吉壽，違之或凶夭。","我初五十八，息老雖非早。","一闲十三年，所得亦不少。","況加祿仕後，衣食常溫飽。","又從风疾来，女嫁男婚了。","胷中一無事，浩氣凝襟抱。","飄若云信风，乐於鱼在藻。","桑榆坐已暮，鐘漏行將晓。","皤然七十翁，亦足稱壽考。","筋骸本非實，一束芭蕉草。","眷屬偶相依，一夕同栖鸟。","去何有顧戀，住亦無憂惱。","生死尚复然，其餘安足道。","是故臨老心，冥然合玄造。"]', '诗', 'shi', '', NULL, '逸老 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ffe4f6a-3d2f-4e03-b5e4-21786d9b910d', '遇物感興因示子弟', '遇物感兴因示子弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聖擇狂夫言，俗信老人語。","我有老狂詞，聽之吾語汝。","吾觀器用中，劒銳鋒多傷。","吾觀形骸內，骨勁齒先亡。","寄言處世者，不可苦剛強。","龜性愚且善，鳩心鈍無惡。","人賤拾支牀，鶻欺擒暖脚。","寄言立身者，不得全柔弱。","彼固罹禍難，此未免憂患。","于何保終吉，強弱剛柔間。","上遵周孔訓，旁鑒老莊言。","不唯鞭其後，亦要軛其先。"]', '["聖擇狂夫言，俗信老人語。","我有老狂词，听之吾語汝。","吾观器用中，劒銳鋒多傷。","吾观形骸內，骨勁齒先亡。","寄言处世者，不可苦剛強。","龟性愚且善，鳩心鈍無惡。","人賤拾支牀，鶻欺擒暖脚。","寄言立身者，不得全柔弱。","彼固罹禍难，此未免憂患。","于何保終吉，強弱剛柔间。","上遵周孔訓，旁鑒老莊言。","不唯鞭其後，亦要軛其先。"]', '诗', 'shi', '', NULL, '遇物感興因示子弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9f4656c-bec2-4a71-bed3-fcc816f81f4d', '首夏南池獨酌', '首夏南池独酌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春盡雜英歇，夏初芳草深。","薰風自南至，吹我池上林。","綠蘋散還合，頳鯉跳復沈。","新葉有佳色，殘鶯猶好音。","依然謝家物，池酌對風琴。","慙無康樂作，秉筆思沈吟。","境勝才思劣，詩成不稱心。"]', '["春尽杂英歇，夏初芳草深。","薰风自南至，吹我池上林。","綠蘋散還合，頳鯉跳复沈。","新葉有佳色，殘鶯猶好音。","依然謝家物，池酌对风琴。","慙無康乐作，秉笔思沈吟。","境勝才思劣，诗成不稱心。"]', '诗', 'shi', '', NULL, '首夏南池獨酌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5989bfc0-3786-47fc-bc30-d58bb638955a', '官俸初罷親故見憂以詩諭之', '官俸初罷親故见憂以诗諭之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七年爲少傅，品高俸不薄。","乘軒已多慙，況是一病鶴。","又及懸車歲，筋力轉衰弱。","豈以貧是憂，尚爲名所縛。","今春始病免，纓組初擺落。","蜩甲有何知，雲心無所著。","囷中殘舊穀，可備歲饑惡。","園中多新蔬，未至食藜藿。","不求安師卜，不問陳生藥。","但對丘中琴，時開池上酌。","信風舟不繫，掉尾魚方樂。","親友不我知，而憂我寂寞。"]', '["七年爲少傅，品高俸不薄。","乘軒已多慙，況是一病鹤。","又及懸车歲，筋力轉衰弱。","豈以貧是憂，尚爲名所縛。","今春始病免，纓組初擺落。","蜩甲有何知，云心無所著。","囷中殘旧穀，可備歲饑惡。","园中多新蔬，未至食藜藿。","不求安師卜，不问陳生藥。","但对丘中琴，时开池上酌。","信风舟不繫，掉尾鱼方乐。","親友不我知，而憂我寂寞。"]', '诗', 'shi', '', NULL, '官俸初罷親故見憂以詩諭之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028660ea-cc99-48a5-8662-41c1a62f603f', '閑居偶吟招鄭庶子皇甫郎中', '闲居偶吟招鄭庶子皇甫郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自哂此迂叟，少迂老更迂。","家計不一問，園林聊自娛。","竹間琴一張，池上酒一壺。","更無俗物到，但與秋光俱。","古石蒼錯落，新泉碧縈紆。","焉用車馬客，即此是吾徒。","猶有所思人，各在城一隅。","杳然愛不見，搔首方踟躕。","玄晏風韻遠，子真雲貌孤。","誠知厭朝市，何必憶江湖。","能來小澗上，一聽潺湲無。"]', '["自哂此迂叟，少迂老更迂。","家計不一问，园林聊自娛。","竹间琴一張，池上酒一壺。","更無俗物到，但與秋光俱。","古石蒼錯落，新泉碧縈紆。","焉用车马客，即此是吾徒。","猶有所思人，各在城一隅。","杳然愛不见，搔首方踟躕。","玄晏风韻远，子真云貌孤。","誠知厭朝市，何必憶江湖。","能来小澗上，一听潺湲無。"]', '诗', 'shi', '', NULL, '閑居偶吟招鄭庶子皇甫郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d94679-b8fc-4a95-a1c6-9b75a1ff66cb', '亭西牆下伊渠水中置石激流潺湲成韻頗有幽趣以詩記之', '亭西牆下伊渠水中置石激流潺湲成韻頗有幽趣以诗記之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嵌巉嵩石峭，皎潔伊流清。","立爲遠峰勢，激作寒玉聲。","夾岸羅密樹，面灘開小亭。","忽疑嚴子瀨，流入洛陽城。","是時羣動息，風靜微月明。","高枕夜悄悄，滿耳秋泠泠。","終日臨大道，何人知此情。","此情苟自愜，亦不要人聽。"]', '["嵌巉嵩石峭，皎潔伊流清。","立爲远峰勢，激作寒玉声。","夾岸羅密樹，面灘开小亭。","忽疑嚴子瀨，流入洛陽城。","是时羣动息，风静微月明。","高枕夜悄悄，满耳秋泠泠。","終日臨大道，何人知此情。","此情苟自愜，亦不要人听。"]', '诗', 'shi', '', NULL, '亭西牆下伊渠水中置石激流潺湲成韻頗有幽趣以詩記之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd44663-298f-4575-b367-7ac7788f67f2', '閑題家池寄王屋張道士', '闲題家池寄王屋張道士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有石白磷磷，有水清潺潺。","有叟頭似雪，婆娑乎其間。","進不趨要路，退不入深山。","深山太濩落，要路多險艱。","不如家池上，樂逸無憂患。","有食適吾口，有酒酡吾顏。","恍惚遊醉鄉，希夷造玄關。","五千言下悟，十二年來閑。","富者我不顧，貴者我不攀。","唯有天壇子，時來一往還。"]', '["有石白磷磷，有水清潺潺。","有叟头似雪，婆娑乎其间。","進不趨要路，退不入深山。","深山太濩落，要路多險艱。","不如家池上，乐逸無憂患。","有食適吾口，有酒酡吾顏。","恍惚游醉乡，希夷造玄关。","五千言下悟，十二年来闲。","富者我不顧，貴者我不攀。","唯有天壇子，时来一往還。"]', '诗', 'shi', '', NULL, '閑題家池寄王屋張道士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef64b452-6a83-4cb4-8362-656f1a5e8c5e', '李盧二中丞各創山居俱誇勝絕然去城稍遠來往頗勞弊居新泉實在宇下偶題十五韻聊戲二君', '李盧二中丞各創山居俱誇勝絕然去城稍远来往頗勞弊居新泉實在宇下偶題十五韻聊戲二君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["龍門蒼石壁，浥澗碧潭水。","各在一山隅，迢遙幾十里。","清鏡碧屏風，惜哉信爲美。","愛而不得見，亦與無相似。","聞君每來去，矻矻事行李。","脂轄復裹糧，心力頗勞止。","未如吾舍下，石與泉甚邇。","鑿鑿復濺濺，晝夜流不已。","洛石千萬拳，襯波鋪錦綺。","海珉一兩片，激瀨含宮徵。","綠宜春濯足，淨可朝漱齒。","遶砌紫鱗遊，拂簾白鳥起。","何言履道叟，便是滄浪子。","君若趁歸程，請君先到此。","願以潺湲聲，洗君塵土耳。"]', '["龙门蒼石壁，浥澗碧潭水。","各在一山隅，迢遙幾十里。","清镜碧屏风，惜哉信爲美。","愛而不得见，亦與無相似。","闻君每来去，矻矻事行李。","脂轄复裹糧，心力頗勞止。","未如吾舍下，石與泉甚邇。","鑿鑿复濺濺，晝夜流不已。","洛石千万拳，襯波鋪錦綺。","海珉一兩片，激瀨含宮徵。","綠宜春濯足，淨可朝漱齒。","遶砌紫鱗游，拂簾白鸟起。","何言履道叟，便是滄浪子。","君若趁归程，請君先到此。","願以潺湲声，洗君塵土耳。"]', '诗', 'shi', '', NULL, '李盧二中丞各創山居俱誇勝絕然去城稍遠來往頗勞弊居新泉實在宇下偶題十五韻聊戲二君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0851be33-fa47-4177-ab32-960f99438fb7', '北窗竹石', '北窗竹石', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一片瑟瑟石，數竿青青竹。","向我如有情，依然看不足。","況臨北窗下，復近西塘曲。","筠風散餘清，苔雨含微綠。","有妻亦衰老，無子方煢獨。","莫掩夜窗扉，共渠相伴宿。"]', '["一片瑟瑟石，數竿青青竹。","向我如有情，依然看不足。","況臨北窗下，复近西塘曲。","筠风散餘清，苔雨含微綠。","有妻亦衰老，無子方煢独。","莫掩夜窗扉，共渠相伴宿。"]', '诗', 'shi', '', NULL, '北窗竹石 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33789ba7-a44a-4989-9da1-f1379968bb8a', '飲後戲示弟子', '饮後戲示弟子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾爲爾先生，爾爲吾弟子。","孔門有遺訓，復坐吾告爾。","先生饌酒食，弟子服勞止。","孝敬不在他，在茲而已矣。","欲我少憂愁，欲我多歡喜。","無如醞好酒，酒須多且旨。","旨即賓可留，多即罍不恥。","吾更有一言，爾宜聽入耳。","人老多憂貧，人病多憂死。","我今雖老病，所憂不在此。","憂在半酣時，尊空座客起。"]', '["吾爲爾先生，爾爲吾弟子。","孔门有遺訓，复坐吾告爾。","先生饌酒食，弟子服勞止。","孝敬不在他，在茲而已矣。","欲我少憂愁，欲我多歡喜。","無如醞好酒，酒須多且旨。","旨即賓可留，多即罍不恥。","吾更有一言，爾宜听入耳。","人老多憂貧，人病多憂死。","我今雖老病，所憂不在此。","憂在半酣时，尊空座客起。"]', '诗', 'shi', '', NULL, '飲後戲示弟子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79595710-c31b-4b1d-bb36-7977c563bf5b', '閑坐看書貽諸少年', '闲坐看书貽諸少年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雨砌長寒蕪，風庭落秋果。","窗間有閑叟，盡日看書坐。","書中見往事，歷歷知福禍。","多取終厚亡，疾驅必先墮。","勸君少干名，名爲錮身鏁。","勸君少求利，利是焚身火。","我心知已久，吾道無不可。","所以雀羅門，不能寂寞我。"]', '["雨砌长寒蕪，风庭落秋果。","窗间有闲叟，尽日看书坐。","书中见往事，歷歷知福禍。","多取終厚亡，疾驱必先墮。","勸君少干名，名爲錮身鏁。","勸君少求利，利是焚身火。","我心知已久，吾道無不可。","所以雀羅门，不能寂寞我。"]', '诗', 'shi', '', NULL, '閑坐看書貽諸少年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('650c3277-30c8-4f12-807e-df47dfdc441e', '夢上山', '梦上山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜夢上嵩山，獨攜藜杖出。","千巖與萬壑，遊覽皆周畢。","夢中足不病，健似少年日。","既悟神返初，依然舊形質。","始知形神內，形病神無疾。","形神兩是幻，夢寐俱非實。","晝行雖蹇澀，夜步頗安逸。","晝夜既平分，其間何得失。"]', '["夜梦上嵩山，独携藜杖出。","千巖與万壑，游覽皆周畢。","梦中足不病，健似少年日。","既悟神返初，依然旧形質。","始知形神內，形病神無疾。","形神兩是幻，梦寐俱非實。","晝行雖蹇澀，夜步頗安逸。","晝夜既平分，其间何得失。"]', '诗', 'shi', '', NULL, '夢上山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29a75999-e769-4fa2-8406-1245036bee8c', '對酒閑吟贈同老者', '对酒闲吟贈同老者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人生七十稀，我年幸過之。","遠行將盡路，春夢欲覺時。","家事口不問，世名心不思。","老既不足歎，病亦不能治。","扶持仰婢僕，將養信妻兒。","飢飽進退食，寒暄加減衣。","聲妓放鄭衛，裘馬脫輕肥。","百事盡除去，尚餘酒與詩。","興來吟一篇，吟罷酒一巵。","不獨適情性，兼用扶衰羸。","雲液灑六腑，陽和生四肢。","於中我自樂，此外吾不知。","寄問同老者，捨此將安歸。","莫學蓬心叟，胷中殘是非。"]', '["人生七十稀，我年幸過之。","远行將尽路，春梦欲覺时。","家事口不问，世名心不思。","老既不足歎，病亦不能治。","扶持仰婢僕，將養信妻兒。","飢飽進退食，寒暄加減衣。","声妓放鄭衛，裘马脫轻肥。","百事尽除去，尚餘酒與诗。","兴来吟一篇，吟罷酒一巵。","不独適情性，兼用扶衰羸。","云液灑六腑，陽和生四肢。","於中我自乐，此外吾不知。","寄问同老者，捨此將安归。","莫学蓬心叟，胷中殘是非。"]', '诗', 'shi', '', NULL, '對酒閑吟贈同老者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea109bd2-c2ee-41ce-aa8b-4031768a1f89', '晚起閑行', '晚起闲行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["皤然一老子，擁裘仍隱几。","坐穩夜忘眠，臥安朝不起。","起來無可作，閉目時叩齒。","靜對銅爐香，暖漱銀瓶水。","午齋何儉潔，餅與蔬而已。","西寺講楞伽，閑行一隨喜。"]', '["皤然一老子，擁裘仍隐几。","坐穩夜忘眠，臥安朝不起。","起来無可作，閉目时叩齒。","静对銅爐香，暖漱銀瓶水。","午斋何儉潔，餅與蔬而已。","西寺講楞伽，闲行一隨喜。"]', '诗', 'shi', '', NULL, '晚起閑行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd41c21f-37df-49ab-94cc-977f21bccc34', '香山居士寫真詩', '香山居士寫真诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔作少學士，圖形入集賢。","今爲老居士，寫貌寄香山。","鶴毳變玄髮，雞膚換朱顏。","前形與後貌，相去三十年。","勿歎韶華子，俄成皤叟仙。","請看東海水，亦變作桑田。"]', '["昔作少学士，圖形入集賢。","今爲老居士，寫貌寄香山。","鹤毳变玄髮，雞膚換朱顏。","前形與後貌，相去三十年。","勿歎韶华子，俄成皤叟仙。","請看东海水，亦变作桑田。"]', '诗', 'shi', '', NULL, '香山居士寫真詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5b5dee-6348-46b1-bd96-e3241e4b958f', '二年三月五日齋畢開素當食偶吟贈妻弘農郡君', '二年三月五日斋畢开素當食偶吟贈妻弘農郡君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["睡足肢體暢，晨起開中堂。","初旭泛簾幕，微風拂衣裳。","二婢扶盥櫛，雙童舁簟牀。","庭東有茂樹，其下多陰涼。","前月事齋戒，昨日散道塲。","以我久蔬素，加籩仍異糧。","魴鱗白如雪，蒸炙加桂薑。","稻飯紅似花，調沃新酪漿。","佐以脯醢味，間之椒薤芳。","老憐口尚美，病喜鼻聞香。","嬌騃三四孫，索哺遶我傍。","山妻未舉案，饞叟已先嘗。","憶同牢巹初，家貧共糟糠。","今食且如此，何必烹猪羊。","況觀姻族間，夫妻半存亡。","偕老不易得，白頭何足傷。","食罷酒一杯，醉飽吟又狂。","緬想梁高士，樂道喜文章。","徒誇五噫作，不解贈孟光。"]', '["睡足肢體暢，晨起开中堂。","初旭泛簾幕，微风拂衣裳。","二婢扶盥櫛，雙童舁簟牀。","庭东有茂樹，其下多陰涼。","前月事斋戒，昨日散道塲。","以我久蔬素，加籩仍異糧。","魴鱗白如雪，蒸炙加桂薑。","稻飯紅似花，調沃新酪漿。","佐以脯醢味，间之椒薤芳。","老怜口尚美，病喜鼻闻香。","嬌騃三四孫，索哺遶我傍。","山妻未舉案，饞叟已先嘗。","憶同牢巹初，家貧共糟糠。","今食且如此，何必烹猪羊。","況观姻族间，夫妻半存亡。","偕老不易得，白头何足傷。","食罷酒一杯，醉飽吟又狂。","緬想梁高士，乐道喜文章。","徒誇五噫作，不解贈孟光。"]', '诗', 'shi', '', NULL, '二年三月五日齋畢開素當食偶吟贈妻弘農郡君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc043b1-d392-44da-89db-0d0508963b98', '不出門', '不出门', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["彌月不出門，永日無來賓。","食飽更拂牀，睡覺一嚬伸。","輕箑白鳥羽，新簟青箭筠。","方寸方丈室，空然兩無塵。","披衣腰不帶，散髮頭不巾。","袒跣北窗下，葛天之遺民。","一日亦自足，況得以終身。","不知天壤內，目我爲何人。"]', '["彌月不出门，永日無来賓。","食飽更拂牀，睡覺一嚬伸。","轻箑白鸟羽，新簟青箭筠。","方寸方丈室，空然兩無塵。","披衣腰不带，散髮头不巾。","袒跣北窗下，葛天之遺民。","一日亦自足，況得以終身。","不知天壤內，目我爲何人。"]', '诗', 'shi', '', NULL, '不出門 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42055eb8-47f9-4e96-b7a2-3a8d589ab55e', '感舊', '感旧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晦叔墳荒草已陳，夢得墓濕土猶新。","微之捐館將一紀，杓直歸丘二十春。","城中雖有故第宅，庭蕪園廢生荆榛。","篋中亦有舊書札，紙穿字蠹成灰塵。","平生定交取人窄，屈指相知唯五人。","四人先去我在後，一枝蒲柳衰殘身。","豈無晚歲新相識，相識面親心不親。","人生莫羨苦長命，命長感舊多悲辛。"]', '["晦叔墳荒草已陳，梦得墓濕土猶新。","微之捐館將一紀，杓直归丘二十春。","城中雖有故第宅，庭蕪园廢生荆榛。","篋中亦有旧书札，紙穿字蠹成灰塵。","平生定交取人窄，屈指相知唯五人。","四人先去我在後，一枝蒲柳衰殘身。","豈無晚歲新相識，相識面親心不親。","人生莫羨苦长命，命长感旧多悲辛。"]', '诗', 'shi', '', NULL, '感舊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eff07af-a1f2-4f18-8005-6e52e199feaf', '送毛仙翁', '送毛仙翁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["仙翁已得道，混迹尋巖泉。","肌膚冰雪瑩，衣服雲霞鮮。","紺髮絲竝緻，齠容花共妍。","方瞳點玄漆，高步凌非煙。","幾見桑海變，莫知龜鶴年。","所憩九清外，所遊五嶽巔。","軒昊舊爲侶，松喬難比肩。","每嗟人世人，役役如狂顛。","孰能脫羈鞅，盡遭名利牽。","貌隨歲律換，神逐光陰遷。","惟余負憂譴，顦顇湓江壖。","衰鬢忽霜白，愁腸如火煎。","羈旅坐多感，裴回私自憐。","晴眺五老峰，玉洞多神仙。","何當憫湮厄，授道安虛孱。","我師惠然來，論道窮重玄。","浩蕩八溟闊，志泰心超然。","形骸既無束，得喪亦都捐。","豈識椿菌異，那知鵬鷃懸。","丹華既相付，促景定當延。","玄功曷可報，感極惟勤拳。","霓旌不肯駐，又歸武夷川。","語罷倏然別，孤鶴升遙天。","賦詩敘明德，永續步虛篇。"]', '["仙翁已得道，混迹尋巖泉。","肌膚冰雪瑩，衣服云霞鲜。","紺髮絲竝緻，齠容花共妍。","方瞳点玄漆，高步凌非煙。","幾见桑海变，莫知龟鹤年。","所憩九清外，所游五嶽巔。","軒昊旧爲侶，松喬难比肩。","每嗟人世人，役役如狂顛。","孰能脫羈鞅，尽遭名利牽。","貌隨歲律換，神逐光陰遷。","惟余負憂譴，顦顇湓江壖。","衰鬢忽霜白，愁腸如火煎。","羈旅坐多感，裴回私自怜。","晴眺五老峰，玉洞多神仙。","何當憫湮厄，授道安虛孱。","我師惠然来，論道窮重玄。","浩蕩八溟闊，志泰心超然。","形骸既無束，得喪亦都捐。","豈識椿菌異，那知鵬鷃懸。","丹华既相付，促景定當延。","玄功曷可報，感極惟勤拳。","霓旌不肯駐，又归武夷川。","語罷倏然別，孤鹤升遙天。","賦诗敘明德，永續步虛篇。"]', '诗', 'shi', '', NULL, '送毛仙翁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c23701-e5b9-4d09-8f7b-8cbf63fd6bef', '達哉樂天行', '達哉乐天行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["達哉達哉白樂天，分司東都十三年。","七旬纔滿冠已挂，半祿未及車先懸。","或伴遊客春行樂，或隨山僧夜坐禪。","二年忘却問家事，門庭多草廚少煙。","庖童朝告鹽米盡，侍婢暮訴衣裳穿。","妻孥不悅甥姪悶，而我醉臥方陶然。","起來與爾畫生計，薄產處置有後先。","先賣南坊十畝園，次賣東都五頃田。","然後兼賣所居宅，髣髴獲緡二三千。","半與爾充衣食費，半與吾供酒肉錢。","吾今已年七十一，眼昏鬚白頭風眩。","但恐此錢用不盡，即先朝露歸夜泉。","未歸且住亦不惡，飢餐樂飲安穩眠。","死生無可無不可，達哉達哉白樂天。"]', '["達哉達哉白乐天，分司东都十三年。","七旬纔满冠已挂，半祿未及车先懸。","或伴游客春行乐，或隨山僧夜坐禪。","二年忘却问家事，门庭多草廚少煙。","庖童朝告鹽米尽，侍婢暮訴衣裳穿。","妻孥不悅甥姪悶，而我醉臥方陶然。","起来與爾畫生計，薄產处置有後先。","先賣南坊十畝园，次賣东都五頃田。","然後兼賣所居宅，髣髴獲緡二三千。","半與爾充衣食費，半與吾供酒肉錢。","吾今已年七十一，眼昏鬚白头风眩。","但恐此錢用不尽，即先朝露归夜泉。","未归且住亦不惡，飢餐乐饮安穩眠。","死生無可無不可，達哉達哉白乐天。"]', '诗', 'shi', '', NULL, '達哉樂天行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6e6ceb-d1ef-4306-b28c-77bb13bc09c3', '春池閑泛', '春池闲泛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綠塘新水平，紅檻小舟輕。","解纜隨風去，開襟信意行。","淺憐清演漾，深愛綠澄泓。","白撲柳飛絮，紅浮桃落英。","古文科斗出，新葉剪刀生。","樹集鶯朋友，雲行雁弟兄。","飛沈皆適性，酣詠自怡情。","花助銀杯氣，松添玉軫聲。","魚跳何事樂，鷗起復誰驚。","莫唱滄浪曲，無塵可濯纓。"]', '["綠塘新水平，紅檻小舟轻。","解纜隨风去，开襟信意行。","淺怜清演漾，深愛綠澄泓。","白撲柳飞絮，紅浮桃落英。","古文科斗出，新葉剪刀生。","樹集鶯朋友，云行雁弟兄。","飞沈皆適性，酣詠自怡情。","花助銀杯氣，松添玉軫声。","鱼跳何事乐，鷗起复誰驚。","莫唱滄浪曲，無塵可濯纓。"]', '诗', 'shi', '', NULL, '春池閑泛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08fd04f7-03bc-494c-8133-e2b2fccb8a86', '池上寓興二絕 一', '池上寓兴二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["濠梁莊惠謾相爭，未必人情知物情。","獺捕魚來魚躍出，此非魚樂是魚驚。"]', '["濠梁莊惠謾相爭，未必人情知物情。","獺捕鱼来鱼躍出，此非鱼乐是鱼驚。"]', '诗', 'shi', '', NULL, '池上寓興二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c58b14-e19a-4a38-8c1f-164c7548cbf0', '池上寓興二絕 二', '池上寓兴二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水淺魚稀白鷺飢，勞心瞪目待魚時。","外容閑暇中心苦，似是而非誰得知。"]', '["水淺鱼稀白鷺飢，勞心瞪目待鱼时。","外容闲暇中心苦，似是而非誰得知。"]', '诗', 'shi', '', NULL, '池上寓興二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e49ae42-d9be-46b1-bfc7-340d8c269f9b', '宴後題府中水堂贈盧尹中丞', '宴後題府中水堂贈盧尹中丞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水齋歲久漸荒蕪，自媿甘棠無一株。","新酒客來方宴飲，舊堂主在重歡娛。","莫言楊柳枝空老，直致櫻桃樹已枯。","從我到君十一尹，相看自置府來無。"]', '["水斋歲久漸荒蕪，自媿甘棠無一株。","新酒客来方宴饮，旧堂主在重歡娛。","莫言楊柳枝空老，直致櫻桃樹已枯。","從我到君十一尹，相看自置府来無。"]', '诗', 'shi', '', NULL, '宴後題府中水堂贈盧尹中丞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0179364d-9f50-4a11-92c5-50930a2ab52b', '和敏中洛下即事', '和敏中洛下即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日池塘春草生，阿連新有好詩成。","花園到處鶯呼入，驄馬遊時客避行。","水暖魚多似南國，人稀塵少勝西京。","洛中佳境應無限，若欲諳知問老兄。"]', '["昨日池塘春草生，阿連新有好诗成。","花园到处鶯呼入，驄马游时客避行。","水暖鱼多似南国，人稀塵少勝西京。","洛中佳境應無限，若欲諳知问老兄。"]', '诗', 'shi', '', NULL, '和敏中洛下即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0749174-6ec1-4175-8575-1a3024d7b7e3', '送敏中新授戶部員外郎西歸', '送敏中新授戶部員外郎西归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["千里歸程三伏天，官新身健馬翩翩。","行衝赤日加餐飯，上到青雲穩著鞭。","長慶老郎唯我在，客曹故事望君傳。","前鴻後雁行難續，相去迢迢二十年。"]', '["千里归程三伏天，官新身健马翩翩。","行衝赤日加餐飯，上到青云穩著鞭。","长慶老郎唯我在，客曹故事望君傳。","前鴻後雁行难續，相去迢迢二十年。"]', '诗', 'shi', '', NULL, '送敏中新授戶部員外郎西歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4865055-1a2e-4f5f-941b-f95be331fbbe', '南侍御以石相贈助成水聲因以絕句謝之', '南侍御以石相贈助成水声因以絕句謝之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["泉石磷磷聲似琴，閑眠靜聽洗塵心。","莫輕兩片青苔石，一夜潺湲直萬金。"]', '["泉石磷磷声似琴，闲眠静听洗塵心。","莫轻兩片青苔石，一夜潺湲直万金。"]', '诗', 'shi', '', NULL, '南侍御以石相贈助成水聲因以絕句謝之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('082a6c37-0bac-4c30-a5da-f6a849405a35', '閑居自題戲招宿客', '闲居自題戲招宿客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水畔竹林邊，閑居二十年。","健常攜酒出，病即掩門眠。","解綬收朝佩，褰裳出野船。","屏除身外物，擺落世間緣。","報曙窗何早，知秋簟最先。","微風深樹裏，斜日小樓前。","渠口添新石，籬根寫亂泉。","欲招同宿客，誰解愛潺湲。"]', '["水畔竹林邊，闲居二十年。","健常携酒出，病即掩门眠。","解綬收朝佩，褰裳出野船。","屏除身外物，擺落世间緣。","報曙窗何早，知秋簟最先。","微风深樹裏，斜日小楼前。","渠口添新石，籬根寫亂泉。","欲招同宿客，誰解愛潺湲。"]', '诗', 'shi', '', NULL, '閑居自題戲招宿客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8f48dc-3249-4f31-8129-46c3a5d2aaae', '李留守相公見過池上汎舟舉酒話及翰林舊事因成四韻以獻之', '李留守相公见過池上汎舟舉酒話及翰林旧事因成四韻以獻之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["引櫂尋池岸，移尊就菊叢。","何言濟川後，相訪釣船中。","白首故情在，青雲往事空。","同時六學士，五相一漁翁。"]', '["引櫂尋池岸，移尊就菊叢。","何言濟川後，相訪釣船中。","白首故情在，青云往事空。","同时六学士，五相一漁翁。"]', '诗', 'shi', '', NULL, '李留守相公見過池上汎舟舉酒話及翰林舊事因成四韻以獻之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5120b00c-fa68-4462-898d-c07ac6667d5a', '閏九月九日獨飲', '閏九月九日独饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃花叢畔綠尊前，猶有些些舊管弦。","偶遇閏秋重九日，東籬獨酌一陶然。","自從九月持齋戒，不醉重陽十五年。"]', '["黄花叢畔綠尊前，猶有些些旧管弦。","偶遇閏秋重九日，东籬独酌一陶然。","自從九月持斋戒，不醉重陽十五年。"]', '诗', 'shi', '', NULL, '閏九月九日獨飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f775eba-91d7-488a-9bb4-262b7c0d4ff9', '覽盧子蒙侍御舊詩多與微之唱和感今傷昔因贈子蒙題於卷後', '覽盧子蒙侍御旧诗多與微之唱和感今傷昔因贈子蒙題於卷後', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早聞元九詠君詩，恨與盧君相識遲。","今日逢君開舊卷，卷中多道贈微之。","相看掩淚情難說，別有傷心事豈知。","聞道咸陽墳上樹，已抽三丈白楊枝。"]', '["早闻元九詠君诗，恨與盧君相識遲。","今日逢君开旧卷，卷中多道贈微之。","相看掩泪情难说，別有傷心事豈知。","闻道咸陽墳上樹，已抽三丈白楊枝。"]', '诗', 'shi', '', NULL, '覽盧子蒙侍御舊詩多與微之唱和感今傷昔因贈子蒙題於卷後 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a9358c-97e9-4b26-8544-1c8d7a4d95f4', '寒亭留客', '寒亭留客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝閑坐石亭中，爐火銷殘尊又空。","冷落若爲留客住，冰池霜竹雪髯翁。"]', '["今朝闲坐石亭中，爐火銷殘尊又空。","冷落若爲留客住，冰池霜竹雪髯翁。"]', '诗', 'shi', '', NULL, '寒亭留客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33efe50e-e3d2-415a-ae26-40693e54effb', '新小灘', '新小灘', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["石淺沙平流水寒，水邊斜插一漁竿。","江南客見生鄉思，道似嚴陵七里灘。"]', '["石淺沙平流水寒，水邊斜插一漁竿。","江南客见生乡思，道似嚴陵七里灘。"]', '诗', 'shi', '', NULL, '新小灘 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d29545-881f-4df1-8b8c-68c0e53cba63', '和李中丞與李給事山居雪夜同宿小酌', '和李中丞與李給事山居雪夜同宿小酌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憲府觸邪峩豸角，璅闈駮正犯龍鱗。","那知近地齋居客，忽作深山同宿人。","一醆寒燈雲外夜，數杯溫酎雪中春。","林泉莫作多時計，諫獵登封憶舊臣。"]', '["憲府觸邪峩豸角，璅闈駮正犯龙鱗。","那知近地斋居客，忽作深山同宿人。","一醆寒灯云外夜，數杯溫酎雪中春。","林泉莫作多时計，諫獵登封憶旧臣。"]', '诗', 'shi', '', NULL, '和李中丞與李給事山居雪夜同宿小酌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('794aee47-3485-404b-937d-4fe645e25ecc', '履道西門二首 一', '履道西门二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["履道西門有弊居，池塘竹樹遶君廬。","豪華肥壯雖無分，飽暖安閑即有餘。","行竈朝香炊早飯，小園春暖掇新蔬。","夷齊黃綺誇芝蕨，比我盤飧恐不如。"]', '["履道西门有弊居，池塘竹樹遶君廬。","豪华肥壯雖無分，飽暖安闲即有餘。","行竈朝香炊早飯，小园春暖掇新蔬。","夷齊黄綺誇芝蕨，比我盤飧恐不如。"]', '诗', 'shi', '', NULL, '履道西門二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d132492-db5a-4180-9f63-7a1b1aae530b', '履道西門二首 二', '履道西门二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["履道西門獨掩扉，官休病退客來稀。","亦知軒冕榮堪戀，其奈田園老合歸。","跛鼈難隨騏驥足，傷禽莫趁鳳凰飛。","世間認得身人少，今我雖愚亦庶幾。"]', '["履道西门独掩扉，官休病退客来稀。","亦知軒冕榮堪戀，其奈田园老合归。","跛鼈难隨騏驥足，傷禽莫趁鳳凰飞。","世间認得身人少，今我雖愚亦庶幾。"]', '诗', 'shi', '', NULL, '履道西門二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8192802-0b10-454a-b2de-cd02f77da156', '偶吟', '偶吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人生變改故無窮，昔是朝官今野翁。","久寄形於朱紫內，漸抽身入蕙荷中。","無情水任方圓器，不繫舟隨去住風。","猶有鱸魚蓴菜興，來春或擬往江東。"]', '["人生变改故無窮，昔是朝官今野翁。","久寄形於朱紫內，漸抽身入蕙荷中。","無情水任方圓器，不繫舟隨去住风。","猶有鱸鱼蓴菜兴，来春或擬往江东。"]', '诗', 'shi', '', NULL, '偶吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6152c59d-4395-44a2-bd16-dc41ae592ec6', '雪夜小飲贈夢得', '雪夜小饮贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["同爲懶慢園林客，共對蕭條雨雪天。","小酌酒巡銷永夜，大開口笑送殘年。","久將時背成遺老，多被人呼作散仙。","呼作散仙應有以，曾看東海變桑田。"]', '["同爲懶慢园林客，共对蕭條雨雪天。","小酌酒巡銷永夜，大开口笑送殘年。","久將时背成遺老，多被人呼作散仙。","呼作散仙應有以，曾看东海变桑田。"]', '诗', 'shi', '', NULL, '雪夜小飲贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8928077e-9d75-4c1f-8c74-37a87129a364', '歲暮夜長病中燈下聞盧尹夜宴以詩戲之且爲來日張本也', '歲暮夜长病中灯下闻盧尹夜宴以诗戲之且爲来日張本也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["榮鬧興多嫌晝短，衰閑睡少覺明遲。","當君秉燭銜杯夜，是我停飱服藥時。","枕上愁吟堪發病，府中歡笑勝尋醫。","明朝強出須謀樂，不擬車公更擬誰。"]', '["榮鬧兴多嫌晝短，衰闲睡少覺明遲。","當君秉燭銜杯夜，是我停飱服藥时。","枕上愁吟堪發病，府中歡笑勝尋醫。","明朝強出須謀乐，不擬车公更擬誰。"]', '诗', 'shi', '', NULL, '歲暮夜長病中燈下聞盧尹夜宴以詩戲之且爲來日張本也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a3f084-0ca8-4261-ae65-6a94e416c149', '病中數會張道士見譏以此荅之', '病中數會張道士见譏以此荅之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亦知數出妨將息，不可端居守寂寥。","病即藥窗眠盡日，興來酒席坐通宵。","賢人易狎須勤飲，姹女難禁莫慢燒。","張道士輸白道士，一杯沆[瀣]便逍遙。"]', '["亦知數出妨將息，不可端居守寂寥。","病即藥窗眠尽日，兴来酒席坐通宵。","賢人易狎須勤饮，姹女难禁莫慢燒。","張道士輸白道士，一杯沆[瀣]便逍遙。"]', '诗', 'shi', '', NULL, '病中數會張道士見譏以此荅之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2877437-d920-462c-83f6-0dadfd75ddb4', '卯飲', '卯饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["短屏風掩臥牀頭，烏帽青氈白氎裘。","卯飲一杯眠一覺，世間何事不悠悠。"]', '["短屏风掩臥牀头，烏帽青氈白氎裘。","卯饮一杯眠一覺，世间何事不悠悠。"]', '诗', 'shi', '', NULL, '卯飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8ad939-d581-4971-83b3-160b1486a2b5', '寄題餘杭郡樓兼呈裴使君', '寄題餘杭郡楼兼呈裴使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官歷二十政，宦遊三十秋。","江山與風月，最憶是杭州。","北郭沙堤尾，西湖石岸頭。","綠觴春送客，紅燭夜迴舟。","不敢言遺愛，空知念舊遊。","憑君吟此句，題向望濤樓。"]', '["官歷二十政，宦游三十秋。","江山與风月，最憶是杭州。","北郭沙堤尾，西湖石岸头。","綠觴春送客，紅燭夜迴舟。","不敢言遺愛，空知念旧游。","憑君吟此句，題向望濤楼。"]', '诗', 'shi', '', NULL, '寄題餘杭郡樓兼呈裴使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7850e71-638c-44b5-afb9-20711128689a', '楊六尚書留太湖石在洛下借置庭中因對舉杯寄贈絕句', '楊六尚书留太湖石在洛下借置庭中因对舉杯寄贈絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["借君片石意何如，置向庭中慰索居。","每就玉山傾一酌，興來如對醉尚書。"]', '["借君片石意何如，置向庭中慰索居。","每就玉山傾一酌，兴来如对醉尚书。"]', '诗', 'shi', '', NULL, '楊六尚書留太湖石在洛下借置庭中因對舉杯寄贈絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82df3c38-2c9c-4f49-8b15-eadee48768b0', '喜入新年自詠', '喜入新年自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白鬚如雪五朝臣，又值新正第七旬。","老過占他藍尾酒，病餘收得到頭身。","銷磨歲月成高位，比類時流是幸人。","大曆年中騎竹馬，幾人得見會昌春。"]', '["白鬚如雪五朝臣，又值新正第七旬。","老過占他藍尾酒，病餘收得到头身。","銷磨歲月成高位，比類时流是幸人。","大曆年中騎竹马，幾人得见會昌春。"]', '诗', 'shi', '', NULL, '喜入新年自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a3040d4-3a16-42cb-b6e7-4e0c3787690e', '灘聲', '灘声', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧玉班班沙歷歷，清流決決響泠泠。","自從造得灘聲後，玉管朱弦可要聽。"]', '["碧玉班班沙歷歷，清流決決响泠泠。","自從造得灘声後，玉管朱弦可要听。"]', '诗', 'shi', '', NULL, '灘聲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6998855b-5b00-4420-a682-18d61b593a66', '題石泉', '題石泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["殷勤傍石遶泉行，不說何人知我情。","漸恐耳聾兼眼闇，聽泉看石不分明。"]', '["殷勤傍石遶泉行，不说何人知我情。","漸恐耳聾兼眼闇，听泉看石不分明。"]', '诗', 'shi', '', NULL, '題石泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('158c5988-604e-43c9-bcc3-e589ac79fe74', '送王卿使君赴任蘇州因思花迎新使感舊遊寄題郡中木蘭西院一別', '送王卿使君赴任蘇州因思花迎新使感旧游寄題郡中木蘭西院一別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一別蘇州十八載，時光人事隨年改。","不論竹馬盡成人，亦恐桑田半爲海。","鶯入故宮含意思，花迎新使生光彩。","爲報江山風月知，至今白使君猶在。"]', '["一別蘇州十八載，时光人事隨年改。","不論竹马尽成人，亦恐桑田半爲海。","鶯入故宮含意思，花迎新使生光彩。","爲報江山风月知，至今白使君猶在。"]', '诗', 'shi', '', NULL, '送王卿使君赴任蘇州因思花迎新使感舊遊寄題郡中木蘭西院一別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba83d2f-f177-4102-8284-803165ebba9a', '出齋日喜皇甫十早訪', '出斋日喜皇甫十早訪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三旬齋滿欲銜杯，平旦敲門門未開。","除却朗之攜一榼，的應不是別人來。"]', '["三旬斋满欲銜杯，平旦敲门门未开。","除却朗之携一榼，的應不是別人来。"]', '诗', 'shi', '', NULL, '出齋日喜皇甫十早訪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2304b84e-e4a1-40df-ab81-71ff5afeab7d', '會昌二年春題池西小樓', '會昌二年春題池西小楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花邊春水水邊樓，一坐經今四十秋。","望月橋傾三遍換，採蓮船破五迴修。","園林一半成喬木，鄰里三分作白頭。","蘇李冥蒙隨燭滅，陳樊漂泊逐萍流。","雖貧眼下無妨樂，縱病心中不與愁。","自笑靈光巋然在，春來遊得且須遊。"]', '["花邊春水水邊楼，一坐經今四十秋。","望月橋傾三遍換，採蓮船破五迴修。","园林一半成喬木，鄰里三分作白头。","蘇李冥蒙隨燭滅，陳樊漂泊逐萍流。","雖貧眼下無妨乐，縱病心中不與愁。","自笑靈光巋然在，春来游得且須游。"]', '诗', 'shi', '', NULL, '會昌二年春題池西小樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93e0804c-e811-4f25-85d4-d97476cf82b8', '酬南洛陽早春見贈', '酬南洛陽早春见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["物華春意尚遲迴，賴有東風晝夜催。","寒縋柳腰收未得，暖熏花口噤初開。","欲披雲霧聯襟去，先喜瓊琚入袖來。","久病長齋詩老退，爭禁年少洛陽才。"]', '["物华春意尚遲迴，賴有东风晝夜催。","寒縋柳腰收未得，暖熏花口噤初开。","欲披云霧聯襟去，先喜瓊琚入袖来。","久病长斋诗老退，爭禁年少洛陽才。"]', '诗', 'shi', '', NULL, '酬南洛陽早春見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e2a973-4bbe-442e-af19-035a46724a81', '對新家醖翫自種花', '对新家醖翫自種花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香麴親看造，芳叢手自栽。","迎春報酒熟，垂老看花開。","紅蠟半含萼，綠油新醱醅。","玲瓏五六樹，瀲灩兩三杯。","恐有狂風起，愁無好客來。","獨酣還獨語，待取月明迴。"]', '["香麴親看造，芳叢手自栽。","迎春報酒熟，垂老看花开。","紅蠟半含萼，綠油新醱醅。","玲瓏五六樹，瀲灩兩三杯。","恐有狂风起，愁無好客来。","独酣還独語，待取月明迴。"]', '诗', 'shi', '', NULL, '對新家醖翫自種花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b3436d-e795-4402-b9a7-e0c379194558', '攜酒往朗之莊居同飲', '携酒往朗之莊居同饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慵中又少經過處，別後都無勸酒人。","不挈一壺相就醉，若爲將老度殘春。"]', '["慵中又少經過处，別後都無勸酒人。","不挈一壺相就醉，若爲將老度殘春。"]', '诗', 'shi', '', NULL, '攜酒往朗之莊居同飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685acda4-7696-4bf9-b447-d44243fb3beb', '以詩代書酬慕巢尚書見寄', '以诗代书酬慕巢尚书见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["書意詩情不偶然，苦云夢想在林泉。","願爲愚谷煙霞侶，思結空門香火緣。","每媿尚書情眷眷，自憐居士病綿綿。","不知待得心期否，老挍於君六七年。"]', '["书意诗情不偶然，苦云梦想在林泉。","願爲愚谷煙霞侶，思結空门香火緣。","每媿尚书情眷眷，自怜居士病綿綿。","不知待得心期否，老挍於君六七年。"]', '诗', 'shi', '', NULL, '以詩代書酬慕巢尚書見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a6762be-e8e3-4efb-891f-aa24a781036e', '春盡日', '春尽日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["芳景銷殘暑氣生，感時思事坐含情。","無人開口共誰語，有酒迴頭還自傾。","醉對數叢紅芍藥，渴嘗一盌綠昌明。","春歸似遣鶯留語，好住園林三兩聲。"]', '["芳景銷殘暑氣生，感时思事坐含情。","無人开口共誰語，有酒迴头還自傾。","醉对數叢紅芍藥，渴嘗一盌綠昌明。","春归似遣鶯留語，好住园林三兩声。"]', '诗', 'shi', '', NULL, '春盡日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('188d655e-92f3-4f2a-8117-ae0509bb6913', '招山僧', '招山僧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["能入城中乞食否，莫辭塵土汚袈裟。","欲知住處東城下，遶竹泉聲是白家。"]', '["能入城中乞食否，莫辞塵土汚袈裟。","欲知住处东城下，遶竹泉声是白家。"]', '诗', 'shi', '', NULL, '招山僧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e8cf97-5869-49d3-abf4-17203db5ff9c', '夏日與閑禪師林下避暑', '夏日與闲禪師林下避暑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛景城西塵土紅，伴僧閑坐竹泉東。","綠蘿潭上不見日，白石灘邊長有風。","熱惱漸知隨念盡，清涼常願與人同。","每因毒暑悲親故，多在炎方瘴海中。"]', '["洛景城西塵土紅，伴僧闲坐竹泉东。","綠蘿潭上不见日，白石灘邊长有风。","熱惱漸知隨念尽，清涼常願與人同。","每因毒暑悲親故，多在炎方瘴海中。"]', '诗', 'shi', '', NULL, '夏日與閑禪師林下避暑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e332be3-de5c-40ec-99e0-8e5338727888', '題新澗亭兼酬寄朝中親故見贈', '題新澗亭兼酬寄朝中親故见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處披襟風快哉，一亭臨澗四門開。","金章紫綬辭腰去，白石清泉就眼來。","自得所宜還獨樂，各行其志莫相咍。","禽魚出得池籠後，縱有人呼可更迴。"]', '["何处披襟风快哉，一亭臨澗四门开。","金章紫綬辞腰去，白石清泉就眼来。","自得所宜還独乐，各行其志莫相咍。","禽鱼出得池籠後，縱有人呼可更迴。"]', '诗', 'shi', '', NULL, '題新澗亭兼酬寄朝中親故見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c93da7da-b27e-4303-9fe3-76fcf2d5bebc', '病中看經贈諸道侶', '病中看經贈諸道侶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["右眼昏花左足風，金箆石水用無功。","不如迴念三乘樂，便得浮生百病空。","無子同居草庵下，有妻偕老道塲中。","何煩更請僧爲侶，月上新歸伴病翁。"]', '["右眼昏花左足风，金箆石水用無功。","不如迴念三乘乐，便得浮生百病空。","無子同居草庵下，有妻偕老道塲中。","何煩更請僧爲侶，月上新归伴病翁。"]', '诗', 'shi', '', NULL, '病中看經贈諸道侶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8097d5e2-11b7-460c-92bd-415035fe753c', '遊豐樂招提佛光三寺', '游豐乐招提佛光三寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竹鞋葵扇白綃巾，林野爲家雲是身。","山寺每遊多寄宿，都城暫出即經旬。","漢容黃綺爲逋客，堯放巢由作外臣。","昨日制書臨郡縣，不該愚谷醉鄉人。"]', '["竹鞋葵扇白綃巾，林野爲家云是身。","山寺每游多寄宿，都城暫出即經旬。","漢容黄綺爲逋客，堯放巢由作外臣。","昨日制书臨郡縣，不該愚谷醉乡人。"]', '诗', 'shi', '', NULL, '遊豐樂招提佛光三寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f09ea8f-507a-4dcf-ad70-d53af9c71a37', '醉中得上都親友書以予停俸多時憂問貧乏偶乘酒興詠而報之', '醉中得上都親友书以予停俸多时憂问貧乏偶乘酒兴詠而報之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頭白醉昏昏，狂歌秋復春。","一生躭酒客，五度棄官人。","異世陶元亮，前生劉伯倫。","臥將琴作枕，行以鍤隨身。","歲要衣三對，年支穀一囷。","園葵烹佐飯，林葉掃添薪。","沒齒甘蔬食，搖頭謝縉紳。","自能拋爵祿，終不惱交親。","但得杯中淥，從生甑上塵。","煩君問生計，憂醒不憂貧。"]', '["头白醉昏昏，狂歌秋复春。","一生躭酒客，五度棄官人。","異世陶元亮，前生劉伯倫。","臥將琴作枕，行以鍤隨身。","歲要衣三对，年支穀一囷。","园葵烹佐飯，林葉掃添薪。","沒齒甘蔬食，搖头謝縉紳。","自能拋爵祿，終不惱交親。","但得杯中淥，從生甑上塵。","煩君问生計，憂醒不憂貧。"]', '诗', 'shi', '', NULL, '醉中得上都親友書以予停俸多時憂問貧乏偶乘酒興詠而報之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0cb09d2-3358-44e5-be2e-726af69ef62a', '池畔逐涼', '池畔逐涼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風清泉冷竹修修，三伏炎天涼似秋。","黃犬引迎騎馬客，青衣扶下釣魚舟。","衰容自覺宜閑坐，蹇步誰能更遠遊。","料得此身終老處，只應林下與灘頭。"]', '["风清泉冷竹修修，三伏炎天涼似秋。","黄犬引迎騎马客，青衣扶下釣鱼舟。","衰容自覺宜闲坐，蹇步誰能更远游。","料得此身終老处，只應林下與灘头。"]', '诗', 'shi', '', NULL, '池畔逐涼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d3fe026-11a9-4d6b-9bf3-bbe49276b374', '池鶴八絕句 雞贈鶴', '池鹤八絕句 雞贈鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一聲警露君能薄，五德司晨我用多。","不會悠悠時俗士，重君輕我意如何。"]', '["一声警露君能薄，五德司晨我用多。","不會悠悠时俗士，重君轻我意如何。"]', '诗', 'shi', '', NULL, '池鶴八絕句 雞贈鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0999cda8-ebab-4382-a8c7-c49af103fecc', '池鶴八絕句 鶴荅雞', '池鹤八絕句 鹤荅雞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爾爭伉儷泥中鬬，吾整羽儀松上栖。","不可遣他天下眼，却輕野鶴重家雞。"]', '["爾爭伉儷泥中鬬，吾整羽儀松上栖。","不可遣他天下眼，却轻野鹤重家雞。"]', '诗', 'shi', '', NULL, '池鶴八絕句 鶴荅雞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b711aeea-80d7-49a6-9e92-d1b89d5ce540', '池鶴八絕句 烏贈鶴', '池鹤八絕句 烏贈鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["與君白黑大分明，縱不相親莫見輕。","我每夜啼君怨別，玉徽琴裏忝同聲。"]', '["與君白黑大分明，縱不相親莫见轻。","我每夜啼君怨別，玉徽琴裏忝同声。"]', '诗', 'shi', '', NULL, '池鶴八絕句 烏贈鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44a01b43-d5b8-456e-89b2-90bd3d18e949', '池鶴八絕句 鶴荅烏', '池鹤八絕句 鹤荅烏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾愛栖雲上華表，汝多攫肉下田中。","吾音中羽汝聲角，琴曲雖同調不同。"]', '["吾愛栖云上华表，汝多攫肉下田中。","吾音中羽汝声角，琴曲雖同調不同。"]', '诗', 'shi', '', NULL, '池鶴八絕句 鶴荅烏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24b60be4-d7e7-4e75-b28f-bed4ebc4ae08', '池鶴八絕句 鳶贈鶴', '池鹤八絕句 鳶贈鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君誇名鶴我名鳶，君呌聞天我戾天。","更有與君相似處，飢來一種啄腥羶。"]', '["君誇名鹤我名鳶，君呌闻天我戾天。","更有與君相似处，飢来一種啄腥羶。"]', '诗', 'shi', '', NULL, '池鶴八絕句 鳶贈鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee844dd0-3101-4d63-b000-22d5d1b6e1de', '池鶴八絕句 鶴荅鳶', '池鹤八絕句 鹤荅鳶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["無妨自是莫相非，清濁高低各有歸。","鸞鶴羣中彩雲裏，幾時曾見喘鳶飛。"]', '["無妨自是莫相非，清濁高低各有归。","鸾鹤羣中彩云裏，幾时曾见喘鳶飞。"]', '诗', 'shi', '', NULL, '池鶴八絕句 鶴荅鳶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4eeb15-a82e-4f15-836a-5729e0ee8834', '池鶴八絕句 鵝贈鶴', '池鹤八絕句 鵝贈鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君因風送入青雲，我被人驅向鴨羣。","雪頸霜毛紅網掌，請看何處不如君。"]', '["君因风送入青云，我被人驱向鴨羣。","雪頸霜毛紅網掌，請看何处不如君。"]', '诗', 'shi', '', NULL, '池鶴八絕句 鵝贈鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc31168d-7b68-49f1-9ac0-a0dcaa1c2308', '池鶴八絕句 鶴荅鵝', '池鹤八絕句 鹤荅鵝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["右軍歿後欲何依，只合隨雞逐鴨飛。","未必犧牲及吾輩，大都我瘦勝君肥。"]', '["右軍歿後欲何依，只合隨雞逐鴨飞。","未必犧牲及吾輩，大都我瘦勝君肥。"]', '诗', 'shi', '', NULL, '池鶴八絕句 鶴荅鵝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094a6992-bb68-40ae-b6f8-3460a32612cd', '談氏小外孫玉童', '談氏小外孫玉童', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["外翁七十孫三歲，笑指琴書欲遣傳。","自念老夫今耄矣，因思稚子更茫然。","中郎餘慶鍾羊祜，子幼能文似馬遷。","才與不才爭料得，東牀空後且嬌憐。"]', '["外翁七十孫三歲，笑指琴书欲遣傳。","自念老夫今耄矣，因思稚子更茫然。","中郎餘慶鍾羊祜，子幼能文似马遷。","才與不才爭料得，东牀空後且嬌怜。"]', '诗', 'shi', '', NULL, '談氏小外孫玉童 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea60b4c2-f2f4-42b6-8f84-197a061aec66', '送後集往廬山東林寺兼寄雲臯上人', '送後集往廬山东林寺兼寄云臯上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["後集寄將何處去，故山迢遞在匡廬。","舊僧獨有雲臯在，三二年來不得書。","別後道情添幾許，老來筋力又何如。","來生緣會應非遠，彼此年過七十餘。"]', '["後集寄將何处去，故山迢遞在匡廬。","旧僧独有云臯在，三二年来不得书。","別後道情添幾許，老来筋力又何如。","来生緣會應非远，彼此年過七十餘。"]', '诗', 'shi', '', NULL, '送後集往廬山東林寺兼寄雲臯上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d15fcaaf-1af2-419d-ae5f-47b7ff296266', '客有說', '客有说', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["近有人從海上迴，海山深處見樓臺。","中有仙龕虛一室，多傳此待樂天來。"]', '["近有人從海上迴，海山深处见楼台。","中有仙龕虛一室，多傳此待乐天来。"]', '诗', 'shi', '', NULL, '客有說 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da1f1f2-06c1-4f74-8e64-8cf2b9bcb40d', '荅客說', '荅客说', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾學空門非學仙，恐君此說是虛傳。","海山不是吾歸處，歸即應歸兜率天。"]', '["吾学空门非学仙，恐君此说是虛傳。","海山不是吾归处，归即應归兜率天。"]', '诗', 'shi', '', NULL, '荅客說 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdfa7bac-a4b3-47d1-948c-9cd209a10415', '哭劉尚書夢得二首 一', '哭劉尚书梦得二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四海齊名白與劉，百年交分兩綢繆。","同貧同病退閑日，一死一生臨老頭。","杯酒英雄君與操，文章微婉我知丘。","賢豪雖歿精靈在，應共微之地下遊。"]', '["四海齊名白與劉，百年交分兩綢繆。","同貧同病退闲日，一死一生臨老头。","杯酒英雄君與操，文章微婉我知丘。","賢豪雖歿精靈在，應共微之地下游。"]', '诗', 'shi', '', NULL, '哭劉尚書夢得二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f4ff067-5d18-45a9-9212-f1cff9b73ea8', '哭劉尚書夢得二首 二', '哭劉尚书梦得二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今日哭君吾道孤，寢門淚滿白髭鬚。","不知箭折弓何用，兼恐脣亡齒亦枯。","窅窅窮泉埋寶玉，駸駸落景挂桑榆。","夜臺暮齒期非遠，但問前頭相見無。"]', '["今日哭君吾道孤，寢门泪满白髭鬚。","不知箭折弓何用，兼恐脣亡齒亦枯。","窅窅窮泉埋寶玉，駸駸落景挂桑榆。","夜台暮齒期非远，但问前头相见無。"]', '诗', 'shi', '', NULL, '哭劉尚書夢得二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f08c95-dbff-4fb9-89ef-0a16df2bf340', '昨日復今辰', '昨日复今辰', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日復今辰，悠悠七十春。","所經多故處，却想似前身。","散秩優游老，閑居淨潔貧。","螺杯中有物，鶴氅上無塵。","解佩收朝帶，抽簪換野巾。","風儀與名號，別是一生人。"]', '["昨日复今辰，悠悠七十春。","所經多故处，却想似前身。","散秩優游老，闲居淨潔貧。","螺杯中有物，鹤氅上無塵。","解佩收朝带，抽簪換野巾。","风儀與名號，別是一生人。"]', '诗', 'shi', '', NULL, '昨日復今辰 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f61fc5-a49d-47fa-9e6d-e0ec3ebe031d', '病瘡', '病瘡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["門有醫來往，庭無客送迎。","病銷談笑興，老足歎嗟聲。","鶴伴臨池立，人扶下砌行。","脚瘡春斷酒，那得有心情。"]', '["门有醫来往，庭無客送迎。","病銷談笑兴，老足歎嗟声。","鹤伴臨池立，人扶下砌行。","脚瘡春斷酒，那得有心情。"]', '诗', 'shi', '', NULL, '病瘡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('478242d8-75dd-4b83-8fc3-a98d98028d8e', '遊趙村杏花', '游趙村杏花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["趙村紅杏每年開，十五年來看幾迴。","七十三人難再到，今春來是別花來。"]', '["趙村紅杏每年开，十五年来看幾迴。","七十三人难再到，今春来是別花来。"]', '诗', 'shi', '', NULL, '遊趙村杏花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd281576-53f9-4fd1-b357-d9711a869731', '刑部尚書致仕', '刑部尚书致仕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十五年來洛下居，道緣俗累兩何如。","迷路心迴因向佛，宦途事了是懸車。","全家遁世曾無悶，半俸資身亦有餘。","唯是名銜人不會，毘耶長者白尚書。"]', '["十五年来洛下居，道緣俗累兩何如。","迷路心迴因向佛，宦途事了是懸车。","全家遁世曾無悶，半俸資身亦有餘。","唯是名銜人不會，毘耶长者白尚书。"]', '诗', 'shi', '', NULL, '刑部尚書致仕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f2be5cc-3532-4e1a-8573-21ac552788f0', '初致仕後戲酬留守牛相公幷呈分司諸寮友', '初致仕後戲酬留守牛相公幷呈分司諸寮友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南北東西無所羈，挂冠目在勝分司。","探花嘗酒多先到，拜表行香盡不知。","炮筍烹魚飽飱後，擁袍枕臂醉眠時。","報君一語君應笑，兼亦無心羨保釐。"]', '["南北东西無所羈，挂冠目在勝分司。","探花嘗酒多先到，拜表行香尽不知。","炮筍烹鱼飽飱後，擁袍枕臂醉眠时。","報君一語君應笑，兼亦無心羨保釐。"]', '诗', 'shi', '', NULL, '初致仕後戲酬留守牛相公幷呈分司諸寮友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dae29e2-46d7-4221-86ba-714d0056c616', '問諸親友', '问諸親友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七十人難到，過三更較稀。","占花租野寺，定酒典朝衣。","趁醉春多出，貪歡夜未歸。","不知親故口，道我是耶非。"]', '["七十人难到，過三更較稀。","占花租野寺，定酒典朝衣。","趁醉春多出，貪歡夜未归。","不知親故口，道我是耶非。"]', '诗', 'shi', '', NULL, '問諸親友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf43a47a-103e-477a-9bed-1a4a5a6236a9', '戲問牛司徒', '戲问牛司徒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["抖擻塵纓捋白鬚，半酣扶起問司徒。","不知詔下懸車後，醉舞狂歌有例無。"]', '["抖擻塵纓捋白鬚，半酣扶起问司徒。","不知詔下懸车後，醉舞狂歌有例無。"]', '诗', 'shi', '', NULL, '戲問牛司徒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b518bde9-459f-468d-8b11-f5ff50ee3c8c', '不與老爲期', '不與老爲期', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不與老爲期，因何兩鬢絲。","纔應免夭促，便已及衰羸。","昨夜夢何在，明朝身不知。","百憂非我所，三樂是吾師。","閉目常閑坐，低頭每靜思。","存神機慮息，養氣語言遲。","行亦攜詩篋，眠多枕酒巵。","自慙無一事，少有不安時。"]', '["不與老爲期，因何兩鬢絲。","纔應免夭促，便已及衰羸。","昨夜梦何在，明朝身不知。","百憂非我所，三乐是吾師。","閉目常闲坐，低头每静思。","存神機慮息，養氣語言遲。","行亦携诗篋，眠多枕酒巵。","自慙無一事，少有不安时。"]', '诗', 'shi', '', NULL, '不與老爲期 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de74506-3b4f-4105-b375-42ada59afd02', '開龍門八節石灘詩二首 一', '开龙门八節石灘诗二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鐵鑿金鎚殷若雷，八灘九石劒稜摧。","竹篙桂檝飛如箭，百筏千艘魚貫來。","振錫導師憑衆力，揮金退傅施家財。","他時相逐西方去，莫慮塵沙路不開。"]', '["鐵鑿金鎚殷若雷，八灘九石劒稜摧。","竹篙桂檝飞如箭，百筏千艘鱼貫来。","振錫導師憑衆力，揮金退傅施家財。","他时相逐西方去，莫慮塵沙路不开。"]', '诗', 'shi', '', NULL, '開龍門八節石灘詩二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628117b3-3f1b-455e-b52f-9d109e0e1bed', '開龍門八節石灘詩二首 二', '开龙门八節石灘诗二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七十三翁旦暮身，誓開險路作通津。","夜舟過此無傾覆，朝脛從今免苦辛。","十里叱灘變河漢，八寒陰獄化陽春。","我身雖歿心長在，闇施慈悲與後人。"]', '["七十三翁旦暮身，誓开險路作通津。","夜舟過此無傾覆，朝脛從今免苦辛。","十里叱灘变河漢，八寒陰獄化陽春。","我身雖歿心长在，闇施慈悲與後人。"]', '诗', 'shi', '', NULL, '開龍門八節石灘詩二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61c8f5e-b2f8-492d-b8e2-8de4281bd62b', '閑坐', '闲坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["婆娑放雞犬，嬉戲任兒童。","閑坐槐陰下，開襟向晚風。","漚麻池水裏，曬棗日陽中。","人物何相稱，居然田舍翁。"]', '["婆娑放雞犬，嬉戲任兒童。","闲坐槐陰下，开襟向晚风。","漚麻池水裏，曬棗日陽中。","人物何相稱，居然田舍翁。"]', '诗', 'shi', '', NULL, '閑坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52a15d7-0a05-407f-b78e-ed5e0a4fcffb', '酬寄牛相公同宿話舊勸酒見贈', '酬寄牛相公同宿話旧勸酒见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["每來政事堂中宿，共憶華陽觀裏時。","日暮獨歸愁米盡，泥深同出借驢騎。","交遊今日唯殘我，富貴當年更有誰。","彼此相看頭雪白，一杯可合重推辭。"]', '["每来政事堂中宿，共憶华陽观裏时。","日暮独归愁米尽，泥深同出借驢騎。","交游今日唯殘我，富貴當年更有誰。","彼此相看头雪白，一杯可合重推辞。"]', '诗', 'shi', '', NULL, '酬寄牛相公同宿話舊勸酒見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da1708b-ddc7-4158-b886-8d511a9be33d', '道場獨坐', '道場独坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["整頓衣巾拂淨牀，一瓶秋水一爐香。","不論煩惱先須去，直到菩提亦擬忘。","朝謁久停收劒珮，宴遊漸罷廢壺觴。","世間無用殘年處，祗合逍遙坐道場。"]', '["整頓衣巾拂淨牀，一瓶秋水一爐香。","不論煩惱先須去，直到菩提亦擬忘。","朝謁久停收劒珮，宴游漸罷廢壺觴。","世间無用殘年处，祗合逍遙坐道場。"]', '诗', 'shi', '', NULL, '道場獨坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a802a703-65e1-4ce6-afa8-72120017b7a5', '偶作寄朗之', '偶作寄朗之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歷想爲官日，無如刺史時。","歡娛接賓客，飽暖及妻兒。","自到東都後，安閑更得宜。","分司勝刺史，致仕勝分司。","何況園林下，欣然得朗之。","仰名同舊識，爲樂即新知。","有雪先相訪，無花不作期。","鬬醲乾釀酒，誇妙細吟詩。","里巷千來往，都門五別離。","岐分兩迴首，書到一開眉。","葉落槐亭院，冰生竹閣池。","雀羅誰問訊，鶴氅罷追隨。","身與心俱病，容將力共衰。","老來多健忘，唯不忘相思。"]', '["歷想爲官日，無如刺史时。","歡娛接賓客，飽暖及妻兒。","自到东都後，安闲更得宜。","分司勝刺史，致仕勝分司。","何況园林下，欣然得朗之。","仰名同旧識，爲乐即新知。","有雪先相訪，無花不作期。","鬬醲乾釀酒，誇妙細吟诗。","里巷千来往，都门五別離。","岐分兩迴首，书到一开眉。","葉落槐亭院，冰生竹閣池。","雀羅誰问訊，鹤氅罷追隨。","身與心俱病，容將力共衰。","老来多健忘，唯不忘相思。"]', '诗', 'shi', '', NULL, '偶作寄朗之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1860092-967c-47e0-aced-98686ee642b9', '狂吟七言十四韻', '狂吟七言十四韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亦知世是休明世，自想身非富貴身。","但恐人間爲長物，不如林下作遺民。","遊依二室成三友，住近雙林當四鄰。","性海澄渟平少浪，心田灑掃淨無塵。","香山閑宿一千夜，梓澤連遊十六春。","是客相逢皆故舊，無僧每見不殷勤。","藥停有喜閑銷疾，金盡無憂醉忘貧。","補綻衣裳媿妻女，支持酒肉賴交親。","俸隨日計錢盈貫，祿逐年支粟滿囷。","洛堰魚鮮供取足，遊村果熟饋爭新。","詩章人與傳千首，壽命天教過七旬。","點檢一生徼倖事，東都除我更無人。"]', '["亦知世是休明世，自想身非富貴身。","但恐人间爲长物，不如林下作遺民。","游依二室成三友，住近雙林當四鄰。","性海澄渟平少浪，心田灑掃淨無塵。","香山闲宿一千夜，梓澤連游十六春。","是客相逢皆故旧，無僧每见不殷勤。","藥停有喜闲銷疾，金尽無憂醉忘貧。","補綻衣裳媿妻女，支持酒肉賴交親。","俸隨日計錢盈貫，祿逐年支粟满囷。","洛堰鱼鲜供取足，游村果熟饋爭新。","诗章人與傳千首，壽命天教過七旬。","点檢一生徼倖事，东都除我更無人。"]', '诗', 'shi', '', NULL, '狂吟七言十四韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888d666c-05ff-41b0-b6c9-e36e23d2f61f', '喜裴濤使君攜詩見訪醉中戲贈', '喜裴濤使君携诗见訪醉中戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽聞扣戶醉吟聲，不覺停杯倒屣迎。","共放詩狂同酒癖，與君別是一親情。"]', '["忽闻扣戶醉吟声，不覺停杯倒屣迎。","共放诗狂同酒癖，與君別是一親情。"]', '诗', 'shi', '', NULL, '喜裴濤使君攜詩見訪醉中戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92bcb1bd-6d78-47b3-b2f9-36374483a7e2', '得潮州楊相公繼之書幷詩以此寄之', '得潮州楊相公繼之书幷诗以此寄之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["詩情書意兩殷勤，來自天南瘴海濱。","初覩銀鉤還啓齒，細吟瓊什欲霑巾。","鳳池隔絕三千里，蝸舍沈冥十五春。","唯有新昌故園月，至今分照兩鄉人。"]', '["诗情书意兩殷勤，来自天南瘴海濱。","初覩銀鉤還啓齒，細吟瓊什欲霑巾。","鳳池隔絕三千里，蝸舍沈冥十五春。","唯有新昌故园月，至今分照兩乡人。"]', '诗', 'shi', '', NULL, '得潮州楊相公繼之書幷詩以此寄之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44defe8-745f-4142-b0f4-27ccc76d780b', '宿府池西亭', '宿府池西亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池上平橋橋下亭，夜深睡覺上橋行。","白頭老尹重來宿，十五年前舊月明。"]', '["池上平橋橋下亭，夜深睡覺上橋行。","白头老尹重来宿，十五年前旧月明。"]', '诗', 'shi', '', NULL, '宿府池西亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e54f653e-e829-4baa-ac7e-ad4e623815f7', '閑眠', '闲眠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暖牀斜臥日曛腰，一覺閑眠百病銷。","盡日一餐茶兩碗，更無所要到明朝。"]', '["暖牀斜臥日曛腰，一覺闲眠百病銷。","尽日一餐茶兩碗，更無所要到明朝。"]', '诗', 'shi', '', NULL, '閑眠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7b62f21-3593-430a-96ec-5ce565af34f9', '楊柳枝詞', '楊柳枝词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一樹春風千萬枝，嫩於金色軟於絲。","永豐西角荒園裏，盡日無人屬阿誰。"]', '["一樹春风千万枝，嫩於金色軟於絲。","永豐西角荒园裏，尽日無人屬阿誰。"]', '诗', 'shi', '', NULL, '楊柳枝詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d4b865-4825-485b-9094-5f3637756473', '詔取永豐柳植禁苑感賦', '詔取永豐柳植禁苑感賦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一樹衰殘委泥土，雙枝榮耀植天庭。","定知玄象今春後，柳宿光中添兩星。"]', '["一樹衰殘委泥土，雙枝榮耀植天庭。","定知玄象今春後，柳宿光中添兩星。"]', '诗', 'shi', '', NULL, '詔取永豐柳植禁苑感賦 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e291d938-e186-4e44-be94-e1a57a4226d3', '齋居春久感事遣懷', '斋居春久感事遣懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["齋戒坐三旬，笙歌發四鄰。","月明停酒夜，眼闇看花人。","賴學空爲觀，深知念是塵。","猶思閑語笑，未忘舊交親。","久作龍門主，多爲兔苑賓。","水嬉歌盡日，雪宴燭通晨。","事事皆過分，時時自問身。","風光拋得也，七十四年春。"]', '["斋戒坐三旬，笙歌發四鄰。","月明停酒夜，眼闇看花人。","賴学空爲观，深知念是塵。","猶思闲語笑，未忘旧交親。","久作龙门主，多爲兔苑賓。","水嬉歌尽日，雪宴燭通晨。","事事皆過分，时时自问身。","风光拋得也，七十四年春。"]', '诗', 'shi', '', NULL, '齋居春久感事遣懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bfff99a-ff38-4731-ab96-7f17f5eb50ce', '每見呂南二郎中新文輒竊有所歎惜因成長句以詠所懷', '每见呂南二郎中新文輒竊有所歎惜因成长句以詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雙金百鍊少人知，縱我知君徒爾爲。","望梅閤老無妨渴，畫餅尚書不救飢。","白日迴頭看又晚，青雲舉足躡何遲。","壯年可惜虛銷擲，遣把閑杯吟詠詩。"]', '["雙金百鍊少人知，縱我知君徒爾爲。","望梅閤老無妨渴，畫餅尚书不救飢。","白日迴头看又晚，青云舉足躡何遲。","壯年可惜虛銷擲，遣把闲杯吟詠诗。"]', '诗', 'shi', '', NULL, '每見呂南二郎中新文輒竊有所歎惜因成長句以詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5609739e-9488-4964-960c-e050fe6b8ddd', '胡吉鄭劉盧張等六賢皆多年壽予亦次焉偶於弊居合成尚齒之會七老相顧既醉且歡靜而思之此會稀有因成七言六韻以紀之傳好事者', '胡吉鄭劉盧張等六賢皆多年壽予亦次焉偶於弊居合成尚齒之會七老相顧既醉且歡静而思之此會稀有因成七言六韻以紀之傳好事者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七人五百七十歲，拖紫紆朱垂白鬚。","手裏無金莫嗟歎，尊中有酒且歡娛。","詩吟兩句神還王，酒飲三杯氣尚麤。","嵬峩狂歌教婢拍，婆娑醉舞遣孫扶。","天年高過二疎傅，人數多於四皓圖。","除却三山五天竺，人間此會更應無。"]', '["七人五百七十歲，拖紫紆朱垂白鬚。","手裏無金莫嗟歎，尊中有酒且歡娛。","诗吟兩句神還王，酒饮三杯氣尚麤。","嵬峩狂歌教婢拍，婆娑醉舞遣孫扶。","天年高過二疎傅，人數多於四皓圖。","除却三山五天竺，人间此會更應無。"]', '诗', 'shi', '', NULL, '胡吉鄭劉盧張等六賢皆多年壽予亦次焉偶於弊居合成尚齒之會七老相顧既醉且歡靜而思之此會稀有因成七言六韻以紀之傳好事者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90de636-fef6-4077-97c6-b29b7192a1fd', '歡喜二偈 一', '歡喜二偈 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["得老加年誠可喜，當春對酒亦宜歡。","心中別有歡喜事，開得龍門八節灘。"]', '["得老加年誠可喜，當春对酒亦宜歡。","心中別有歡喜事，开得龙门八節灘。"]', '诗', 'shi', '', NULL, '歡喜二偈 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc957da9-1e39-43d9-a7cb-3bce418ab3fe', '歡喜二偈 二', '歡喜二偈 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眼闇頭旋耳重聽，唯餘心口尚醒醒。","今朝歡喜緣何事，禮徹佛名百部經。"]', '["眼闇头旋耳重听，唯餘心口尚醒醒。","今朝歡喜緣何事，禮徹佛名百部經。"]', '诗', 'shi', '', NULL, '歡喜二偈 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e7e724e-cea8-4254-be31-1785add00ec3', '閑居貧活計', '闲居貧活計', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["冠蓋閑居少，簞瓢陋巷深。","稱家開戶牖，量力置園林。","儉薄身都慣，營爲力不任。","飢烹一斤肉，暖臥兩重衾。","尊有陶潛酒，囊無陸賈金。","莫嫌貧活計，更富即勞心。"]', '["冠蓋闲居少，簞瓢陋巷深。","稱家开戶牖，量力置园林。","儉薄身都慣，營爲力不任。","飢烹一斤肉，暖臥兩重衾。","尊有陶潛酒，囊無陸賈金。","莫嫌貧活計，更富即勞心。"]', '诗', 'shi', '', NULL, '閑居貧活計 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aced3db-b1d7-415a-b7a9-c56ff7f2e381', '贈諸少年', '贈諸少年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少年莫笑我蹉跎，聽我狂翁一曲歌。","入手榮名取雖少，關心穩事得還多。","老慙退馬霑芻秣，高喜歸鴻脫弋羅。","官給俸錢天與壽，些些貧病奈吾何。"]', '["少年莫笑我蹉跎，听我狂翁一曲歌。","入手榮名取雖少，关心穩事得還多。","老慙退马霑芻秣，高喜归鴻脫弋羅。","官給俸錢天與壽，些些貧病奈吾何。"]', '诗', 'shi', '', NULL, '贈諸少年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e117043-6993-4b25-91db-335bfb9932b2', '感所見', '感所见', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巧者焦勞智者愁，愚翁何喜復何憂。","莫嫌山木無人用，大勝籠禽不自由。","網外老雞因斷尾，盤中鮮鱠爲吞鉤。","誰人會我心中事，冷笑時時一掉頭。"]', '["巧者焦勞智者愁，愚翁何喜复何憂。","莫嫌山木無人用，大勝籠禽不自由。","網外老雞因斷尾，盤中鲜鱠爲吞鉤。","誰人會我心中事，冷笑时时一掉头。"]', '诗', 'shi', '', NULL, '感所見 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ebf2d97-fb7a-4b70-bdae-161b059e9e23', '寄黔州馬常侍', '寄黔州马常侍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑看雙節信爲貴，樂飲一杯誰與同。","可惜風情與心力，五年拋擲在黔中。"]', '["闲看雙節信爲貴，乐饮一杯誰與同。","可惜风情與心力，五年拋擲在黔中。"]', '诗', 'shi', '', NULL, '寄黔州馬常侍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c29ba9a2-373d-45d4-942e-717f0cfbaf9a', '和李相公留守題漕上新橋六韻', '和李相公留守題漕上新橋六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["選石鋪新路，安橋壓古堤。","似從銀漢下，落傍玉川西。","影定欄杆倒，標高華表齊。","煙開虹半見，月冷鶴雙栖。","材映夔龍小，功嫌元凱低。","從容濟世後，餘力及黔黎。"]', '["選石鋪新路，安橋壓古堤。","似從銀漢下，落傍玉川西。","影定欄杆倒，標高华表齊。","煙开虹半见，月冷鹤雙栖。","材映夔龙小，功嫌元凱低。","從容濟世後，餘力及黔黎。"]', '诗', 'shi', '', NULL, '和李相公留守題漕上新橋六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2acc2e23-10ea-48bb-b1ba-b7a3940159ae', '閑居', '闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風雨蕭條秋少客，門庭冷靜晝多關。","金羈駱馬近賣却，羅袖柳枝尋放還。","書卷略尋聊取睡，酒杯淺把麤開顏。","眼昏入夜休看月，脚重經春不上山。","心靜無妨喧處寂，機忘兼覺夢中閑。","是非愛惡銷停盡，唯寄空身在世間。"]', '["风雨蕭條秋少客，门庭冷静晝多关。","金羈駱马近賣却，羅袖柳枝尋放還。","书卷略尋聊取睡，酒杯淺把麤开顏。","眼昏入夜休看月，脚重經春不上山。","心静無妨喧处寂，機忘兼覺梦中闲。","是非愛惡銷停尽，唯寄空身在世间。"]', '诗', 'shi', '', NULL, '閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ad8822-dbac-4ec1-8521-6ba066be1f79', '新秋夜雨', '新秋夜雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟋蟀暮啾啾，光陰不少留。","松簷半夜雨，風幌滿牀秋。","曙早燈猶在，涼初簟未收。","新晴好天氣，誰伴老人遊。"]', '["蟋蟀暮啾啾，光陰不少留。","松簷半夜雨，风幌满牀秋。","曙早灯猶在，涼初簟未收。","新晴好天氣，誰伴老人游。"]', '诗', 'shi', '', NULL, '新秋夜雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23d2ed8d-fd6f-4ec8-b37d-8ce7b3380998', '春眠', '春眠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["枕低被暖身安穩，日照房門帳未開。","還有少年春氣味，時時蹔到夢中來。"]', '["枕低被暖身安穩，日照房门帳未开。","還有少年春氣味，时时蹔到梦中来。"]', '诗', 'shi', '', NULL, '春眠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('407caec8-8b7d-4935-bdca-77c475d23db0', '喜老自嘲', '喜老自嘲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["面黑頭雪白，自嫌還自憐。","毛龜蓍下老，蝙蝠鼠中仙。","名籍同逋客，衣裝類古賢。","裘輕被白氎，靴暖蹋烏氈。","周易休開卦，陶琴不上弦。","任從人棄擲，自與我周旋。","鐵馬因疲退，鉛刀以鈍全。","行開第八秩，可謂盡天年。"]', '["面黑头雪白，自嫌還自怜。","毛龟蓍下老，蝙蝠鼠中仙。","名籍同逋客，衣裝類古賢。","裘轻被白氎，靴暖蹋烏氈。","周易休开卦，陶琴不上弦。","任從人棄擲，自與我周旋。","鐵马因疲退，鉛刀以鈍全。","行开第八秩，可謂尽天年。"]', '诗', 'shi', '', NULL, '喜老自嘲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ec4e946-fb9a-4800-b7be-5cba376eaabc', '能無媿', '能無媿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十兩新綿褐，披行暖似春。","一團香絮枕，倚坐穩于人。","婢僕遣他嘗藥草，兒孫與我拂衣巾。","迴看左右能無媿，養活枯殘廢退身。"]', '["十兩新綿褐，披行暖似春。","一團香絮枕，倚坐穩于人。","婢僕遣他嘗藥草，兒孫與我拂衣巾。","迴看左右能無媿，養活枯殘廢退身。"]', '诗', 'shi', '', NULL, '能無媿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6486779b-681a-49ac-b49b-f1b3140d8546', '河陽石尚書破迴鶻迎貴主過上黨射鷺𪆗繪畫爲圖猥蒙見示稱歎不足以詩美之', '河陽石尚书破迴鶻迎貴主過上黨射鷺𪆗繪畫爲圖猥蒙见示稱歎不足以诗美之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["塞北虜郊隨手破，山東賊壘掉鞭收。","烏孫公主歸秦地，白馬將軍入潞州。","劒拔青鱗蛇尾活，弦抨赤羽火星流。","須知鳥目猶難漏，縱有天狼豈足憂。","畫角三聲刁斗曉，清商一部管弦秋。","他時麟閣圖勳業，更合何人居上頭。"]', '["塞北虜郊隨手破，山东賊壘掉鞭收。","烏孫公主归秦地，白马將軍入潞州。","劒拔青鱗蛇尾活，弦抨赤羽火星流。","須知鸟目猶难漏，縱有天狼豈足憂。","畫角三声刁斗晓，清商一部管弦秋。","他时麟閣圖勳業，更合何人居上头。"]', '诗', 'shi', '', NULL, '河陽石尚書破迴鶻迎貴主過上黨射鷺𪆗繪畫爲圖猥蒙見示稱歎不足以詩美之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f846d2d-e4d7-4e07-8304-21ae22cef232', '自詠老身示諸家屬', '自詠老身示諸家屬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["壽及七十五，俸霑五十千。","夫妻偕老日，甥姪聚居年。","粥美嘗新米，袍溫換故綿。","家居雖濩落，眷屬幸團圓。","置榻素屏下，移爐青帳前。","書聽孫子讀，湯看侍兒煎。","走筆還詩債，抽衣當藥錢。","支分閑事了，爬背向陽眠。"]', '["壽及七十五，俸霑五十千。","夫妻偕老日，甥姪聚居年。","粥美嘗新米，袍溫換故綿。","家居雖濩落，眷屬幸團圓。","置榻素屏下，移爐青帳前。","书听孫子读，湯看侍兒煎。","走笔還诗債，抽衣當藥錢。","支分闲事了，爬背向陽眠。"]', '诗', 'shi', '', NULL, '自詠老身示諸家屬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd7d06e9-ebb7-4aae-9323-03c926003ba0', '自問此心呈諸老伴', '自问此心呈諸老伴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝問此心何所思，暮問此心何所爲。","不入公門慵歛手，不看人面免低眉。","居士室間眠得所，少年場上飲非宜。","閑談亹亹留諸老，美醞徐徐進一巵。","心未曾求過分事，身常少有不安時。","此心除自謀身外，更問其餘盡不知。"]', '["朝问此心何所思，暮问此心何所爲。","不入公门慵歛手，不看人面免低眉。","居士室间眠得所，少年場上饮非宜。","闲談亹亹留諸老，美醞徐徐進一巵。","心未曾求過分事，身常少有不安时。","此心除自謀身外，更问其餘尽不知。"]', '诗', 'shi', '', NULL, '自問此心呈諸老伴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5754edd8-51eb-4f85-959d-b588ad282d41', '六年立春日人日作', '六年立春日人日作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二日立春人七日，盤蔬餅餌逐時新。","年方吉鄭猶爲少，家比劉韓未是貧。","鄉園節歲應堪重，親故歡遊莫厭頻。","試作循潮封眼想，何由得見洛陽春。"]', '["二日立春人七日，盤蔬餅餌逐时新。","年方吉鄭猶爲少，家比劉韓未是貧。","乡园節歲應堪重，親故歡游莫厭頻。","試作循潮封眼想，何由得见洛陽春。"]', '诗', 'shi', '', NULL, '六年立春日人日作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e758d754-e07d-4267-b98f-25dbbecf77bc', '齋居偶作', '斋居偶作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["童子裝爐火，行添一炷香。","老翁持麈尾，坐拂半張牀。","卷縵看天色，移齋近日陽。","甘鮮新餅果，穩暖舊衣裳。","止足安生理，悠閑樂性場。","是非一以遣，動靜百無妨。","豈有物相累，兼無情可忘。","不須憂老病，心是自醫王。"]', '["童子裝爐火，行添一炷香。","老翁持麈尾，坐拂半張牀。","卷縵看天色，移斋近日陽。","甘鲜新餅果，穩暖旧衣裳。","止足安生理，悠闲乐性場。","是非一以遣，动静百無妨。","豈有物相累，兼無情可忘。","不須憂老病，心是自醫王。"]', '诗', 'shi', '', NULL, '齋居偶作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edada8fa-dc00-41d6-8715-0481b43d52b3', '詠身', '詠身', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自中風來三歷閏，從懸軍後幾逢春。","周南留滯稱遺老，漢上羸殘號半人。","薄有文章傳子弟，斷無書札荅交親。","餘年自問將何用，恐是人間賸長身。"]', '["自中风来三歷閏，從懸軍後幾逢春。","周南留滯稱遺老，漢上羸殘號半人。","薄有文章傳子弟，斷無书札荅交親。","餘年自问將何用，恐是人间賸长身。"]', '诗', 'shi', '', NULL, '詠身 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d4e490b-517c-4201-bdf5-90da20d8ac46', '予與山南王僕射起淮南李僕射紳事歷五朝踰三紀海內年輩今唯三人榮路雖殊交情不替聊題長句寄舉之公垂二相公', '予與山南王僕射起淮南李僕射紳事歷五朝踰三紀海內年輩今唯三人榮路雖殊交情不替聊題长句寄舉之公垂二相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故交海內只三人，二坐巖廊一臥雲。","老愛詩書還似我，榮兼將相不如君。","百年膠漆初心在，萬里煙霄中路分。","阿閣鸞凰野田鶴，何人信道舊同羣。"]', '["故交海內只三人，二坐巖廊一臥云。","老愛诗书還似我，榮兼將相不如君。","百年膠漆初心在，万里煙霄中路分。","阿閣鸾凰野田鹤，何人信道旧同羣。"]', '诗', 'shi', '', NULL, '予與山南王僕射起淮南李僕射紳事歷五朝踰三紀海內年輩今唯三人榮路雖殊交情不替聊題長句寄舉之公垂二相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a48014c-71be-4011-b765-2051ece90629', '讀道德經', '读道德經', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玄元皇帝著遺文，烏角先生仰後塵。","金玉滿堂非己物，子孫委蛻是他人。","世間盡不關吾事，天下無親於我身。","只有一身宜愛護，少教冰炭逼心神。"]', '["玄元皇帝著遺文，烏角先生仰後塵。","金玉满堂非己物，子孫委蛻是他人。","世间尽不关吾事，天下無親於我身。","只有一身宜愛護，少教冰炭逼心神。"]', '诗', 'shi', '', NULL, '讀道德經 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('493f2546-5e66-4084-8387-4c8249d68e86', '禽蟲十二章 一', '禽蟲十二章 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["燕違戊己鵲避歲，茲事因何羽族知。","疑有鳳凰頒鳥曆，一時一日不參差。"]', '["燕違戊己鵲避歲，茲事因何羽族知。","疑有鳳凰頒鸟曆，一时一日不參差。"]', '诗', 'shi', '', NULL, '禽蟲十二章 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f50dcc-aba0-4e95-b175-c71d2eb203c7', '禽蟲十二章 二', '禽蟲十二章 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水中科斗長成蛙，林下桑蟲老作蛾。","蛙跳蛾舞仰頭笑，焉用鵾鵬鱗羽多。"]', '["水中科斗长成蛙，林下桑蟲老作蛾。","蛙跳蛾舞仰头笑，焉用鵾鵬鱗羽多。"]', '诗', 'shi', '', NULL, '禽蟲十二章 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc6dbec-3846-48be-83f3-939d956e5ab3', '禽蟲十二章 三', '禽蟲十二章 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江魚羣從稱妻妾，塞雁聯行號弟兄。","但恐世間真眷屬，親疎亦是強爲名。"]', '["江鱼羣從稱妻妾，塞雁聯行號弟兄。","但恐世间真眷屬，親疎亦是強爲名。"]', '诗', 'shi', '', NULL, '禽蟲十二章 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1120d8-5f62-4ddd-84c7-97839ed41fec', '禽蟲十二章 四', '禽蟲十二章 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蠶老繭成不庇身，蜂飢蜜熟屬他人。","須知年老憂家者，恐是二蟲虛苦辛。"]', '["蠶老繭成不庇身，蜂飢蜜熟屬他人。","須知年老憂家者，恐是二蟲虛苦辛。"]', '诗', 'shi', '', NULL, '禽蟲十二章 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67beefac-6047-45e2-8783-b9c15cce4180', '禽蟲十二章 五', '禽蟲十二章 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["阿閣鵷鸞田舍烏，妍蚩貴賤兩懸殊。","如何閉向深籠裏，一種摧頹觸四隅。"]', '["阿閣鵷鸾田舍烏，妍蚩貴賤兩懸殊。","如何閉向深籠裏，一種摧頹觸四隅。"]', '诗', 'shi', '', NULL, '禽蟲十二章 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff48aed7-652b-4fb0-8ae2-1861d5771e3e', '禽蟲十二章 六', '禽蟲十二章 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獸中刀鎗多怒吼，鳥遭羅弋盡哀鳴。","羔羊口在緣何事，闇死屠門無一聲。"]', '["獸中刀鎗多怒吼，鸟遭羅弋尽哀鳴。","羔羊口在緣何事，闇死屠门無一声。"]', '诗', 'shi', '', NULL, '禽蟲十二章 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a64c6d0-878e-4594-a815-6b4174fb8a86', '禽蟲十二章 七', '禽蟲十二章 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟭螟殺敵蚊巢上，蠻觸交爭蝸角中。","應是諸天觀下界，一微塵內鬬英雄。"]', '["蟭螟殺敵蚊巢上，蠻觸交爭蝸角中。","應是諸天观下界，一微塵內鬬英雄。"]', '诗', 'shi', '', NULL, '禽蟲十二章 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10abc64-0e3c-47f2-bbcf-7a57d50d42a4', '禽蟲十二章 八', '禽蟲十二章 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蠨蛸網上罥蜉蝣，反覆相持死始休。","何異浮生臨老日，一彈指頃報恩讐。"]', '["蠨蛸網上罥蜉蝣，反覆相持死始休。","何異浮生臨老日，一彈指頃報恩讐。"]', '诗', 'shi', '', NULL, '禽蟲十二章 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cab8a6d-042b-40c7-ad7b-d30f61fd0d90', '禽蟲十二章 九', '禽蟲十二章 九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟻王化飯爲臣妾，蜾母偷蟲作子孫。","彼此假名非本物，其間何怨復何恩。"]', '["蟻王化飯爲臣妾，蜾母偷蟲作子孫。","彼此假名非本物，其间何怨复何恩。"]', '诗', 'shi', '', NULL, '禽蟲十二章 九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0207d5b9-9515-46e8-82a1-314d82f32bc9', '禽蟲十二章 十', '禽蟲十二章 十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豆苗鹿嚼解烏毒，艾葉雀銜奪燕巢。","鳥獸不曾看本草，諳知藥性是誰教。"]', '["豆苗鹿嚼解烏毒，艾葉雀銜奪燕巢。","鸟獸不曾看本草，諳知藥性是誰教。"]', '诗', 'shi', '', NULL, '禽蟲十二章 十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('983980f4-30da-4799-bec0-b5b597357679', '禽蟲十二章 十一', '禽蟲十二章 十一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一鼠得仙生羽翼，衆鼠相看有羨色。","豈知飛上未半空，已作烏鳶口中食。"]', '["一鼠得仙生羽翼，衆鼠相看有羨色。","豈知飞上未半空，已作烏鳶口中食。"]', '诗', 'shi', '', NULL, '禽蟲十二章 十一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61c68b9-55a4-4613-9f34-c3183a52452c', '禽蟲十二章 十二', '禽蟲十二章 十二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鵝乳養雛遺在水，魚心想子變成鱗。","細微幽隱何窮事，知者唯應是聖人。"]', '["鵝乳養雛遺在水，鱼心想子变成鱗。","細微幽隐何窮事，知者唯應是聖人。"]', '诗', 'shi', '', NULL, '禽蟲十二章 十二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3eb0494-509b-4e39-8c2f-505a4fc0d6ae', '窗中列遠岫', '窗中列远岫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天靜秋山好，窗開曉翠通。","遙憐峰窈窕，不隔竹朦朧。","萬點當虛室，千重疊遠空。","列檐攢秀氣，緣隙助清風。","碧愛新晴後，明宜反照中。","宣城郡齋在，望與古時同。"]', '["天静秋山好，窗开晓翠通。","遙怜峰窈窕，不隔竹朦朧。","万点當虛室，千重叠远空。","列檐攢秀氣，緣隙助清风。","碧愛新晴後，明宜反照中。","宣城郡斋在，望與古时同。"]', '诗', 'shi', '', NULL, '窗中列遠岫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b9ed86c-2189-475f-bce3-0339fb22707b', '玉水記方流', '玉水記方流', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["良璞含章久，寒泉徹底幽。","矩浮光灩灩，方折浪悠悠。","凌亂波紋異，縈迴水性柔。","似風搖淺瀨，疑月落清流。","潛潁應傍達，藏真豈上浮。","玉人如不見，淪棄即千秋。"]', '["良璞含章久，寒泉徹底幽。","矩浮光灩灩，方折浪悠悠。","凌亂波紋異，縈迴水性柔。","似风搖淺瀨，疑月落清流。","潛潁應傍達，藏真豈上浮。","玉人如不见，淪棄即千秋。"]', '诗', 'shi', '', NULL, '玉水記方流 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5a08b3-3f64-4708-ad58-160ce15c51a9', '大社觀獻捷詩', '大社观獻捷诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淮海妖氛滅，乾坤嘉氣通。","班師郊社內，操袂凱歌中。","廟算無遺策，天兵不戰功。","小臣同鳥獸，率舞向皇風。"]', '["淮海妖氛滅，乾坤嘉氣通。","班師郊社內，操袂凱歌中。","廟算無遺策，天兵不戰功。","小臣同鸟獸，率舞向皇风。"]', '诗', 'shi', '', NULL, '大社觀獻捷詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f70c89-d21b-4785-b337-cb3f96a31013', '自誨', '自誨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樂天樂天，來與汝言。","汝宜拳拳，終身行焉。","物有萬類，錮人如鎖。","事有萬感，爇人如火。","萬類遰來，鏁汝形骸。","使汝未老，形枯如柴。","萬感遰至，火汝心懷。","使汝未死，心化爲灰。","樂天樂天，可不大哀。","汝胡不懲往而念來，人生百歲七十稀，設使與汝七十期。","汝今年已四十四，却後二十六年能幾時。","汝不思二十五六年來事，疾速倏忽如一寐。","往日來日皆瞥然，胡爲自苦於其間。","樂天樂天，可不大哀。","而今而後，汝宜飢而食，渴而飲。","晝而興，夜而寢。","無浪喜，無妄憂。","病則臥，死則休。","此中是汝家，此中是汝鄉。","汝何捨此而去，自取其遑遑。","遑遑兮欲安往哉，樂天樂天歸去來。"]', '["乐天乐天，来與汝言。","汝宜拳拳，終身行焉。","物有万類，錮人如鎖。","事有万感，爇人如火。","万類遰来，鏁汝形骸。","使汝未老，形枯如柴。","万感遰至，火汝心懷。","使汝未死，心化爲灰。","乐天乐天，可不大哀。","汝胡不懲往而念来，人生百歲七十稀，設使與汝七十期。","汝今年已四十四，却後二十六年能幾时。","汝不思二十五六年来事，疾速倏忽如一寐。","往日来日皆瞥然，胡爲自苦於其间。","乐天乐天，可不大哀。","而今而後，汝宜飢而食，渴而饮。","晝而兴，夜而寢。","無浪喜，無妄憂。","病則臥，死則休。","此中是汝家，此中是汝乡。","汝何捨此而去，自取其遑遑。","遑遑兮欲安往哉，乐天乐天归去来。"]', '诗', 'shi', '', NULL, '自誨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69cf0d6a-2c3f-455a-8ce1-995d50469d59', '三謠 蟠木謠', '三謠 蟠木謠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟠木蟠木，有似我身。","不中乎器，無用於人。","下擁腫而上轔菌，桷不桷兮輪不輪。","天子建明堂兮既非梁棟，諸侯斵大輅兮材又不中。","唯我病夫，或有所用。","用爾爲几，承吾臂支吾頤而已矣。","不傷爾性，不枉爾理。","爾怏怏爲几之外，無所用爾。","爾既不材，吾亦不材，胡爲乎人間裴回？","蟠木蟠木，吾與汝歸草堂去來。"]', '["蟠木蟠木，有似我身。","不中乎器，無用於人。","下擁腫而上轔菌，桷不桷兮輪不輪。","天子建明堂兮既非梁棟，諸侯斵大輅兮材又不中。","唯我病夫，或有所用。","用爾爲几，承吾臂支吾頤而已矣。","不傷爾性，不枉爾理。","爾怏怏爲几之外，無所用爾。","爾既不材，吾亦不材，胡爲乎人间裴回？","蟠木蟠木，吾與汝归草堂去来。"]', '诗', 'shi', '', NULL, '三謠 蟠木謠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c437981e-acc7-44aa-a248-ad39993355a1', '三謠 素屏謠', '三謠 素屏謠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["素屏素屏，胡爲乎不文不飾，不丹不青。","當世豈無李陽冰之篆字，張旭之筆迹。","邊鸞之花鳥，張璪之松石。","吾不令加一點一畫於其上，欲爾保真而全白。","吾於香爐峰下置草堂，二屏倚在東西牆。","夜如明月入我室，曉如白雲圍我牀。","我心久養浩然氣，亦欲與爾表裏相輝光。","爾不見當今甲第與王宮，織成步障銀屏風。","綴珠陷鈿貼雲母，五金七寶相玲瓏。","貴豪待此方悅目，晏然寢臥乎其中。","素屏素屏，物各有所宜，用各有所施。","爾今木爲骨兮紙爲面，捨吾草堂欲何之。"]', '["素屏素屏，胡爲乎不文不飾，不丹不青。","當世豈無李陽冰之篆字，張旭之笔迹。","邊鸾之花鸟，張璪之松石。","吾不令加一点一畫於其上，欲爾保真而全白。","吾於香爐峰下置草堂，二屏倚在东西牆。","夜如明月入我室，晓如白云圍我牀。","我心久養浩然氣，亦欲與爾表裏相輝光。","爾不见當今甲第與王宮，织成步障銀屏风。","綴珠陷鈿貼云母，五金七寶相玲瓏。","貴豪待此方悅目，晏然寢臥乎其中。","素屏素屏，物各有所宜，用各有所施。","爾今木爲骨兮紙爲面，捨吾草堂欲何之。"]', '诗', 'shi', '', NULL, '三謠 素屏謠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a8ea076-1895-4dfb-a0de-42e17e3a042c', '三謠 朱藤謠', '三謠 朱藤謠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朱藤朱藤，溫如紅玉，直如朱繩。","自我得爾以爲杖，大有裨於股肱。","前年左選，東南萬里。","交遊別我於國門，親友送我於滻水。","登高山兮車倒輪摧，渡漢水兮馬跙蹄開。","中途不進，部曲多迴。","唯此朱藤，實隨我來。","瘴癘之鄉，無人之地。","扶衛衰病，驅訶魑魅。","吾獨一身，賴爾爲二。","或水或陸，自北徂南。","泥黏雪滑，足力不堪。","吾本兩足，得爾爲三。","紫霄峰頭，黃石巖下。","松門石磴，不通輿馬。","吾與爾披雲撥水，環山繞野。","二年蹋徧匡廬間，未嘗一步而相捨。","雖有佳子弟，良友朋。","扶危助蹇，不如朱藤。","嗟乎！窮既若是，通復何如？","吾不以常杖待爾，爾勿以常人望吾。","朱藤朱藤，吾雖青雲之上，黃泥之下，誓不棄爾於斯須。"]', '["朱藤朱藤，溫如紅玉，直如朱繩。","自我得爾以爲杖，大有裨於股肱。","前年左選，东南万里。","交游別我於国门，親友送我於滻水。","登高山兮车倒輪摧，渡漢水兮马跙蹄开。","中途不進，部曲多迴。","唯此朱藤，實隨我来。","瘴癘之乡，無人之地。","扶衛衰病，驱訶魑魅。","吾独一身，賴爾爲二。","或水或陸，自北徂南。","泥黏雪滑，足力不堪。","吾本兩足，得爾爲三。","紫霄峰头，黄石巖下。","松门石磴，不通輿马。","吾與爾披云撥水，环山繞野。","二年蹋徧匡廬间，未嘗一步而相捨。","雖有佳子弟，良友朋。","扶危助蹇，不如朱藤。","嗟乎！窮既若是，通复何如？","吾不以常杖待爾，爾勿以常人望吾。","朱藤朱藤，吾雖青云之上，黄泥之下，誓不棄爾於斯須。"]', '诗', 'shi', '', NULL, '三謠 朱藤謠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da9dca80-4137-4ef6-8851-2c0e23463a22', '無可奈何歌', '無可奈何歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["無可奈何兮！白日走而朱顏頹，少日往而老日催。","生者不住兮死者不迴，況乎寵辱豐顇之外物。","又何常不十去而一來，去不可挽兮來不可推。","無可奈何兮！已焉哉！惟天長而地久，前無始兮後無終。","嗟吾生之幾何，寄瞬息乎其中。","又如太倉之稊米，委一粒於萬鍾。","何不與道逍遙？","委化從容。","縱心放志，洩洩融融。","胡爲乎分愛惡於生死，繫憂喜於窮通。","倔強其骨髓，齟齬其心胷。","合冰炭以交戰，祗自苦兮厥躬。","彼造物者，云何不爲。","此與化者，云何不隨。","或喣或吹，或盛或衰。","雖千變與萬化，委一順以貫之。","爲彼何非，爲此何是。","誰冥此心，夢蝶之子。","何禍非福，何吉非凶。","誰達此觀，喪馬之翁。","俾吾爲秋毫之杪，吾亦自足。","不見其小，俾吾爲泰山之阿。","吾亦無餘，不見其多。","是以達人靜則脗然與陰合迹，動則浩然與陽同波。","委順而已，孰知其他。","時邪命邪！吾其無奈彼何？委邪順邪！彼亦無奈吾何？夫兩無奈何，然後能冥至順而合太和。","故吾所以飲太和，扣至順，而爲無可奈何之歌。"]', '["無可奈何兮！白日走而朱顏頹，少日往而老日催。","生者不住兮死者不迴，況乎寵辱豐顇之外物。","又何常不十去而一来，去不可挽兮来不可推。","無可奈何兮！已焉哉！惟天长而地久，前無始兮後無終。","嗟吾生之幾何，寄瞬息乎其中。","又如太倉之稊米，委一粒於万鍾。","何不與道逍遙？","委化從容。","縱心放志，洩洩融融。","胡爲乎分愛惡於生死，繫憂喜於窮通。","倔強其骨髓，齟齬其心胷。","合冰炭以交戰，祗自苦兮厥躬。","彼造物者，云何不爲。","此與化者，云何不隨。","或喣或吹，或盛或衰。","雖千变與万化，委一順以貫之。","爲彼何非，爲此何是。","誰冥此心，梦蝶之子。","何禍非福，何吉非凶。","誰達此观，喪马之翁。","俾吾爲秋毫之杪，吾亦自足。","不见其小，俾吾爲泰山之阿。","吾亦無餘，不见其多。","是以達人静則脗然與陰合迹，动則浩然與陽同波。","委順而已，孰知其他。","时邪命邪！吾其無奈彼何？委邪順邪！彼亦無奈吾何？夫兩無奈何，然後能冥至順而合太和。","故吾所以饮太和，扣至順，而爲無可奈何之歌。"]', '诗', 'shi', '', NULL, '無可奈何歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f058930e-14aa-470d-a0eb-fcec45d2071d', '池上篇', '池上篇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十畝之宅，五畝之園。","有水一池，有竹千竿。","勿謂土狹，勿謂地偏。","足以容膝，足以息肩。","有堂有庭，有橋有船。","有書有酒，有歌有弦。","有叟在中，白鬚飄然。","識分知足，外無求焉。","如鳥擇木，姑務巢安。","如龜居坎，不知海寬。","靈鶴怪石，紫菱白蓮。","皆吾所好，盡在吾前。","時飲一杯，或吟一篇。","妻孥熙熙，雞犬閑閑。","優哉游哉，吾將終老乎其間。"]', '["十畝之宅，五畝之园。","有水一池，有竹千竿。","勿謂土狹，勿謂地偏。","足以容膝，足以息肩。","有堂有庭，有橋有船。","有书有酒，有歌有弦。","有叟在中，白鬚飄然。","識分知足，外無求焉。","如鸟擇木，姑務巢安。","如龟居坎，不知海寬。","靈鹤怪石，紫菱白蓮。","皆吾所好，尽在吾前。","时饮一杯，或吟一篇。","妻孥熙熙，雞犬闲闲。","優哉游哉，吾將終老乎其间。"]', '诗', 'shi', '', NULL, '池上篇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd4e626-16f4-4beb-bc98-6e9a75f62534', '齒落辭', '齒落辞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嗟嗟乎雙齒，自吾有之爾。","俾爾嚼肉咀蔬，銜杯漱水。","豐吾膚革，滋吾血髓。","從幼逮老，勤亦至矣。","幸有輔車，非無齗齶。","胡然捨我，一旦雙落。","齒雖無情，吾豈無情。","老與齒別，齒隨涕零。","我老日來，爾去不迴。","嗟嗟乎雙齒，孰謂而來哉？孰謂而去哉？齒不能言，請以意宣。","爲口中之物，忽乎六十餘年。","昔君之壯也，血剛齒堅。","今君之老矣，血衰齒寒。","輔車齗齶，日削月朘。","上參差而下𠨜𦤞，曾何足以少安。","嘻！君其聽哉，女長辭姥，臣老辭主。","髮衰辭頭，葉枯辭樹。","物無細大，功成者去，君何嗟嗟？","獨不聞諸道經，我身非我有也，蓋天地之委形。","君何嗟嗟？","又不聞諸佛說，是身如浮雲，須臾變滅。","由是而言，君何有焉？","所宜委百骸而順萬化，胡爲乎嗟嗟於一牙一齒之間。","吾應曰：吾過矣，爾之言然。"]', '["嗟嗟乎雙齒，自吾有之爾。","俾爾嚼肉咀蔬，銜杯漱水。","豐吾膚革，滋吾血髓。","從幼逮老，勤亦至矣。","幸有輔车，非無齗齶。","胡然捨我，一旦雙落。","齒雖無情，吾豈無情。","老與齒別，齒隨涕零。","我老日来，爾去不迴。","嗟嗟乎雙齒，孰謂而来哉？孰謂而去哉？齒不能言，請以意宣。","爲口中之物，忽乎六十餘年。","昔君之壯也，血剛齒堅。","今君之老矣，血衰齒寒。","輔车齗齶，日削月朘。","上參差而下𠨜𦤞，曾何足以少安。","嘻！君其听哉，女长辞姥，臣老辞主。","髮衰辞头，葉枯辞樹。","物無細大，功成者去，君何嗟嗟？","独不闻諸道經，我身非我有也，蓋天地之委形。","君何嗟嗟？","又不闻諸佛说，是身如浮云，須臾变滅。","由是而言，君何有焉？","所宜委百骸而順万化，胡爲乎嗟嗟於一牙一齒之间。","吾應曰：吾過矣，爾之言然。"]', '诗', 'shi', '', NULL, '齒落辭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd389f4-9ca4-4e6e-842c-e0488b44946b', '不能忘情吟', '不能忘情吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬻駱馬兮放楊柳枝，掩翠黛兮頓金羈。","馬不能言兮長鳴而却顧，楊柳枝再拜長跪而致辭。","辭曰：主乘此駱五年，凡千有八百日。","銜橜之下，不驚不逸。","素事主十年，凡三千有六百日。","巾櫛之間，無違無失。","今素貌雖陋，未至衰摧。","駱力猶壯，又無虺隤。","即駱之力，尚可以代主一步。","素之歌，亦可以送主一杯。","一旦雙去，有去無迴。","故素將去，其辭也苦。","駱將去，其鳴也哀。","此人之情也，馬之情也，豈主君獨無情哉？","予俯而歎，仰而咍，且曰：駱、駱，爾勿嘶，素、素，爾勿啼，駱反廐，素反閨。","吾疾雖作，年雖頹，幸未及項籍之將死。","何必一日之內，棄騅兮而別虞兮，乃目素兮素兮。","爲我歌楊柳枝，我姑酌彼金罍，我與爾歸醉鄉去來。"]', '["鬻駱马兮放楊柳枝，掩翠黛兮頓金羈。","马不能言兮长鳴而却顧，楊柳枝再拜长跪而致辞。","辞曰：主乘此駱五年，凡千有八百日。","銜橜之下，不驚不逸。","素事主十年，凡三千有六百日。","巾櫛之间，無違無失。","今素貌雖陋，未至衰摧。","駱力猶壯，又無虺隤。","即駱之力，尚可以代主一步。","素之歌，亦可以送主一杯。","一旦雙去，有去無迴。","故素將去，其辞也苦。","駱將去，其鳴也哀。","此人之情也，马之情也，豈主君独無情哉？","予俯而歎，仰而咍，且曰：駱、駱，爾勿嘶，素、素，爾勿啼，駱反廐，素反閨。","吾疾雖作，年雖頹，幸未及項籍之將死。","何必一日之內，棄騅兮而別虞兮，乃目素兮素兮。","爲我歌楊柳枝，我姑酌彼金罍，我與爾归醉乡去来。"]', '诗', 'shi', '', NULL, '不能忘情吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59dcfd79-edf4-40ea-9e7e-166bfba05c0d', '勸酒', '勸酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨與美人對尊酒，朱顏如花腰似柳。","今與美人傾一杯，秋風颯颯頭上來。","年光似水向東去，兩鬢不禁白日催。","東鄰起樓高百尺，璇題照日光相射。","珠翠無非二八人，盤筵何啻三千客。","鄰家儒者方下帷，夜誦古書朝忍飢。","身年三十未入仕，仰望東鄰安可期。","一朝逸翮乘風勢，金榜高張登上第。","春闈未了冬登科，九萬摶風誰與繼。","不逾十稔居台衡，門前車馬紛縱橫。","人人仰望在何處，造化筆頭雲雨生。","東鄰高樓色未改，主人云亡息猶在。","金玉車馬一不存，朱門更有何人待。","牆垣反鎖長安春，樓臺漸漸屬西鄰。","松篁薄暮亦栖鳥，桃李無情還笑人。","憶昔東鄰宅初搆，雲甍彩棟皆非舊。","瑇瑁筵前翡翠栖，芙蓉池上鴛鴦鬬。","日往月來凡幾秋，一衰一盛何悠悠。","但教帝里笙歌在，池上年年醉五侯。"]', '["昨與美人对尊酒，朱顏如花腰似柳。","今與美人傾一杯，秋风颯颯头上来。","年光似水向东去，兩鬢不禁白日催。","东鄰起楼高百尺，璇題照日光相射。","珠翠無非二八人，盤筵何啻三千客。","鄰家儒者方下帷，夜誦古书朝忍飢。","身年三十未入仕，仰望东鄰安可期。","一朝逸翮乘风勢，金榜高張登上第。","春闈未了冬登科，九万摶风誰與繼。","不逾十稔居台衡，门前车马紛縱橫。","人人仰望在何处，造化笔头云雨生。","东鄰高楼色未改，主人云亡息猶在。","金玉车马一不存，朱门更有何人待。","牆垣反鎖长安春，楼台漸漸屬西鄰。","松篁薄暮亦栖鸟，桃李無情還笑人。","憶昔东鄰宅初搆，云甍彩棟皆非旧。","瑇瑁筵前翡翠栖，芙蓉池上鴛鴦鬬。","日往月来凡幾秋，一衰一盛何悠悠。","但教帝里笙歌在，池上年年醉五侯。"]', '诗', 'shi', '', NULL, '勸酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eefedc03-348b-45e7-bb17-8c718504b317', '南陽小將張彥硤口鎮稅人場射虎歌', '南陽小將張彥硤口鎮稅人場射虎歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海內昔年狎太平，橫目穰穰何崢嶸。","天生天殺豈天怒，忍使朝朝餵猛虎。","關東驛路多丘荒，行人最忌稅人場。","張彥雄特制殘暴，見之叱起如叱羊。","鳴弦霹靂越幽阻，往往依林猶旅拒。","草際旋看委錦茵，腰間不更抽白羽。","老饕已斃衆雛恐，童穉揶揄皆自勇。","忠良效順勢亦然，一劒猜狂敢輕動。","有文有武方爲國，不是英雄伏不得。","試徵張彥作將軍，幾箇將軍願策勳。"]', '["海內昔年狎太平，橫目穰穰何崢嶸。","天生天殺豈天怒，忍使朝朝餵猛虎。","关东驛路多丘荒，行人最忌稅人場。","張彥雄特制殘暴，见之叱起如叱羊。","鳴弦霹靂越幽阻，往往依林猶旅拒。","草際旋看委錦茵，腰间不更抽白羽。","老饕已斃衆雛恐，童穉揶揄皆自勇。","忠良效順勢亦然，一劒猜狂敢轻动。","有文有武方爲国，不是英雄伏不得。","試徵張彥作將軍，幾箇將軍願策勳。"]', '诗', 'shi', '', NULL, '南陽小將張彥硤口鎮稅人場射虎歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34be6242-2eeb-4ef0-8c20-6cc8dc9ec82d', '陰雨', '陰雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潤葉濡枝浹四方，濃雲來去勢何長。","曠然寰宇清風滿，救旱功高暑氣涼。"]', '["潤葉濡枝浹四方，濃云来去勢何长。","曠然寰宇清风满，救旱功高暑氣涼。"]', '诗', 'shi', '', NULL, '陰雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3dd357-ff37-47a0-a9cc-7ec4acf7cd4c', '喜雨', '喜雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西北油然雲勢濃，須臾霶沛雨飄空。","頓疎萬物焦枯意，定看秋郊稼穡豐。"]', '["西北油然云勢濃，須臾霶沛雨飄空。","頓疎万物焦枯意，定看秋郊稼穡豐。"]', '诗', 'shi', '', NULL, '喜雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c69d9b47-c00d-430f-a5f7-d241f4294686', '過故洛城', '過故洛城', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故城門前春日斜，故城門裏無人家。","市朝欲認不知處，漠漠野田飛草花。"]', '["故城门前春日斜，故城门裏無人家。","市朝欲認不知处，漠漠野田飞草花。"]', '诗', 'shi', '', NULL, '過故洛城 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ef63d25-57f3-44a9-a3af-57b7f7a76842', '江南喜逢蕭九徹因話長安舊遊戲贈五十韻', '江南喜逢蕭九徹因話长安旧游戲贈五十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昔嬉遊伴，多陪歡宴場。","寓居同永樂，幽會共平康。","師子尋前曲，聲兒出內坊。","花深態奴宅，竹錯得憐堂。","庭晚開紅藥，門閑蔭綠楊。","經過悉同巷，居處盡連牆。","時世高梳髻，風流澹作妝。","戴花紅石竹，帔暈紫檳榔。","鬢動懸蟬翼，釵垂小鳳行。","拂胷輕粉絮，煖手小香囊。","選勝移銀燭，邀歡舉玉觴。","爐煙凝麝氣，酒色注鵝黃。","急管停還奏，繁弦慢更張。","雪飛迴舞袖，塵起繞歌梁。","舊曲翻調笑，新聲打義揚。","名情推阿軌，巧語許秋孃。","風暖春將暮，星迴夜未央。","宴餘添粉黛，坐久換衣裳。","結伴歸深院，分頭入洞房。","綵帷開翡翠，羅薦拂鴛鴦。","留宿爭牽袖，貪眠各占牀。","綠窗籠水影，紅壁背燈光。","索鏡收花鈿，邀人解袷襠。","暗嬌妝靨笑，私語口脂香。","怕聽鐘聲坐，羞明映縵藏。","眉殘蛾翠淺，鬟解綠雲長。","聚散知無定，憂歡事不常。","離筵開夕宴，別騎促晨裝。","去住青門外，留連滻水傍。","車行遙寄語，馬駐共相望。","雲雨分何處，山川共異方。","野行初寂莫，店宿乍恓惶。","別後嫌宵永，愁來厭歲芳。","幾看花結子，頻見露爲霜。","歲月何超忽，音容坐渺茫。","往還書斷絕，來去夢遊揚。","自我辭秦地，逢君客楚鄉。","常嗟異岐路，忽喜共舟航。","話舊堪垂淚，思鄉數斷腸。","愁雲接巫峽，淚竹近瀟湘。","月落江湖闊，天高節候涼。","浦深煙渺渺，沙冷月蒼蒼。","紅葉江楓老，青蕪驛路荒。","野風吹蟋蟀，湖水浸菰蔣。","帝路何由見，心期不可忘。","舊遊千里外，往事十年強。","春晝提壺飲，秋林摘橘嘗。","強歌還自感，縱飲不成狂。","永夜長相憶，逢君各共傷。","殷勤萬里意，幷寫贈蕭郎。"]', '["憶昔嬉游伴，多陪歡宴場。","寓居同永乐，幽會共平康。","師子尋前曲，声兒出內坊。","花深態奴宅，竹錯得怜堂。","庭晚开紅藥，门闲蔭綠楊。","經過悉同巷，居处尽連牆。","时世高梳髻，风流澹作妝。","戴花紅石竹，帔暈紫檳榔。","鬢动懸蟬翼，釵垂小鳳行。","拂胷轻粉絮，煖手小香囊。","選勝移銀燭，邀歡舉玉觴。","爐煙凝麝氣，酒色注鵝黄。","急管停還奏，繁弦慢更張。","雪飞迴舞袖，塵起繞歌梁。","旧曲翻調笑，新声打義揚。","名情推阿軌，巧語許秋孃。","风暖春將暮，星迴夜未央。","宴餘添粉黛，坐久換衣裳。","結伴归深院，分头入洞房。","綵帷开翡翠，羅薦拂鴛鴦。","留宿爭牽袖，貪眠各占牀。","綠窗籠水影，紅壁背灯光。","索镜收花鈿，邀人解袷襠。","暗嬌妝靨笑，私語口脂香。","怕听鐘声坐，羞明映縵藏。","眉殘蛾翠淺，鬟解綠云长。","聚散知無定，憂歡事不常。","離筵开夕宴，別騎促晨裝。","去住青门外，留連滻水傍。","车行遙寄語，马駐共相望。","云雨分何处，山川共異方。","野行初寂莫，店宿乍恓惶。","別後嫌宵永，愁来厭歲芳。","幾看花結子，頻见露爲霜。","歲月何超忽，音容坐渺茫。","往還书斷絕，来去梦游揚。","自我辞秦地，逢君客楚乡。","常嗟異岐路，忽喜共舟航。","話旧堪垂泪，思乡數斷腸。","愁云接巫峽，泪竹近瀟湘。","月落江湖闊，天高節候涼。","浦深煙渺渺，沙冷月蒼蒼。","紅葉江楓老，青蕪驛路荒。","野风吹蟋蟀，湖水浸菰蔣。","帝路何由见，心期不可忘。","旧游千里外，往事十年強。","春晝提壺饮，秋林摘橘嘗。","強歌還自感，縱饮不成狂。","永夜长相憶，逢君各共傷。","殷勤万里意，幷寫贈蕭郎。"]', '诗', 'shi', '', NULL, '江南喜逢蕭九徹因話長安舊遊戲贈五十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37ed807-84d5-4de8-9781-928cb16e602b', '贈薛濤', '贈薛濤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蛾眉山勢接雲霓，欲逐劉郎北路迷。","若似剡中容易到，春風猶隔武陵溪。"]', '["蛾眉山勢接云霓，欲逐劉郎北路迷。","若似剡中容易到，春风猶隔武陵溪。"]', '诗', 'shi', '', NULL, '贈薛濤 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40a0235-61c5-4cb6-b96c-471a62afac00', '酬令狐留守尚書見贈十韻', '酬令狐留守尚书见贈十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長慶清風在，夔龍燮理餘。","太和膏雨降，周邵保釐初。","嵩少當宮署，伊瀍入禁渠。","曉關開玉兔，夕鑰納銀魚。","舊眷憐移疾，新吟念索居。","離聲雙白鸝，行色一籃轝。","罷免無餘俸，休閑有敝廬。","慵於嵇叔夜，渴似馬相如。","酒每蒙酤我，詩嘗許起予。","洛中歸計定，一半爲尚書。"]', '["长慶清风在，夔龙燮理餘。","太和膏雨降，周邵保釐初。","嵩少當宮署，伊瀍入禁渠。","晓关开玉兔，夕鑰納銀鱼。","旧眷怜移疾，新吟念索居。","離声雙白鸝，行色一籃轝。","罷免無餘俸，休闲有敝廬。","慵於嵇叔夜，渴似马相如。","酒每蒙酤我，诗嘗許起予。","洛中归計定，一半爲尚书。"]', '诗', 'shi', '', NULL, '酬令狐留守尚書見贈十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1115e5-1ec9-41ec-aab8-d61af62debf2', '聽蘆管', '听蘆管', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["幽咽新蘆管，淒涼古竹枝。","似臨猨峽唱，疑在雁門吹。","調爲高多切，聲緣小乍遲。","麤豪嫌觱篥，細妙勝參差。","雲水巴南客，風沙隴上兒。","屈原收淚夜，蘇武斷腸時。","仰秣胡駒聽，驚栖越鳥知。","何言胡越異，聞此一同悲。"]', '["幽咽新蘆管，淒涼古竹枝。","似臨猨峽唱，疑在雁门吹。","調爲高多切，声緣小乍遲。","麤豪嫌觱篥，細妙勝參差。","云水巴南客，风沙隴上兒。","屈原收泪夜，蘇武斷腸时。","仰秣胡駒听，驚栖越鸟知。","何言胡越異，闻此一同悲。"]', '诗', 'shi', '', NULL, '聽蘆管 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ca2efb9-9c67-487e-b440-f1b8e77e158a', '送滕庶子致仕歸婺州', '送滕庶子致仕归婺州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春風秋月攜歌酒，八十年來翫物華。","已見曾孫騎竹馬，猶聽侍女唱梅花。","入鄉不杖歸時健，出郭乘軺到處誇。","兒著繡衣身衣錦，東陽門戶勝滕家。"]', '["春风秋月携歌酒，八十年来翫物华。","已见曾孫騎竹马，猶听侍女唱梅花。","入乡不杖归时健，出郭乘軺到处誇。","兒著繡衣身衣錦，东陽门戶勝滕家。"]', '诗', 'shi', '', NULL, '送滕庶子致仕歸婺州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6ebc85-65b1-4eb0-850e-0e36b8c80f58', '送劉郎中赴任蘇州', '送劉郎中赴任蘇州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["仁風膏雨去隨輪，勝境歡遊到逐身。","水驛路穿兒店月，花船棹入女湖春。","宣城獨詠窗中岫，柳惲單題汀上蘋。","何似姑蘇詩太守，吟詩相繼有三人。"]', '["仁风膏雨去隨輪，勝境歡游到逐身。","水驛路穿兒店月，花船棹入女湖春。","宣城独詠窗中岫，柳惲單題汀上蘋。","何似姑蘇诗太守，吟诗相繼有三人。"]', '诗', 'shi', '', NULL, '送劉郎中赴任蘇州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cec6558-dc6a-42bb-8e30-aef958651ca3', '福先寺雪中餞劉蘇州', '福先寺雪中餞劉蘇州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["送君何處展離筵，大梵王宮大雪天。","庾嶺梅花落歌管，謝家柳絮撲金田。","亂從紈袖交加舞，醉入籃轝取次眠。","却笑召鄒兼訪戴，只持空酒駕空船。"]', '["送君何处展離筵，大梵王宮大雪天。","庾嶺梅花落歌管，謝家柳絮撲金田。","亂從紈袖交加舞，醉入籃轝取次眠。","却笑召鄒兼訪戴，只持空酒駕空船。"]', '诗', 'shi', '', NULL, '福先寺雪中餞劉蘇州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5303d6b6-d8ee-46f2-ac9d-52466da37675', '除夜言懷兼贈張常侍', '除夜言懷兼贈張常侍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三百六旬今夜盡，六十四年明日催。","不用歎身隨日老，亦須知壽逐年來。","加添雪興憑氈帳，消殺春愁付酒杯。","唯恨詩成君去後，紅箋紙卷爲誰開。"]', '["三百六旬今夜尽，六十四年明日催。","不用歎身隨日老，亦須知壽逐年来。","加添雪兴憑氈帳，消殺春愁付酒杯。","唯恨诗成君去後，紅箋紙卷爲誰开。"]', '诗', 'shi', '', NULL, '除夜言懷兼贈張常侍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f47be53-0ab1-4098-a9f4-3471b730a781', '送張常侍西歸', '送張常侍西归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二年花下爲閑伴，一旦尊前棄老夫。","西午橋街行悵望，南龍興寺立踟躕。","洛城久住留情否，省騎重歸稱意無。","出鎮歸朝但相訪，此身應不離東都。"]', '["二年花下爲闲伴，一旦尊前棄老夫。","西午橋街行悵望，南龙兴寺立踟躕。","洛城久住留情否，省騎重归稱意無。","出鎮归朝但相訪，此身應不離东都。"]', '诗', 'shi', '', NULL, '送張常侍西歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20519800-0bd2-4ff2-855f-bda534f9b86f', '和河南鄭尹新歲對雪', '和河南鄭尹新歲对雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白雪吟詩鈴閣開，故情新興兩裴回。","昔經勤苦照書卷，今助歡娛飄酒杯。","楚客難酬郢中曲，吳公兼占洛陽才。","銅街金谷春知否，又有詩人作尹來。"]', '["白雪吟诗鈴閣开，故情新兴兩裴回。","昔經勤苦照书卷，今助歡娛飄酒杯。","楚客难酬郢中曲，吳公兼占洛陽才。","銅街金谷春知否，又有诗人作尹来。"]', '诗', 'shi', '', NULL, '和河南鄭尹新歲對雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56270098-2459-4746-af86-fb7ae3e2d86b', '吹笙內人出家', '吹笙內人出家', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雨露難忘君念重，電泡易滅妾身輕。","金刀已剃頭然髮，玉管休吹腸斷聲。","新戒珠從衣裏得，初心蓮向火中生。","道場夜半香花冷，猶在燈前禮佛名。"]', '["雨露难忘君念重，電泡易滅妾身轻。","金刀已剃头然髮，玉管休吹腸斷声。","新戒珠從衣裏得，初心蓮向火中生。","道場夜半香花冷，猶在灯前禮佛名。"]', '诗', 'shi', '', NULL, '吹笙內人出家 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf2a3ab-c8b5-423c-a2ae-07d7f89a5ef6', '醉中見微之舊卷有感', '醉中见微之旧卷有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝何事一霑襟，檢得君詩醉後吟。","老淚交流風病眼，春箋搖動酒杯心。","銀鉤塵覆年年暗，玉樹泥埋日日深。","聞道墓松高一丈，更無消息到如今。"]', '["今朝何事一霑襟，檢得君诗醉後吟。","老泪交流风病眼，春箋搖动酒杯心。","銀鉤塵覆年年暗，玉樹泥埋日日深。","闻道墓松高一丈，更無消息到如今。"]', '诗', 'shi', '', NULL, '醉中見微之舊卷有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b506fa81-e9ae-4f0d-9894-60960596655b', '壽安歇馬重吟', '壽安歇马重吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春衫細薄馬蹄輕，一日遲遲進一程。","野棗花含新蜜氣，山禽語帶破匏聲。","垂鞭晚就槐陰歇，低倡閑衝柳絮行。","忽憶家園須速去，櫻桃欲熟筍應生。"]', '["春衫細薄马蹄轻，一日遲遲進一程。","野棗花含新蜜氣，山禽語带破匏声。","垂鞭晚就槐陰歇，低倡闲衝柳絮行。","忽憶家园須速去，櫻桃欲熟筍應生。"]', '诗', 'shi', '', NULL, '壽安歇馬重吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcfc8ccb-85f4-4513-bef2-d60518fb3ec0', '贈張處士山人', '贈張处士山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘿襟蕙帶竹皮巾，雖到塵中不染塵。","每見俗人多慘澹，惟逢美酒即殷勤。","浮雲心事誰能會，老鶴風標不可親。","世說三生如不謬，共疑巢許是前身。"]', '["蘿襟蕙带竹皮巾，雖到塵中不染塵。","每见俗人多慘澹，惟逢美酒即殷勤。","浮云心事誰能會，老鹤风標不可親。","世说三生如不謬，共疑巢許是前身。"]', '诗', 'shi', '', NULL, '贈張處士山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b02a4b-7245-4e44-939b-ea2583bf285e', '池畔閑坐兼呈侍中', '池畔闲坐兼呈侍中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池畔最平處，樹陰新合時。","移牀解衣帶，坐任清風吹。","舉棹鳥先覺，垂綸魚未知。","前頭何所有，一卷晉公詩。"]', '["池畔最平处，樹陰新合时。","移牀解衣带，坐任清风吹。","舉棹鸟先覺，垂綸鱼未知。","前头何所有，一卷晉公诗。"]', '诗', 'shi', '', NULL, '池畔閑坐兼呈侍中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ea337c-7965-4311-a981-5bc124d9fabe', '初冬即事憶皇甫十', '初冬即事憶皇甫十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["冷竹風成韻，荒街葉作堆。","欲尋聯句卷，先飲煖寒杯。","帽爲迎霜戴，爐因試火開。","時時還有客，終不當君來。"]', '["冷竹风成韻，荒街葉作堆。","欲尋聯句卷，先饮煖寒杯。","帽爲迎霜戴，爐因試火开。","时时還有客，終不當君来。"]', '诗', 'shi', '', NULL, '初冬即事憶皇甫十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1abe55fd-feae-47a3-af80-b17efbb4b16f', '小庭寒夜寄夢得', '小庭寒夜寄梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["庭小同蝸舍，門閑稱雀羅。","火將燈共盡，風與雪相和。","老睡隨年減，衰情向夕多。","不知同病者，爭奈夜長何。"]', '["庭小同蝸舍，门闲稱雀羅。","火將灯共尽，风與雪相和。","老睡隨年減，衰情向夕多。","不知同病者，爭奈夜长何。"]', '诗', 'shi', '', NULL, '小庭寒夜寄夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b906b7b-3d76-415a-9742-0ec27d3d9e74', '西還壽安路西歇馬', '西還壽安路西歇马', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["槐陰歇鞍馬，柳絮惹衣巾。","日晚獨歸路，春深多思人。","去家纔百里，爲客只三旬。","已念紗窗下，應生寶瑟塵。"]', '["槐陰歇鞍马，柳絮惹衣巾。","日晚独归路，春深多思人。","去家纔百里，爲客只三旬。","已念紗窗下，應生寶瑟塵。"]', '诗', 'shi', '', NULL, '西還壽安路西歇馬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b579e871-dcea-4551-af1a-5fa02101790f', '雨中訪崔十八', '雨中訪崔十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["肩舁仍挈榼，莫怪就君來。","秋雨經三宿，無人勸一杯。"]', '["肩舁仍挈榼，莫怪就君来。","秋雨經三宿，無人勸一杯。"]', '诗', 'shi', '', NULL, '雨中訪崔十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f845b815-e1c5-4bb2-9bce-1400c18b6a80', '夢得得新詩', '梦得得新诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池上今宵風月涼，閑教少樂理霓裳。","集仙殿裏新詞到，便播笙歌作樂章。"]', '["池上今宵风月涼，闲教少乐理霓裳。","集仙殿裏新词到，便播笙歌作乐章。"]', '诗', 'shi', '', NULL, '夢得得新詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51196cf6-9352-4831-80a0-12aed62618d3', '初見劉二十八郎中有感', '初见劉二十八郎中有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲話毘陵君反袂，欲言夏口我霑衣。","誰知臨老相逢日，悲歎聲多語笑稀。"]', '["欲話毘陵君反袂，欲言夏口我霑衣。","誰知臨老相逢日，悲歎声多語笑稀。"]', '诗', 'shi', '', NULL, '初見劉二十八郎中有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3fb875f-d48b-4bce-8485-b4261cb18348', '夜題玉泉', '夜題玉泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遇客多言愛山水，逢僧盡道厭囂塵。","玉泉潭畔松間宿，要且經年無一人。"]', '["遇客多言愛山水，逢僧尽道厭囂塵。","玉泉潭畔松间宿，要且經年無一人。"]', '诗', 'shi', '', NULL, '夜題玉泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce175fe6-299b-4d60-b996-e56604bdc99a', '拜表早出贈皇甫賓客', '拜表早出贈皇甫賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一月一回同拜表，莫辭侵早過中橋。","老於君者應無數，猶趁西京十五朝。"]', '["一月一回同拜表，莫辞侵早過中橋。","老於君者應無數，猶趁西京十五朝。"]', '诗', 'shi', '', NULL, '拜表早出贈皇甫賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b30e493-cb22-4113-8591-ec86070e93e8', '贈鄭尹', '贈鄭尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["府池東北舊亭臺，久別長思醉一回。","但請主人空埽地，自攜杯酒管弦來。"]', '["府池东北旧亭台，久別长思醉一回。","但請主人空埽地，自携杯酒管弦来。"]', '诗', 'shi', '', NULL, '贈鄭尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7d2368-f4ec-400a-bb7c-617323156c10', '別楊同州後却寄', '別楊同州後却寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潘驛橋南醉中別，下邽村北醒時歸。","春風怪我君知否，榆葉楊花撲面飛。"]', '["潘驛橋南醉中別，下邽村北醒时归。","春风怪我君知否，榆葉楊花撲面飞。"]', '诗', 'shi', '', NULL, '別楊同州後却寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('977ecaec-3922-4c0d-9cd5-df1c7fd582a3', '狐泉店前作', '狐泉店前作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野狐泉上柳花飛，逐水東流便不歸。","花水悠悠兩無意，因風吹落偶相依。"]', '["野狐泉上柳花飞，逐水东流便不归。","花水悠悠兩無意，因风吹落偶相依。"]', '诗', 'shi', '', NULL, '狐泉店前作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f37335b1-5784-4e5c-914e-b24f19a7f572', '贈盧績', '贈盧績', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["餘杭縣裏盧明府，虛白亭中白舍人。","今日相逢頭似雪，一杯相勸送殘春。"]', '["餘杭縣裏盧明府，虛白亭中白舍人。","今日相逢头似雪，一杯相勸送殘春。"]', '诗', 'shi', '', NULL, '贈盧績 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adca7e05-f093-4786-b5a5-770c2367d2c7', '與裴華州同過敷水戲贈', '與裴华州同過敷水戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["使君五馬且蜘躕，馬上能聽絕句無。","每過桑間試留意，何妨後代有羅敷。"]', '["使君五马且蜘躕，马上能听絕句無。","每過桑间試留意，何妨後代有羅敷。"]', '诗', 'shi', '', NULL, '與裴華州同過敷水戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8fd7467-c5e8-4c6b-b534-a4d35a567768', '閑遊', '闲游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲笑隨情酒逐身，此身雖老未辜春。","春來點檢閑遊數，猶自多於年少人。"]', '["欲笑隨情酒逐身，此身雖老未辜春。","春来点檢闲游數，猶自多於年少人。"]', '诗', 'shi', '', NULL, '閑遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad862e81-84e0-4999-bebb-c7b0b7af2ca1', '招韜光禪師', '招韜光禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白屋炊香飯，葷膻不入家。","濾泉澄葛粉，洗手摘藤花。","青芥除黃葉，紅薑帶紫芽。","命師相伴食，齋罷一甌茶。"]', '["白屋炊香飯，葷膻不入家。","濾泉澄葛粉，洗手摘藤花。","青芥除黄葉，紅薑带紫芽。","命師相伴食，斋罷一甌茶。"]', '诗', 'shi', '', NULL, '招韜光禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d9794a-0ef0-4e93-a798-f72d56d4f094', '和柳公權登齊雲樓', '和柳公權登齊云楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樓外春晴百鳥鳴，樓中春酒美人傾。","路傍花日添衣色，雲裏天風散珮聲。","向此高吟誰得意，偶來閑客獨多情。","佳時莫起興亡恨，遊樂今逢四海清。"]', '["楼外春晴百鸟鳴，楼中春酒美人傾。","路傍花日添衣色，云裏天风散珮声。","向此高吟誰得意，偶来闲客独多情。","佳时莫起兴亡恨，游乐今逢四海清。"]', '诗', 'shi', '', NULL, '和柳公權登齊雲樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01105fdb-a111-4cf8-b25c-a01172a435fe', '毛公壇', '毛公壇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["毛公壇上片雲閑，得道何年去不還。","千載鶴翎歸碧落，五湖空鎮萬重山。"]', '["毛公壇上片云闲，得道何年去不還。","千載鹤翎归碧落，五湖空鎮万重山。"]', '诗', 'shi', '', NULL, '毛公壇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab0c899-7e8b-4126-abf8-c83376a18c40', '靈巖寺', '靈巖寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["館娃宮畔千年寺，水闊雲多客到稀。","聞說春來更惆悵，百花深處一僧歸。"]', '["館娃宮畔千年寺，水闊云多客到稀。","闻说春来更惆悵，百花深处一僧归。"]', '诗', 'shi', '', NULL, '靈巖寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83284bf1-8b8e-4deb-a29d-6aa9cfaf7184', '白雲泉', '白云泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天平山上白雲泉，雲自無心水自閑。","何必奔衝山下去，更添波浪向人間。"]', '["天平山上白云泉，云自無心水自闲。","何必奔衝山下去，更添波浪向人间。"]', '诗', 'shi', '', NULL, '白雲泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7032e43-846d-4583-a2f7-f60598f0d256', '寄韜光禪師', '寄韜光禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一山門作兩山門，兩寺原從一寺分。","東澗水流西澗水，南山雲起北山雲。","前臺花發後臺見，上界鐘聲下界聞。","遙想吾師行道處，天香桂子落紛紛。"]', '["一山门作兩山门，兩寺原從一寺分。","东澗水流西澗水，南山云起北山云。","前台花發後台见，上界鐘声下界闻。","遙想吾師行道处，天香桂子落紛紛。"]', '诗', 'shi', '', NULL, '寄韜光禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a721b13c-026d-4142-a1ac-b1a8cfad5959', '和夢得夏至憶蘇州呈盧賓客', '和梦得夏至憶蘇州呈盧賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶在蘇州日，常諳夏至筵。","糉香筒竹嫩，炙脆子鵝鮮。","水國多臺榭，吳風尚管弦。","每家皆有酒，無處不過船。","交印君相次，褰帷我在前。","此鄉俱老矣，東望共依然。","洛下麥秋月，江南梅雨天。","齊雲樓上事，已上十三年。"]', '["憶在蘇州日，常諳夏至筵。","糉香筒竹嫩，炙脆子鵝鲜。","水国多台榭，吳风尚管弦。","每家皆有酒，無处不過船。","交印君相次，褰帷我在前。","此乡俱老矣，东望共依然。","洛下麦秋月，江南梅雨天。","齊云楼上事，已上十三年。"]', '诗', 'shi', '', NULL, '和夢得夏至憶蘇州呈盧賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a145f815-8e48-4f29-8f2b-ef8e1eb82947', '曲江', '曲江', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["細草岸西東，酒旗搖水風。","樓臺在花杪，鷗鷺下煙中。","翠幄晴相接，芳洲夜暫空。","何人賞秋景，興與此時同。"]', '["細草岸西东，酒旗搖水风。","楼台在花杪，鷗鷺下煙中。","翠幄晴相接，芳洲夜暫空。","何人賞秋景，兴與此时同。"]', '诗', 'shi', '', NULL, '曲江 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a749faf-8fea-46b9-b194-b17a4f034ffa', '歲夜詠懷兼寄思黯', '歲夜詠懷兼寄思黯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["徧數故交親，何人得六旬。","今年已入手，餘事豈關身。","老自無多興，春應不揀人。","陶窗與弘閣，風景一時新。"]', '["徧數故交親，何人得六旬。","今年已入手，餘事豈关身。","老自無多兴，春應不揀人。","陶窗與弘閣，风景一时新。"]', '诗', 'shi', '', NULL, '歲夜詠懷兼寄思黯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eadd591-9b76-4772-a1b4-b8930e47b849', '寒食日過棗糰店', '寒食日過棗糰店', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寒食棗糰店，春低楊柳枝。","酒香留客住，鶯語和人詩。","困立攀花久，慵行上馬遲。","若爲將此意，前字與僧期。"]', '["寒食棗糰店，春低楊柳枝。","酒香留客住，鶯語和人诗。","困立攀花久，慵行上马遲。","若爲將此意，前字與僧期。"]', '诗', 'shi', '', NULL, '寒食日過棗糰店 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf1e46fd-32d1-4ee7-938d-49cc27acf1f3', '宿張雲舉院', '宿張云舉院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不食胡麻飯，杯中自得仙。","隔房招好客，可室致芳筵。","美醞香醪嫩，時新異果鮮。","夜深唯畏曉，坐穩不思眠。","棊罷嫌無敵，詩成媿在前。","明朝題壁上，誰得衆人傳。"]', '["不食胡麻飯，杯中自得仙。","隔房招好客，可室致芳筵。","美醞香醪嫩，时新異果鲜。","夜深唯畏晓，坐穩不思眠。","棊罷嫌無敵，诗成媿在前。","明朝題壁上，誰得衆人傳。"]', '诗', 'shi', '', NULL, '宿張雲舉院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bea62be5-4953-4fb1-80aa-dd4d0eb8c215', '惜花', '惜花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["可憐夭豔正當時，剛被狂風一夜吹。","今日流鶯來舊處，百般言語泥空枝。"]', '["可怜夭豔正當时，剛被狂风一夜吹。","今日流鶯来旧处，百般言語泥空枝。"]', '诗', 'shi', '', NULL, '惜花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97bd0ba1-a40b-4bf0-b044-f7a3e70eb02c', '七夕', '七夕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙霄微月澹長空，銀漢秋期萬古同。","幾許歡情與離恨，年年幷在此宵中。"]', '["煙霄微月澹长空，銀漢秋期万古同。","幾許歡情與離恨，年年幷在此宵中。"]', '诗', 'shi', '', NULL, '七夕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f447099a-821e-497b-99c1-47064fdff2fa', '宿誠禪師山房題贈', '宿誠禪師山房題贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不出孤峰上，人間四十秋。","視身如傳舍，閱世任東流。","法爲因緣立，心從次第脩。","中宵問真偈，有住是吾憂。"]', '["不出孤峰上，人间四十秋。","視身如傳舍，閱世任东流。","法爲因緣立，心從次第脩。","中宵问真偈，有住是吾憂。"]', '诗', 'shi', '', NULL, '宿誠禪師山房題贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a748c0-ba13-4810-b138-ab5fd7df93a3', '新池', '新池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["數日自穿鑿，引泉來近陂。","尋渠通咽處，繞岸待清時。","深好求魚養，閑堪與鶴期。","幽聲聽難盡，入夜睡常遲。"]', '["數日自穿鑿，引泉来近陂。","尋渠通咽处，繞岸待清时。","深好求鱼養，闲堪與鹤期。","幽声听难尽，入夜睡常遲。"]', '诗', 'shi', '', NULL, '新池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c594f6-47ec-4008-a541-c5ad7b1b13de', '南池', '南池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕭條微雨絕，荒岸抱清源。","入舫山侵塞，分泉道接邨。","秋聲依樹色，月影在蒲根。","淹泊方難遂，他宵關夢魂。"]', '["蕭條微雨絕，荒岸抱清源。","入舫山侵塞，分泉道接邨。","秋声依樹色，月影在蒲根。","淹泊方难遂，他宵关梦魂。"]', '诗', 'shi', '', NULL, '南池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2c3dfd-288b-4b0d-8c46-583e6a841b4b', '宿池上', '宿池上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["泉來從絕壑，亭敞在中流。","竹密無空岸，松長可絆舟。","蟪蛄潭上夜，河漢島前秋。","異夕期新漲，攜琴却此遊。"]', '["泉来從絕壑，亭敞在中流。","竹密無空岸，松长可絆舟。","蟪蛄潭上夜，河漢島前秋。","異夕期新漲，携琴却此游。"]', '诗', 'shi', '', NULL, '宿池上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f5a717-b877-4d0b-b5df-f1bf0821dcb4', '翻經臺', '翻經台', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一會靈山猶未散，重翻貝葉有來由。","是名精進纔開眼，巖石無端亦點頭。"]', '["一會靈山猶未散，重翻貝葉有来由。","是名精進纔开眼，巖石無端亦点头。"]', '诗', 'shi', '', NULL, '翻經臺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67ae99f0-5748-4dd0-bdb5-7ed8b72c754d', '寄題上強山精舍寺', '寄題上強山精舍寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慣遊山水住南州，行盡天台及虎丘。","惟有上強精舍寺，最堪遊處未曾遊。"]', '["慣游山水住南州，行尽天台及虎丘。","惟有上強精舍寺，最堪游处未曾游。"]', '诗', 'shi', '', NULL, '寄題上強山精舍寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('177fba37-6b56-40cc-9592-88d4e23aa65b', '一字至七字詩', '一字至七字诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["詩，綺美，瓌奇。","明月夜，落花時。","能助歡笑，亦傷別離。","調清金石怨，吟苦鬼神悲。","天下只應我愛，世間唯有君知。","自從都尉別蘇句，便到司空送白辭。"]', '["诗，綺美，瓌奇。","明月夜，落花时。","能助歡笑，亦傷別離。","調清金石怨，吟苦鬼神悲。","天下只應我愛，世间唯有君知。","自從都尉別蘇句，便到司空送白辞。"]', '诗', 'shi', '', NULL, '一字至七字詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab7da5f-f21f-4ef1-8c55-c43d91d3381c', '九老圖詩', '九老圖诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪作鬚眉雲作衣，遼東華表鶴雙歸。","當時一鶴猶希有，何況今逢兩令威。"]', '["雪作鬚眉云作衣，遼东华表鹤雙归。","當时一鹤猶希有，何況今逢兩令威。"]', '诗', 'shi', '', NULL, '九老圖詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3432d1a3-736c-4483-a727-d0d405acea34', '和裴相公傍水閑行絕句', '和裴相公傍水闲行絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["行尋春水坐看山，早出中書晚未還。","爲報野僧巖客道，偷閑氣味勝長閑。"]', '["行尋春水坐看山，早出中书晚未還。","爲報野僧巖客道，偷闲氣味勝长闲。"]', '诗', 'shi', '', NULL, '和裴相公傍水閑行絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3b8f8a-a441-4ec9-95a6-aee566a486a4', '七老會詩', '七老會诗', '0a71cad5-0065-4873-aaf6-2eeee3ca4cec', '唐', '["閑居同會在三春，大抵愚年最出羣。","霜鬢不嫌杯酒興，白頭仍愛玉爐熏。","裴回玩柳心猶健，老大看花意却勤。","鑿落滿斟判酩酊，香囊高挂任氤氳。","搜神得句題紅葉，望景長吟對白雲。","今日交情何不替？齊年同事聖明君。"]', '["闲居同會在三春，大抵愚年最出羣。","霜鬢不嫌杯酒兴，白头仍愛玉爐熏。","裴回玩柳心猶健，老大看花意却勤。","鑿落满斟判酩酊，香囊高挂任氤氳。","搜神得句題紅葉，望景长吟对白云。","今日交情何不替？齊年同事聖明君。"]', '诗', 'shi', '', NULL, '七老會詩 胡杲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4056bdfc-5723-4a12-984e-08331e3021b3', '七老會詩', '七老會诗', 'f06b18d3-09b0-4aa6-8036-50b622ecca64', '唐', '["休官罷任已閑居，林苑園亭興有餘。","對酒最宜花藻發，邀歡不厭柳條初。","低腰醉舞垂緋袖，擊筑謳歌任褐裾。","寧用管弦來合雜，自親松竹且清虛。","飛觥酒到須先酌，賦詠成詩不住書。","借問商山賢四皓，不如此後更何如。"]', '["休官罷任已闲居，林苑园亭兴有餘。","对酒最宜花藻發，邀歡不厭柳條初。","低腰醉舞垂緋袖，擊筑謳歌任褐裾。","寧用管弦来合杂，自親松竹且清虛。","飞觥酒到須先酌，賦詠成诗不住书。","借问商山賢四皓，不如此後更何如。"]', '诗', 'shi', '', NULL, '七老會詩 吉皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc230638-0d66-4173-97da-1b105c8583a5', '七老會詩', '七老會诗', 'ebc03e1c-9efc-4fd0-84e6-20b53dcee048', '唐', '["垂絲今日幸同筵，朱紫居身是大年。","賞景尚知心未退，吟詩猶覺力完全。","閑庭飲酒當三月，在席揮毫象七賢。","山茗煮時秋霧碧，玉杯斟處彩霞鮮。","臨堦花笑如歌妓，傍竹松聲當管弦。","雖未學窮生死訣，人間豈不是神仙。"]', '["垂絲今日幸同筵，朱紫居身是大年。","賞景尚知心未退，吟诗猶覺力完全。","闲庭饮酒當三月，在席揮毫象七賢。","山茗煮时秋霧碧，玉杯斟处彩霞鲜。","臨堦花笑如歌妓，傍竹松声當管弦。","雖未学窮生死訣，人间豈不是神仙。"]', '诗', 'shi', '', NULL, '七老會詩 劉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c747250f-d2c1-4419-b630-b3ba4badbac2', '七老會詩', '七老會诗', 'd931fc87-8bd9-45b0-ab08-73898f4c1290', '唐', '["東洛幽閑日暮春，邀歡多是白頭賓。","官班朱紫多相似，年紀高低次第勻。","聯句每言松竹意，停杯多說古今人。","更無外事來心肺，空有清虛入思神。","醉舞兩回迎勸酒，狂歌一曲會娛身。","今朝何事偏情重，同作明時列任臣。"]', '["东洛幽闲日暮春，邀歡多是白头賓。","官班朱紫多相似，年紀高低次第勻。","聯句每言松竹意，停杯多说古今人。","更無外事来心肺，空有清虛入思神。","醉舞兩回迎勸酒，狂歌一曲會娛身。","今朝何事偏情重，同作明时列任臣。"]', '诗', 'shi', '', NULL, '七老會詩 鄭據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('336bb957-2e93-4de4-9b17-379e41afac34', '七老會詩', '七老會诗', 'd09d926d-e13e-4a4f-9d93-4cf69b24e1d4', '唐', '["三春已盡洛陽宮，天氣初晴景象中。","千朵嫩桃迎曉日，萬株垂柳逐和風。","非論官位皆相似，及至年高亦共同。","對酒歌聲猶覺妙，玩花詩思豈能窮。","先時共作三朝貴，今日猶逢七老翁。","但願醁醽常滿酌，煙霞萬里會應同。"]', '["三春已尽洛陽宮，天氣初晴景象中。","千朵嫩桃迎晓日，万株垂柳逐和风。","非論官位皆相似，及至年高亦共同。","对酒歌声猶覺妙，玩花诗思豈能窮。","先时共作三朝貴，今日猶逢七老翁。","但願醁醽常满酌，煙霞万里會應同。"]', '诗', 'shi', '', NULL, '七老會詩 盧真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('263c8159-087f-4d95-8c18-63406c69450c', '七老會詩', '七老會诗', 'f425e2f7-a920-4596-89ac-2b10f2413b53', '唐', '["幽亭春盡共爲歡，印綬居身是大官。","遁跡豈勞登遠岫，垂絲何必坐谿磻。","詩聯七韻猶應易，酒飲三杯未覺難。","每況襟懷同宴會，共將心事比波瀾。","風吹野柳垂羅帶，日照庭花落綺紈。","此席不煩鋪錦帳，斯筵堪作畫圖看。"]', '["幽亭春尽共爲歡，印綬居身是大官。","遁跡豈勞登远岫，垂絲何必坐谿磻。","诗聯七韻猶應易，酒饮三杯未覺难。","每況襟懷同宴會，共將心事比波瀾。","风吹野柳垂羅带，日照庭花落綺紈。","此席不煩鋪錦帳，斯筵堪作畫圖看。"]', '诗', 'shi', '', NULL, '七老會詩 張渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8557aa7d-f5cd-4ea2-841a-3df57d855943', '一字至七字詩 竹', '一字至七字诗 竹', '7bcca27a-972e-450a-b44b-397e0682472c', '唐', '["竹，臨池，似玉。","裛露靜，和煙綠。","抱節寧改，貞心自束。","渭曲偏種多，王家看不足。","仙杖正驚龍化，美實當隨鳳熟。","唯愁吹作別離聲，回首駕驂舞陣速。"]', '["竹，臨池，似玉。","裛露静，和煙綠。","抱節寧改，貞心自束。","渭曲偏種多，王家看不足。","仙杖正驚龙化，美實當隨鳳熟。","唯愁吹作別離声，回首駕驂舞陣速。"]', '诗', 'shi', '', NULL, '一字至七字詩 竹 韋式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b606e102-4e53-48df-95b7-0574bd7c6979', '奉和白太守揀橘', '奉和白太守揀橘', 'd26774bd-6a01-423c-b1c1-fa88de5f1ce6', '唐', '["凌霜遠涉太湖深，雙卷朱旗望橘林。","樹樹籠煙疑帶火，山山照日似懸金。","行看採掇方盈手，暗覺馨香已滿襟。","揀選封題皆盡力，無人不感近臣心。"]', '["凌霜远涉太湖深，雙卷朱旗望橘林。","樹樹籠煙疑带火，山山照日似懸金。","行看採掇方盈手，暗覺馨香已满襟。","揀選封題皆尽力，無人不感近臣心。"]', '诗', 'shi', '', NULL, '奉和白太守揀橘 張彤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f0d6341-09f4-4227-9256-1649c3049705', '和白太守揀貢橘', '和白太守揀貢橘', '44304464-87c5-4dd8-8110-96fedd4b1a27', '唐', '["離離朱實綠叢中，似火燒山處處紅。","影下寒林沈綠水，光搖高樹照晴空。","銀章自竭人臣力，玉液誰知造化功。","看取明朝船發後，餘香猶尚逐仁風。"]', '["離離朱實綠叢中，似火燒山处处紅。","影下寒林沈綠水，光搖高樹照晴空。","銀章自竭人臣力，玉液誰知造化功。","看取明朝船發後，餘香猶尚逐仁风。"]', '诗', 'shi', '', NULL, '和白太守揀貢橘 周元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2921af23-6e9d-49fb-9f7c-46282b1797fc', '句', '句', '44304464-87c5-4dd8-8110-96fedd4b1a27', '唐', '["誰云蒿上煙，隨雲依碧落。","莫怪西陵風景別，鏡湖花草爲先春。"]', '["誰云蒿上煙，隨云依碧落。","莫怪西陵风景別，镜湖花草爲先春。"]', '诗', 'shi', '', NULL, '句 周元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd493e0-73cb-4163-812c-3cf445e1074d', '書巫山神女祠', '书巫山神女祠', 'ea051bc0-bc68-434f-9b68-ab017fd2171f', '唐', '["忠州刺史今才子，行到巫山必有詩。","爲報高唐神女道，速排雲雨候清詞。"]', '["忠州刺史今才子，行到巫山必有诗。","爲報高唐神女道，速排云雨候清词。"]', '诗', 'shi', '', NULL, '書巫山神女祠 繁知一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e62ce3-fe42-431a-acee-3c59b1cf2876', '唐昌觀玉蘂花折有仙人遊悵然成二絕 一', '唐昌观玉蘂花折有仙人游悵然成二絕 一', '46eaa6d4-eab7-4a4b-810b-7675994b2d6c', '唐', '["終日齋心禱玉宸，魂銷目斷未逢真。","不如滿樹瓊瑤蘂，笑對藏花洞裏人。"]', '["終日斋心禱玉宸，魂銷目斷未逢真。","不如满樹瓊瑤蘂，笑对藏花洞裏人。"]', '诗', 'shi', '', NULL, '唐昌觀玉蘂花折有仙人遊悵然成二絕 一 嚴休復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e849a36-6dba-4dca-a9ed-7b806d1975cc', '唐昌觀玉蘂花折有仙人遊悵然成二絕 二', '唐昌观玉蘂花折有仙人游悵然成二絕 二', '46eaa6d4-eab7-4a4b-810b-7675994b2d6c', '唐', '["羽車潛下玉龜山，塵世何由覩蕣顏。","唯有多情枝上雪，好風吹綴綠雲鬟。"]', '["羽车潛下玉龟山，塵世何由覩蕣顏。","唯有多情枝上雪，好风吹綴綠云鬟。"]', '诗', 'shi', '', NULL, '唐昌觀玉蘂花折有仙人遊悵然成二絕 二 嚴休復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6743f4-806a-49e8-8a21-d415aae1df9a', '江亭寓目', '江亭寓目', '6da78acc-ff87-45fc-9002-c092cec68bd2', '唐', '["江郭帶林巒，津亭倚檻看。","水風蒲葉戰，沙雨鷺鶿寒。","晚木初凋柳，秋叢欲敗蘭。","哀猨自相叫，鄉淚好無端。"]', '["江郭带林巒，津亭倚檻看。","水风蒲葉戰，沙雨鷺鶿寒。","晚木初凋柳，秋叢欲敗蘭。","哀猨自相叫，乡泪好無端。"]', '诗', 'shi', '', NULL, '江亭寓目 盧拱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc2a2b5-9288-41c5-9394-fda3c93e5cca', '中元日觀法事', '中元日观法事', '6da78acc-ff87-45fc-9002-c092cec68bd2', '唐', '["四孟逢秋序，三元得氣中。","雲迎碧落步，章奏玉皇宮。","壇滴槐花露，香飄栢子風。","羽衣凌縹緲，瑤轂輾虛空。","久慕餐霞客，常悲習蓼蟲。","青囊如可授，從此訪鴻蒙。"]', '["四孟逢秋序，三元得氣中。","云迎碧落步，章奏玉皇宮。","壇滴槐花露，香飄栢子风。","羽衣凌縹緲，瑤轂輾虛空。","久慕餐霞客，常悲習蓼蟲。","青囊如可授，從此訪鴻蒙。"]', '诗', 'shi', '', NULL, '中元日觀法事 盧拱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652a83fe-31eb-481e-b136-2a340129c03c', '句', '句', '6da78acc-ff87-45fc-9002-c092cec68bd2', '唐', '["地甃如拳石，溪橫似葉舟。"]', '["地甃如拳石，溪橫似葉舟。"]', '诗', 'shi', '', NULL, '句 盧拱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308213b8-4138-4386-a68d-f0591f3d019b', '蘇州元日郡齋感懷寄越州元相公杭州白舍人', '蘇州元日郡斋感懷寄越州元相公杭州白舍人', '3de08808-24cc-4d85-80aa-524c0b0ac705', '唐', '["稱慶還鄉郡吏歸，端憂明發儼朝衣。","首開三百六旬日，新知四十九年非。","當官補拙猶勤慮，游宦量才已息機。","舉族共資隨月俸，一身惟憶故山薇。","舊交邂逅封疆近，老牧蕭條宴賞稀。","書札每來同笑語，篇章時到借光輝。","絲綸暫厭分符竹，舟檝初登擁羽旗。","未知今日情何似，應與幽人事有違。"]', '["稱慶還乡郡吏归，端憂明發儼朝衣。","首开三百六旬日，新知四十九年非。","當官補拙猶勤慮，游宦量才已息機。","舉族共資隨月俸，一身惟憶故山薇。","旧交邂逅封疆近，老牧蕭條宴賞稀。","书札每来同笑語，篇章时到借光輝。","絲綸暫厭分符竹，舟檝初登擁羽旗。","未知今日情何似，應與幽人事有違。"]', '诗', 'shi', '', NULL, '蘇州元日郡齋感懷寄越州元相公杭州白舍人 李諒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2045c179-4465-4d77-9760-8abb6c8ae168', '月生', '月生', '88d66830-1141-45cb-9d7f-ba7b9b7935fd', '唐', '["月生十五前，日望光彩圓。","月滿十五後，日畏光彩瘦。","不見夜花色，一尊成暗酒。","匣中苔背銅，光短不照空。","不惜補明月，慚無此良工。"]', '["月生十五前，日望光彩圓。","月满十五後，日畏光彩瘦。","不见夜花色，一尊成暗酒。","匣中苔背銅，光短不照空。","不惜補明月，慚無此良工。"]', '诗', 'shi', '', NULL, '月生 劉猛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e69c54f3-6656-40d8-8072-e11ca8f41f5e', '苦雨', '苦雨', '88d66830-1141-45cb-9d7f-ba7b9b7935fd', '唐', '["自念數年間，兩手中藏鉤。","於心且無恨，他日爲我羞。","古老傳童歌，連淫亦兵象。","夜夢戈甲鳴，苦不願年長。"]', '["自念數年间，兩手中藏鉤。","於心且無恨，他日爲我羞。","古老傳童歌，連淫亦兵象。","夜梦戈甲鳴，苦不願年长。"]', '诗', 'shi', '', NULL, '苦雨 劉猛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6985e295-03ae-4cc2-8fc3-3d2b48a5a8ed', '曉', '晓', '88d66830-1141-45cb-9d7f-ba7b9b7935fd', '唐', '["朝梳一把白，夜淚千滴雨。","可恥垂拱時，老作在家女。"]', '["朝梳一把白，夜泪千滴雨。","可恥垂拱时，老作在家女。"]', '诗', 'shi', '', NULL, '曉 劉猛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1841a7-9041-4e63-bc2b-d69c8170c38a', '獻盧尚書', '獻盧尚书', '3c41f370-40df-4791-b49f-533dd29cfe30', '唐', '["荷衣拭淚幾回穿，欲謁朱門抵上天。","不是尚書輕下客，山家無物與王權。"]', '["荷衣拭泪幾回穿，欲謁朱门抵上天。","不是尚书轻下客，山家無物與王權。"]', '诗', 'shi', '', NULL, '獻盧尚書 萬彤雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('427d14b2-8dbe-4d99-84e8-a9da68cafc0a', '和白尚書賦永豐柳', '和白尚书賦永豐柳', 'd3b7ce71-9ac2-4997-b8c1-4da0db5a9411', '唐', '["一樹依依在永豐，兩枝飛去杳無蹤。","玉皇曾採人間曲，應逐歌聲入九重。"]', '["一樹依依在永豐，兩枝飞去杳無蹤。","玉皇曾採人间曲，應逐歌声入九重。"]', '诗', 'shi', '', NULL, '和白尚書賦永豐柳 盧貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4c077d-1458-455a-a14c-7883b2dff50b', '和劉夢得歲夜懷友', '和劉梦得歲夜懷友', 'd3b7ce71-9ac2-4997-b8c1-4da0db5a9411', '唐', '["文翰走天下，琴尊臥洛陽。","貞元朝士盡，新歲一悲涼。","名早緣才大，官遲爲壽長。","時來知病已，莫歎步趨妨。"]', '["文翰走天下，琴尊臥洛陽。","貞元朝士尽，新歲一悲涼。","名早緣才大，官遲爲壽长。","时来知病已，莫歎步趨妨。"]', '诗', 'shi', '', NULL, '和劉夢得歲夜懷友 盧貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5d219f8-8b1d-48ff-a988-e478cc65e668', '和李校書雨中自秘省見訪知早入朝便入集賢不遇詩', '和李校书雨中自秘省见訪知早入朝便入集賢不遇诗', 'de55721c-a41e-4164-a6f5-743b43d76a35', '唐', '["台庭才子來欵扉，典校初從天祿歸。","已慙陋巷迴玉趾，仍聞細雨霑綵衣。","詰朝始趨鳳闕去，此日遂愁雞黍違。","憶昨謬官在烏府，喜君對門討魚魯。","直廬相望夜每闌，高閣遙臨月時吐。","昔聞三入承明廬，今來重入中秘書。","校文復忝丞相屬，博物更與張侯居。","新冠峩峩不變鐵，舊泉脉脈猶在渠。","忽枉情人吐芳訊，臨風不羨潘錦舒。","憶見青天霞未卷，吟翫瑤華不知晚。","自憐豈是風引舟，如何漸與蓬山遠。"]', '["台庭才子来欵扉，典校初從天祿归。","已慙陋巷迴玉趾，仍闻細雨霑綵衣。","詰朝始趨鳳闕去，此日遂愁雞黍違。","憶昨謬官在烏府，喜君对门討鱼魯。","直廬相望夜每闌，高閣遙臨月时吐。","昔闻三入承明廬，今来重入中秘书。","校文复忝丞相屬，博物更與張侯居。","新冠峩峩不变鐵，旧泉脉脈猶在渠。","忽枉情人吐芳訊，臨风不羨潘錦舒。","憶见青天霞未卷，吟翫瑤华不知晚。","自怜豈是风引舟，如何漸與蓬山远。"]', '诗', 'shi', '', NULL, '和李校書雨中自秘省見訪知早入朝便入集賢不遇詩 王起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf241e4f-c01f-4429-80ef-62cebff79a68', '貢舉人謁先師聞雅樂', '貢舉人謁先師闻雅乐', 'de55721c-a41e-4164-a6f5-743b43d76a35', '唐', '["藹藹觀光士，來同鵠鷺羣。","鞠躬遺像在，稽首雅歌聞。","度曲飄清漢，餘音遏曉雲。","兩楹淒已合，九仞杳難分。","斷續同清吹，洪纖入紫氛。","長言聽已罷，千載仰斯文。"]', '["藹藹观光士，来同鵠鷺羣。","鞠躬遺像在，稽首雅歌闻。","度曲飄清漢，餘音遏晓云。","兩楹淒已合，九仞杳难分。","斷續同清吹，洪纖入紫氛。","长言听已罷，千載仰斯文。"]', '诗', 'shi', '', NULL, '貢舉人謁先師聞雅樂 王起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4767cbe-61c2-4885-a1e7-796313d295c8', '濁水求珠', '濁水求珠', 'de55721c-a41e-4164-a6f5-743b43d76a35', '唐', '["行潦沈明月，光輝也不浮。","識珍能洞鑒，精寶此來求。","幾被泥沙雜，常隨混濁流。","潤川終自媚，照乘且何由。","的皪終難掩，晶熒願見收。","蛇行無脛至，飲德已聞酬。"]', '["行潦沈明月，光輝也不浮。","識珍能洞鑒，精寶此来求。","幾被泥沙杂，常隨混濁流。","潤川終自媚，照乘且何由。","的皪終难掩，晶熒願见收。","蛇行無脛至，饮德已闻酬。"]', '诗', 'shi', '', NULL, '濁水求珠 王起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f0084f4-da0e-437d-8c17-026280cd427a', '和周侍郎見寄', '和周侍郎见寄', 'de55721c-a41e-4164-a6f5-743b43d76a35', '唐', '["貢院離來二十霜，誰知更忝主文場。","楊葉縱能穿舊的，桂枝何必愛新香。","九重每憶同仙禁，六義初吟得夜光。","莫道相知不相見，蓮峰之下欲徵黃。"]', '["貢院離来二十霜，誰知更忝主文場。","楊葉縱能穿旧的，桂枝何必愛新香。","九重每憶同仙禁，六義初吟得夜光。","莫道相知不相见，蓮峰之下欲徵黄。"]', '诗', 'shi', '', NULL, '和周侍郎見寄 王起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97504d49-e5d5-44e7-b0a7-feeb27e97e9d', '贈毛仙翁', '贈毛仙翁', 'de55721c-a41e-4164-a6f5-743b43d76a35', '唐', '["冰霜肌骨稱童年，羽駕何由到俗間。","丹竈化金留秘訣，仙宮嗽玉叩玄關。","壺中世界青天近，洞裏煙霞白日閑。","若許隨師去塵網，願陪鸞鶴向三山。"]', '["冰霜肌骨稱童年，羽駕何由到俗间。","丹竈化金留秘訣，仙宮嗽玉叩玄关。","壺中世界青天近，洞裏煙霞白日闲。","若許隨師去塵網，願陪鸾鹤向三山。"]', '诗', 'shi', '', NULL, '贈毛仙翁 王起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8030c854-1ecd-4f04-be2d-9a159df53747', '賦花', '賦花', 'de55721c-a41e-4164-a6f5-743b43d76a35', '唐', '["花，點綴，分葩。","露初裛，月未斜。","一枝曲水，千樹山家。","戲蝶未成夢，嬌鶯語更誇。","既見東園成徑，何殊西子同車。","漸覺風飄輕似雪，能令醉者亂如麻。"]', '["花，点綴，分葩。","露初裛，月未斜。","一枝曲水，千樹山家。","戲蝶未成梦，嬌鶯語更誇。","既见东园成徑，何殊西子同车。","漸覺风飄轻似雪，能令醉者亂如麻。"]', '诗', 'shi', '', NULL, '賦花 王起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e00e8e3-9b98-49b0-a739-950d50ab9a5e', '賦得濁水求珠', '賦得濁水求珠', '37783146-e02f-474f-9b7d-7283e7204773', '唐', '["積水非澄徹，明珠不易求。","依稀沈極浦，想像在中流。","瞪目思清淺，褰裳恨暗投。","徒看川色媚，空愛夜光浮。","月入疑龍吐，星歸似蚌游。","終希識珍者，採掇冀冥搜。"]', '["積水非澄徹，明珠不易求。","依稀沈極浦，想像在中流。","瞪目思清淺，褰裳恨暗投。","徒看川色媚，空愛夜光浮。","月入疑龙吐，星归似蚌游。","終希識珍者，採掇冀冥搜。"]', '诗', 'shi', '', NULL, '賦得濁水求珠 王損之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a499057-19e7-4a35-b55a-cb329af36d90', '賦得行不由徑', '賦得行不由徑', '2ec3ee00-9977-485c-b7f3-457458e18ce6', '唐', '["邪徑趨時捷，端心惡此名。","長衢貴高步，大路自規行。","且慮縈紆僻，將求坦蕩情。","詎同流俗好，方保立身貞。","遠跡如違險，修仁在履平。","始知夫子道，從此得堅誠。"]', '["邪徑趨时捷，端心惡此名。","长衢貴高步，大路自規行。","且慮縈紆僻，將求坦蕩情。","詎同流俗好，方保立身貞。","远跡如違險，修仁在履平。","始知夫子道，從此得堅誠。"]', '诗', 'shi', '', NULL, '賦得行不由徑 王炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('182f8141-9e02-4ac1-b11c-e21b5513e4c7', '賦得行不由徑', '賦得行不由徑', '0bc8b900-a7fc-4ba7-9c30-3255f4756b21', '唐', '["欲速意何成，康莊欲砥平。","天衢皆利往，吾道泰方行。","不復由萊徑，無由見蔣生。","三條遵廣達，九軌尚安貞。","紫陌悠悠去，芳塵步步清。","澹臺千載後，公正有遺名。"]', '["欲速意何成，康莊欲砥平。","天衢皆利往，吾道泰方行。","不复由萊徑，無由见蔣生。","三條遵廣達，九軌尚安貞。","紫陌悠悠去，芳塵步步清。","澹台千載後，公正有遺名。"]', '诗', 'shi', '', NULL, '賦得行不由徑 封孟紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f17636b-e203-4d17-853f-aed1b634c61c', '題馬侍中燧木香亭', '題马侍中燧木香亭', '03115311-4399-41fe-96ff-6366bba59cad', '唐', '["春日遲遲木香閣，窈窕佳人褰繡幕。","淋漓玉露滴紫蕤，綿蠻黃鳥窺朱萼。","橫漢碧雲歌處斷，滿地花鈿舞時落。","樹影參差斜入簷，風動玲瓏水晶箔。"]', '["春日遲遲木香閣，窈窕佳人褰繡幕。","淋漓玉露滴紫蕤，綿蠻黄鸟窺朱萼。","橫漢碧云歌处斷，满地花鈿舞时落。","樹影參差斜入簷，风动玲瓏水晶箔。"]', '诗', 'shi', '', NULL, '題馬侍中燧木香亭 邵楚萇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978a6fcf-5269-45bc-b5e4-93c9d36600d0', '賦得玉水記方流', '賦得玉水記方流', '2e6df49c-57f0-47e2-af6f-67ab811a0f29', '唐', '["積水綦文動，因知玉產幽。","如天涵素色，侔地引方流。","潛潤滋雲起，熒華射浪浮。","魚龍泉不夜，草木岸無秋。","璧沼寧堪比，瑤池詎可儔。","若非懸坐測，誰復寄冥搜。"]', '["積水綦文动，因知玉產幽。","如天涵素色，侔地引方流。","潛潤滋云起，熒华射浪浮。","鱼龙泉不夜，草木岸無秋。","璧沼寧堪比，瑤池詎可儔。","若非懸坐測，誰复寄冥搜。"]', '诗', 'shi', '', NULL, '賦得玉水記方流 鄭俞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ca0382-8ca8-480e-9aa9-ec5476adea7c', '賦得玉水記方流', '賦得玉水記方流', 'f3162842-deef-4d18-a163-bbb58b3909e7', '唐', '["玉泉何處記，四折水紋浮。","潤下寧踰矩，居方在上流。","映空虛漾漾，涵白淨悠悠。","影碎疑衝斗，光清耐觸舟。","珪璋分辨狀，沙礫共懷柔。","願赴朝宗日，縈迴入御溝。"]', '["玉泉何处記，四折水紋浮。","潤下寧踰矩，居方在上流。","映空虛漾漾，涵白淨悠悠。","影碎疑衝斗，光清耐觸舟。","珪璋分辨狀，沙礫共懷柔。","願赴朝宗日，縈迴入御溝。"]', '诗', 'shi', '', NULL, '賦得玉水記方流 吳丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddb2db2a-f00e-456b-af3d-fa1c065d22da', '賦得玉水記方流', '賦得玉水記方流', 'c4e17f2a-dd74-4ed3-bb91-9a9303b5dd6a', '唐', '["玉潤在中洲，光臨碕岸幽。","氤氳冥瑞影，演瀁度方流。","乍似輕漣合，還疑駭浪收。","夤緣知有異，洞徹信無儔。","比德稱殊賞，含輝處至柔。","沈淪如見念，況乃屬時休。"]', '["玉潤在中洲，光臨碕岸幽。","氤氳冥瑞影，演瀁度方流。","乍似轻漣合，還疑駭浪收。","夤緣知有異，洞徹信無儔。","比德稱殊賞，含輝处至柔。","沈淪如见念，況乃屬时休。"]', '诗', 'shi', '', NULL, '賦得玉水記方流 王鑑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be2db9a-ea51-4e5f-a052-6dbb3ea6b661', '賦得玉水記方流', '賦得玉水記方流', '6492ce82-8059-43ef-8db4-4d38d324ac6f', '唐', '["明媚如懷玉，奇姿自詫幽。","白虹深不見，綠水折空流。","方珏清沙遍，縱橫氣色浮。","類圭才有角，寫月讓成鉤。","久處沈潛貴，希當特達收。","滔滔在何許，揭厲願從游。"]', '["明媚如懷玉，奇姿自詫幽。","白虹深不见，綠水折空流。","方珏清沙遍，縱橫氣色浮。","類圭才有角，寫月讓成鉤。","久处沈潛貴，希當特達收。","滔滔在何許，揭厲願從游。"]', '诗', 'shi', '', NULL, '賦得玉水記方流 陳昌言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a77cc4bb-0039-49dd-b62f-dcbf364155de', '白日麗江臯', '白日丽江臯', '6492ce82-8059-43ef-8db4-4d38d324ac6f', '唐', '["遲景臨遙水，晴空似不高。","清明開曉鏡，昭晰辨秋毫。","鬱鬱長隄土，離離淺渚毛。","煙銷占一候，風靜擁千艘。","獨媚青春柳，宜看白鷺濤。","何年謝公賞，遺韻在江臯。"]', '["遲景臨遙水，晴空似不高。","清明开晓镜，昭晰辨秋毫。","鬱鬱长隄土，離離淺渚毛。","煙銷占一候，风静擁千艘。","独媚青春柳，宜看白鷺濤。","何年謝公賞，遺韻在江臯。"]', '诗', 'shi', '', NULL, '白日麗江臯 陳昌言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd28b64d-37dd-4fcb-b7cd-fbac0efe6a66', '賦得玉水記方流', '賦得玉水記方流', '5a2de640-7d87-40dd-9ba5-3f08bde6099a', '唐', '["重泉生美玉，積水異常流。","始玩清堪賞，因知寶可求。","斗回虹氣見，磬折紫光浮。","中矩皆明德，同方叶至柔。","月華偏共映，風暖佇將遊。","遇鑒終無暗，逢時願見收。"]', '["重泉生美玉，積水異常流。","始玩清堪賞，因知寶可求。","斗回虹氣见，磬折紫光浮。","中矩皆明德，同方叶至柔。","月华偏共映，风暖佇將游。","遇鑒終無暗，逢时願见收。"]', '诗', 'shi', '', NULL, '賦得玉水記方流 杜元穎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d6f683-e123-46ec-b4a5-1229f5ce24af', '太常觀閱驃國新樂', '太常观閱驃国新乐', 'cb38e46b-ccdd-43fa-b8ee-fb8b30eb2bbc', '唐', '["異音來驃國，初被奉常人。","纔可宮商辨，殊驚節奏新。","轉規迴繡面，曲折度文身。","舒散隨鸞吹，喧呼雜鳥春。","襟袵懷舊識，絲竹變恆陳。","何事留中夏，長令表化淳。"]', '["異音来驃国，初被奉常人。","纔可宮商辨，殊驚節奏新。","轉規迴繡面，曲折度文身。","舒散隨鸾吹，喧呼杂鸟春。","襟袵懷旧識，絲竹变恆陳。","何事留中夏，长令表化淳。"]', '诗', 'shi', '', NULL, '太常觀閱驃國新樂 胡直鈞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8877c330-ce31-4a0b-a939-33b21e56b422', '行不由徑', '行不由徑', '976cb88b-6de1-4128-b2b4-5d8731cddd87', '唐', '["古人心有尚，乃是孔門生。","爲計安貧樂，當從大道行。","詎應流遠迹，方欲料前程。","捷徑雖云易，長衢豈不平。","後來無枉路，先達擅前名。","一示遵途意，微衷益自精。"]', '["古人心有尚，乃是孔门生。","爲計安貧乐，當從大道行。","詎應流远迹，方欲料前程。","捷徑雖云易，长衢豈不平。","後来無枉路，先達擅前名。","一示遵途意，微衷益自精。"]', '诗', 'shi', '', NULL, '行不由徑 俞簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde4b27e-fc46-4a17-b086-2ec8be0d8776', '丁巳歲八月祭武侯祠堂因題臨淮公舊碑', '丁巳歲八月祭武侯祠堂因題臨淮公旧碑', 'a666447a-5adf-4081-9062-5d56d382f568', '唐', '["齋莊修祀事，旌斾出郊闉。","薙草軒墀狹，塗牆赭堊新。","謀猷期作聖，風俗奉爲神。","酹酒成坳澤，持兵列偶人。","非才膺寵任，異代揖芳塵。","況是平津客，碑前淚滿巾。"]', '["斋莊修祀事，旌斾出郊闉。","薙草軒墀狹，塗牆赭堊新。","謀猷期作聖，风俗奉爲神。","酹酒成坳澤，持兵列偶人。","非才膺寵任，異代揖芳塵。","況是平津客，碑前泪满巾。"]', '诗', 'shi', '', NULL, '丁巳歲八月祭武侯祠堂因題臨淮公舊碑 楊嗣復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b4a887b-0584-427c-9bbe-c7637a7a1467', '儀鳳', '儀鳳', 'a666447a-5adf-4081-9062-5d56d382f568', '唐', '["八方該帝澤，威鳳忽來賓。","向日朱光動，迎風翠羽新。","低昂多異趣，飲啄迥無鄰。","郊藪今翔集，河圖意等倫。","聞韶知鼓舞，偶聖願逡巡。","比屋初同俗，垂恩擊壤人。"]', '["八方該帝澤，威鳳忽来賓。","向日朱光动，迎风翠羽新。","低昂多異趣，饮啄迥無鄰。","郊藪今翔集，河圖意等倫。","闻韶知鼓舞，偶聖願逡巡。","比屋初同俗，垂恩擊壤人。"]', '诗', 'shi', '', NULL, '儀鳳 楊嗣復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906813c1-fa70-4099-9bf1-42ba32cc84da', '贈毛仙翁', '贈毛仙翁', 'a666447a-5adf-4081-9062-5d56d382f568', '唐', '["天上玉郎騎白鶴，肘後金壺盛妙藥。","暫遊下界傲五侯，重看當時舊城郭。","羽衣茸茸輕似雪，雲上雙童持絳節。","王母親縫紫錦囊，令向懷中藏秘訣。","令威子晉皆儔侶，東嶽同尋太真女。","搜奇綴韻和陽春，文章不是人間語。","藥成自固黃金骨，天地齊兮身不沒。","日月宮中便是家，下視崑崙何突兀。","童姿玉貌誰方比，玄髮綠髯光彌彌。","滿朝將相門弟子，隨師盡願拋塵滓。","九轉琅玕必有餘，願乞刀圭救生死。"]', '["天上玉郎騎白鹤，肘後金壺盛妙藥。","暫游下界傲五侯，重看當时旧城郭。","羽衣茸茸轻似雪，云上雙童持絳節。","王母親縫紫錦囊，令向懷中藏秘訣。","令威子晉皆儔侶，东嶽同尋太真女。","搜奇綴韻和陽春，文章不是人间語。","藥成自固黄金骨，天地齊兮身不沒。","日月宮中便是家，下視崑崙何突兀。","童姿玉貌誰方比，玄髮綠髯光彌彌。","满朝將相门弟子，隨師尽願拋塵滓。","九轉琅玕必有餘，願乞刀圭救生死。"]', '诗', 'shi', '', NULL, '贈毛仙翁 楊嗣復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ff06ff-f269-4113-ac15-def0dc37876b', '題李處士山居', '題李处士山居', 'a666447a-5adf-4081-9062-5d56d382f568', '唐', '["臥龍決起爲時君，寂寞匡廬惟白雲。","今日仲容修故業，草堂焉敢更移文。"]', '["臥龙決起爲时君，寂寞匡廬惟白云。","今日仲容修故業，草堂焉敢更移文。"]', '诗', 'shi', '', NULL, '題李處士山居 楊嗣復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479f4614-220f-481a-b5ac-0fe0fbe3c708', '謝寄新茶', '謝寄新茶', 'a666447a-5adf-4081-9062-5d56d382f568', '唐', '["石上生芽二月中，蒙山顧渚莫爭雄。","封題寄與楊司馬，應爲前銜是相公。"]', '["石上生芽二月中，蒙山顧渚莫爭雄。","封題寄與楊司马，應爲前銜是相公。"]', '诗', 'shi', '', NULL, '謝寄新茶 楊嗣復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('703a0215-431b-446d-b6fb-539da2d98f78', '盧十五竹亭送姪偁歸山', '盧十五竹亭送姪偁归山', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["落葉寒擁壁，清霜夜霑石。","正是憶山時，復送歸山客。","殷勤一尊酒，曉月當窗白。"]', '["落葉寒擁壁，清霜夜霑石。","正是憶山时，复送归山客。","殷勤一尊酒，晓月當窗白。"]', '诗', 'shi', '', NULL, '盧十五竹亭送姪偁歸山 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7037682-3bb0-4bee-ac82-11823a69b2d3', '旅次江亭', '旅次江亭', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["扣舷不能寐，皓露清衣襟。","彌傷孤舟夜，遠結萬里心。","幽興惜瑤草，素懷寄鳴琴。","三奏月初上，寂寥寒江深。"]', '["扣舷不能寐，皓露清衣襟。","彌傷孤舟夜，远結万里心。","幽兴惜瑤草，素懷寄鳴琴。","三奏月初上，寂寥寒江深。"]', '诗', 'shi', '', NULL, '旅次江亭 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2f66a9a-96ca-45d3-bc0d-2eb994be6674', '賦得夜雨滴空堦送魏秀才', '賦得夜雨滴空堦送魏秀才', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["委簷方滴滴，霑紅復洒綠。","醉聽乍朦朧，愁聞多斷續。","始兼泉嚮細，稍雜更聲促。","百慮自縈心，況有人如玉。"]', '["委簷方滴滴，霑紅复洒綠。","醉听乍朦朧，愁闻多斷續。","始兼泉嚮細，稍杂更声促。","百慮自縈心，況有人如玉。"]', '诗', 'shi', '', NULL, '賦得夜雨滴空堦送魏秀才 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4cd131c-5bfd-427b-a762-8ff4882208a1', '征人', '征人', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["西風屢鳴雁，東郊未升日。","繁煙幕幕昏，暗騎蕭蕭出。","望雲愁玉塞，眠月想蕙質。","借問露霑衣，何如香滿室。"]', '["西风屢鳴雁，东郊未升日。","繁煙幕幕昏，暗騎蕭蕭出。","望云愁玉塞，眠月想蕙質。","借问露霑衣，何如香满室。"]', '诗', 'shi', '', NULL, '征人 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba918bb-55d5-49c2-9052-e590801839ce', '遊陸先生故巖居', '游陸先生故巖居', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["獨壑臨萬嶂，蒼苔絕行跡。","仰窺猨挂樹，俯對鶴巢石。","上有一巖屋，相傳靈人宅。","深林無陽暉，幽水轉鮮碧。","拾薪遇遺鼎，探穴得古籍。","結念候雲興，燒香坐終夕。"]', '["独壑臨万嶂，蒼苔絕行跡。","仰窺猨挂樹，俯对鹤巢石。","上有一巖屋，相傳靈人宅。","深林無陽暉，幽水轉鲜碧。","拾薪遇遺鼎，探穴得古籍。","結念候云兴，燒香坐終夕。"]', '诗', 'shi', '', NULL, '遊陸先生故巖居 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d87879-1a79-4e86-b7b2-686365c02b53', '題玄和師仙藥室', '題玄和師仙藥室', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["山邊蕭寂室，石掩浮雲扃。","遶室微有路，松煙深冥冥。","入松汲寒水，對鶴問仙經。","石几香未盡，水花風欲零。","何年去華表，幾度窮蒼冥。","却顧宦遊子，眇如霜中螢。"]', '["山邊蕭寂室，石掩浮云扃。","遶室微有路，松煙深冥冥。","入松汲寒水，对鹤问仙經。","石几香未尽，水花风欲零。","何年去华表，幾度窮蒼冥。","却顧宦游子，眇如霜中螢。"]', '诗', 'shi', '', NULL, '題玄和師仙藥室 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cb3f893-1f2c-40fa-bd31-480c52f11940', '宿陸氏齋賦得殘燈詩', '宿陸氏斋賦得殘灯诗', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["殷勤照永夜，屬思未成眠。","餘暉含薄霧，落燼迸空筵。","誰比秦樓曉，緘愁別幌前。"]', '["殷勤照永夜，屬思未成眠。","餘暉含薄霧，落燼迸空筵。","誰比秦楼晓，緘愁別幌前。"]', '诗', 'shi', '', NULL, '宿陸氏齋賦得殘燈詩 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17adbcb-41cd-43ad-b89a-0c543e132e66', '夷陵郡內敘別', '夷陵郡內敘別', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["禮娶嗣明德，同牢夙所欽。","況蒙生死契，豈顧蓬蒿心。","雁幣任野薄，恩愛緣義深。","同聲若鼓瑟，合韻似鳴琴。","將迓空未立，就贅意難任。","皎月託言誓，滄波信浮沈。","荆臺理晨轍，巫渚疑宵襟。","憫憫百慮起，回回萬恨深。","候更促徒侶，先曉徹夜禽。","燈彩凝寒風，蟬思噪密林。","留念同心帶，贈遠芙蓉簪。","撫懷極投漆，感物重黃金。","分鸞豈遐阻，別劒念相尋。","儻甘蓬戶賤，願俟故山岑。"]', '["禮娶嗣明德，同牢夙所欽。","況蒙生死契，豈顧蓬蒿心。","雁幣任野薄，恩愛緣義深。","同声若鼓瑟，合韻似鳴琴。","將迓空未立，就贅意难任。","皎月託言誓，滄波信浮沈。","荆台理晨轍，巫渚疑宵襟。","憫憫百慮起，回回万恨深。","候更促徒侶，先晓徹夜禽。","灯彩凝寒风，蟬思噪密林。","留念同心带，贈远芙蓉簪。","撫懷極投漆，感物重黄金。","分鸾豈遐阻，別劒念相尋。","儻甘蓬戶賤，願俟故山岑。"]', '诗', 'shi', '', NULL, '夷陵郡內敘別 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bab693-c9f2-4d94-92c7-c57280e10cc5', '將之荆州南與張伯剛馬惣鍾陵夜別', '將之荆州南與張伯剛马惣鍾陵夜別', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["荆臺別路長，密緒分離狀。","莫訴杯來促，更籌屢已倡。","燭花侵霧暗，瑟調寒風亮。","誰念曉帆開，默睇參差浪。"]', '["荆台別路长，密緒分離狀。","莫訴杯来促，更籌屢已倡。","燭花侵霧暗，瑟調寒风亮。","誰念晓帆开，默睇參差浪。"]', '诗', 'shi', '', NULL, '將之荆州南與張伯剛馬惣鍾陵夜別 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d6bf35-4373-4e6b-bcdd-b17ec8472e87', '經端溪峽中', '經端溪峽中', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["陰岸東流水，上有微風生。","素羽漾翠澗，碧苔敷丹英。","重林宿雨晦，遠岫孤霞明。","飛猱相攀牽，白雲亂縱橫。","有客泝輕檝，閱勝匪羈程。","逍遙一息間，糞土五侯榮。","搴茗庶蠲熱，漱泉聊析酲。","寄言絲竹者，詎識松風聲。"]', '["陰岸东流水，上有微风生。","素羽漾翠澗，碧苔敷丹英。","重林宿雨晦，远岫孤霞明。","飞猱相攀牽，白云亂縱橫。","有客泝轻檝，閱勝匪羈程。","逍遙一息间，糞土五侯榮。","搴茗庶蠲熱，漱泉聊析酲。","寄言絲竹者，詎識松风声。"]', '诗', 'shi', '', NULL, '經端溪峽中 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58d2e9c-9bb1-487a-834d-7de9bf46b25c', '南海苦雨寄贈王四侍御', '南海苦雨寄贈王四侍御', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["炎風雜海氣，暑雨每成霖。","塗泥親杖屨，苔蘚漬衣襟。","念近劇懷遠，涉淺定知深。","暗溝夜滴滴，荒庭晝霪霪。","折簡展離曠，理逕俟招尋。","處陰誠多慘，況乃觸隅禽。"]', '["炎风杂海氣，暑雨每成霖。","塗泥親杖屨，苔蘚漬衣襟。","念近劇懷远，涉淺定知深。","暗溝夜滴滴，荒庭晝霪霪。","折簡展離曠，理逕俟招尋。","处陰誠多慘，況乃觸隅禽。"]', '诗', 'shi', '', NULL, '南海苦雨寄贈王四侍御 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065f8096-2539-4792-b48e-5fc033f855b2', '秋夜閑居即事寄廬山鄭員外蜀郡符處士', '秋夜闲居即事寄廬山鄭員外蜀郡符处士', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["憂思繁未整，良辰會無由。","引領遲佳音，星紀屢以周。","蓬閬絕華耀，況乃處窮愁。","墜葉寒擁砌，燈火夜悠悠。","開琴弄清弦，窺月俯澄流。","冉冉鴻雁度，蕭蕭帷箔秋。","悵懷石門詠，緬慕碧雞遊。","髣髴蒙顏色，崇蘭隱芳洲。"]', '["憂思繁未整，良辰會無由。","引領遲佳音，星紀屢以周。","蓬閬絕华耀，況乃处窮愁。","墜葉寒擁砌，灯火夜悠悠。","开琴弄清弦，窺月俯澄流。","冉冉鴻雁度，蕭蕭帷箔秋。","悵懷石门詠，緬慕碧雞游。","髣髴蒙顏色，崇蘭隐芳洲。"]', '诗', 'shi', '', NULL, '秋夜閑居即事寄廬山鄭員外蜀郡符處士 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5878f29-2eed-4700-b49d-7b79bc698a70', '寄贈田倉曹灣', '寄贈田倉曹灣', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["芳蘭媚庭除，灼灼紅英舒。","身爲陋巷客，門有絳轅車。","朝覽夷胡傳，暮習潁陽書。","盻雲高羽翼，待賈蘊璠璵。","纓弁雖云阻，音塵豈復疎。","若因風雨晦，應念寂寥居。"]', '["芳蘭媚庭除，灼灼紅英舒。","身爲陋巷客，门有絳轅车。","朝覽夷胡傳，暮習潁陽书。","盻云高羽翼，待賈蘊璠璵。","纓弁雖云阻，音塵豈复疎。","若因风雨晦，應念寂寥居。"]', '诗', 'shi', '', NULL, '寄贈田倉曹灣 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41adf73a-13a5-4d9a-97a9-0bc447e34640', '詠春色', '詠春色', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["靄靄復濛濛，非霧滿晴空。","密添宮柳翠，暗泄路桃紅。","縈絲光乍失，緣隟影纔通。","夕迷鴛枕上，朝漫綺弦中。","促駟馳香陌，勞鶯轉豔叢。","可憐腸斷望，併在洛城東。"]', '["靄靄复濛濛，非霧满晴空。","密添宮柳翠，暗泄路桃紅。","縈絲光乍失，緣隟影纔通。","夕迷鴛枕上，朝漫綺弦中。","促駟驰香陌，勞鶯轉豔叢。","可怜腸斷望，併在洛城东。"]', '诗', 'shi', '', NULL, '詠春色 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b821bfa8-5eba-4039-91b2-18abba79c50d', '送春', '送春', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["三月三十日，春歸日復暮。","惆悵問春風，明朝應不住。","送春曲江上，眷眷東西顧。","但見撲水花，紛紛不知數。","人生似行客，兩足無停步。","日日進前程，前程幾多路。","兵刃與水火，盡可違之去。","惟有老到來，人間無避處。","感時良未已，獨倚池南樹。","今日送春心，心如別親故。"]', '["三月三十日，春归日复暮。","惆悵问春风，明朝應不住。","送春曲江上，眷眷东西顧。","但见撲水花，紛紛不知數。","人生似行客，兩足無停步。","日日進前程，前程幾多路。","兵刃與水火，尽可違之去。","惟有老到来，人间無避处。","感时良未已，独倚池南樹。","今日送春心，心如別親故。"]', '诗', 'shi', '', NULL, '送春 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1d240a-0fe9-45f6-a709-ef307cb25303', '遊峽山寺', '游峽山寺', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["結構天南畔，勝絕固難儔。","幸蒙時所漏，遂得恣閑遊。","路石蔭松蓋，檻藤維鶴舟。","雨霽花木潤，風和景氣柔。","寶殿敞丹扉，靈幡垂絳旒。","照曜芙蓉壺，金人居上頭。","翔禽拂危剎，落日避層樓。","端溪瀰漫駛，曲澗潺湲流。","高居何重沓，登覽自夷猶。","煙霞無隱態，巖洞詎遺幽。","奔駟非久耀，馳波肯暫留。","會從香火緣，滅跡此山丘。"]', '["結構天南畔，勝絕固难儔。","幸蒙时所漏，遂得恣闲游。","路石蔭松蓋，檻藤維鹤舟。","雨霽花木潤，风和景氣柔。","寶殿敞丹扉，靈幡垂絳旒。","照曜芙蓉壺，金人居上头。","翔禽拂危剎，落日避層楼。","端溪瀰漫駛，曲澗潺湲流。","高居何重沓，登覽自夷猶。","煙霞無隐態，巖洞詎遺幽。","奔駟非久耀，驰波肯暫留。","會從香火緣，滅跡此山丘。"]', '诗', 'shi', '', NULL, '遊峽山寺 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87477559-3470-400d-b812-e90f5373231f', '宿陟岵寺雲律師院', '宿陟岵寺云律師院', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["像宇鬱參差，寶林疎復密。","中有彌天子，燃燈坐虛室。","心證紅蓮喻，跡羈青眼律。","玉爐揚翠煙，金經開縹帙。","肆陳堅固學，破我夢幻質。","碧水灑塵纓，涼扇當夏日。","宿禽詎相保，迸火煙欲失。","願迴戚促勞，趨隅事休逸。"]', '["像宇鬱參差，寶林疎复密。","中有彌天子，燃灯坐虛室。","心證紅蓮喻，跡羈青眼律。","玉爐揚翠煙，金經开縹帙。","肆陳堅固学，破我梦幻質。","碧水灑塵纓，涼扇當夏日。","宿禽詎相保，迸火煙欲失。","願迴戚促勞，趨隅事休逸。"]', '诗', 'shi', '', NULL, '宿陟岵寺雲律師院 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77b81301-7f83-45e5-9fe2-6728a14f5c9f', '秋夜桂州宴送鄭十九侍御', '秋夜桂州宴送鄭十九侍御', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["秋至觸物愁，況當離別筵。","短歌銷夜燭，繁緒遍高弦。","桂水舟始泛，蘭堂榻詎懸。","一盃勾離阻，三載奉周旋。","鴉噪更漏颯，露濡風景鮮。","斯須不共此，且爲更留連。"]', '["秋至觸物愁，況當離別筵。","短歌銷夜燭，繁緒遍高弦。","桂水舟始泛，蘭堂榻詎懸。","一盃勾離阻，三載奉周旋。","鴉噪更漏颯，露濡风景鲜。","斯須不共此，且爲更留連。"]', '诗', 'shi', '', NULL, '秋夜桂州宴送鄭十九侍御 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82cba92a-5c27-4f27-bebc-bb56b08f6d6d', '九日陪樊尚書龍山宴集', '九日陪樊尚书龙山宴集', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["孟嘉從宴地，千乘復登臨。","緣危陟高步，憑曠寫幽襟。","黃花翫初馥，翠物喜盈斟。","雲雜組繡色，樂和山水音。","斾搖秋吹急，筵卷夕光沈。","都人瞻騎火，猶知隔寺深。"]', '["孟嘉從宴地，千乘复登臨。","緣危陟高步，憑曠寫幽襟。","黄花翫初馥，翠物喜盈斟。","云杂組繡色，乐和山水音。","斾搖秋吹急，筵卷夕光沈。","都人瞻騎火，猶知隔寺深。"]', '诗', 'shi', '', NULL, '九日陪樊尚書龍山宴集 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b6b48b-e8ef-45f7-b2a6-aa78878ed230', '江陵送客歸河北', '江陵送客归河北', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["遠客歸故里，臨路結裴回。","山長水復闊，無因重此來。","聊將歌一曲，送子手中盃。"]', '["远客归故里，臨路結裴回。","山长水复闊，無因重此来。","聊將歌一曲，送子手中盃。"]', '诗', 'shi', '', NULL, '江陵送客歸河北 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('000e96e4-474a-47b9-a0b1-c16d2816ed0c', '送鄭丞之羅浮中習業', '送鄭丞之羅浮中習業', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["百年泛飄忽，萬事繫衰榮。","高鴻脫矰繳，達士去簪纓。","始從天目遊，復作羅浮行。","雲臥石林密，月窺花洞明。","全形在氣和，習默憑境清。","夙祕絳囊訣，屢投金簡名。","鐘管促離觴，煙霞隨去程。","何當真府內，重得欵平生。"]', '["百年泛飄忽，万事繫衰榮。","高鴻脫矰繳，達士去簪纓。","始從天目游，复作羅浮行。","云臥石林密，月窺花洞明。","全形在氣和，習默憑境清。","夙祕絳囊訣，屢投金簡名。","鐘管促離觴，煙霞隨去程。","何當真府內，重得欵平生。"]', '诗', 'shi', '', NULL, '送鄭丞之羅浮中習業 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c2350e-d560-4956-b2dd-9ea8cc72324d', '送王秀才往安南', '送王秀才往安南', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["君爲蹈海客，客路誰諳悉。","鯨度乍疑山，雞鳴先見日。","所嗟迴櫂晚，倍結離情密。","無貪合浦珠，念守江陵橘。"]', '["君爲蹈海客，客路誰諳悉。","鯨度乍疑山，雞鳴先见日。","所嗟迴櫂晚，倍結離情密。","無貪合浦珠，念守江陵橘。"]', '诗', 'shi', '', NULL, '送王秀才往安南 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d4631b-13c4-44b8-b90f-4be34eea0a24', '送公孫器自桂林歸蜀', '送公孫器自桂林归蜀', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["桂林淺復碧，潺湲半露石。","將乘觸物舟，暫駐飛空錫。","蜀鄉異青眼，蓬戶高朱戟。","風度杳難尋，雲飄詎留跡。","舊戶閑花草，馴鴿傍簷隟。","揮手共忘懷，日墮千山夕。"]', '["桂林淺复碧，潺湲半露石。","將乘觸物舟，暫駐飞空錫。","蜀乡異青眼，蓬戶高朱戟。","风度杳难尋，云飄詎留跡。","旧戶闲花草，馴鴿傍簷隟。","揮手共忘懷，日墮千山夕。"]', '诗', 'shi', '', NULL, '送公孫器自桂林歸蜀 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e89e730-74b8-4924-ae06-0d2f259c03be', '贈羅浮易鍊師', '贈羅浮易鍊師', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["海上多仙嶠，靈人信長生。","榮衛冰雪姿，嚥嚼日月精。","默書絳符遍，晦步斗文成。","翠髮披肩長，金蓋凌風輕。","曉籟息塵響，天雞叱幽聲。","碧樹來戶陰，丹霞照窗明。","焚香叩虛寂，稽首迴太清。","鸞鷺振羽儀，飛翻拂斾旌。","左挹玉泉液，右搴雲芝英。","念得參龍駕，攀天度赤城。"]', '["海上多仙嶠，靈人信长生。","榮衛冰雪姿，嚥嚼日月精。","默书絳符遍，晦步斗文成。","翠髮披肩长，金蓋凌风轻。","晓籟息塵响，天雞叱幽声。","碧樹来戶陰，丹霞照窗明。","焚香叩虛寂，稽首迴太清。","鸾鷺振羽儀，飞翻拂斾旌。","左挹玉泉液，右搴云芝英。","念得參龙駕，攀天度赤城。"]', '诗', 'shi', '', NULL, '贈羅浮易鍊師 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489ae830-c46f-4617-932b-7754556b7660', '登紫霄峰贈黃仙師', '登紫霄峰贈黄仙師', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["紫霄不可涉，靈峯信穹崇。","下有瓊樹枝，上有翠髮翁。","雞鳴秋漢側，日出紅霞中。","璨璨真仙子，執旄爲侍童。","焚香杳忘言，默念合太空。","世華徒熠耀，虛室自朦朧。","雲飛瓊瑤圃，龜息芝蘭藂。","玉籙掩不開，天窗微微風。","茲焉悟佳旨，塵境亦幽通。","浩渺臨廣津，永用挹無窮。"]', '["紫霄不可涉，靈峯信穹崇。","下有瓊樹枝，上有翠髮翁。","雞鳴秋漢側，日出紅霞中。","璨璨真仙子，執旄爲侍童。","焚香杳忘言，默念合太空。","世华徒熠耀，虛室自朦朧。","云飞瓊瑤圃，龟息芝蘭藂。","玉籙掩不开，天窗微微风。","茲焉悟佳旨，塵境亦幽通。","浩渺臨廣津，永用挹無窮。"]', '诗', 'shi', '', NULL, '登紫霄峰贈黃仙師 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fce6309c-7066-454e-ab83-b8be51cc1893', '烏啼曲', '烏啼曲', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["可憐楊葉復楊花，雪淨煙深碧玉家。","烏栖不定枝條弱，城頭夜半聲啞啞。","浮萍流蕩門前水，任罥芙蓉莫浣紗。"]', '["可怜楊葉复楊花，雪淨煙深碧玉家。","烏栖不定枝條弱，城头夜半声啞啞。","浮萍流蕩门前水，任罥芙蓉莫浣紗。"]', '诗', 'shi', '', NULL, '烏啼曲 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faa6ba1b-f44c-4ed0-b5cf-e215b972e1ec', '白紵歌二首 一', '白紵歌二首 一', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["玉纓翠佩雜輕羅，香汗微漬朱顏酡，爲君起唱白紵歌。","清聲褭雲繁思多，凝笳哀瑟時相和。","金壺半傾芳夜促，梁塵霏霏暗紅燭。","令君安坐聽終曲，墜葉飄花難再復。"]', '["玉纓翠佩杂轻羅，香汗微漬朱顏酡，爲君起唱白紵歌。","清声褭云繁思多，凝笳哀瑟时相和。","金壺半傾芳夜促，梁塵霏霏暗紅燭。","令君安坐听終曲，墜葉飄花难再复。"]', '诗', 'shi', '', NULL, '白紵歌二首 一 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6cdeae-fe7a-49fc-afc2-831528d8064a', '白紵歌二首 二', '白紵歌二首 二', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["躡珠履，步瓊筵輕身起舞紅燭前，芳姿豔態妖且妍。","迴眸轉袖暗催弦，涼風蕭蕭漏水急。","月華泛豔紅蓮濕，牽裙攬帶翻成泣。"]', '["躡珠履，步瓊筵轻身起舞紅燭前，芳姿豔態妖且妍。","迴眸轉袖暗催弦，涼风蕭蕭漏水急。","月华泛豔紅蓮濕，牽裙攬带翻成泣。"]', '诗', 'shi', '', NULL, '白紵歌二首 二 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b722b9-55f8-47d5-800e-5dbcd3382b68', '長門怨', '长门怨', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["絲聲繁兮管聲急，珠簾不捲風吹入。","萬遍凝愁枕上聽，千迴候命花間立。","望望昭陽信不來，迴眸獨掩紅巾泣。"]', '["絲声繁兮管声急，珠簾不捲风吹入。","万遍凝愁枕上听，千迴候命花间立。","望望昭陽信不来，迴眸独掩紅巾泣。"]', '诗', 'shi', '', NULL, '長門怨 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af87fd3e-ea52-4b9f-9f7a-c3dce8a42649', '寄徹公', '寄徹公', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["北風吹霜霜月明，荷葉枯盡越水清。","別來幾度龍宮宿，雪山童子應相逐。"]', '["北风吹霜霜月明，荷葉枯尽越水清。","別来幾度龙宮宿，雪山童子應相逐。"]', '诗', 'shi', '', NULL, '寄徹公 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10dda84c-850d-41e0-ac25-005964f60918', '哭李象', '哭李象', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["白雞黃犬不將去，寂寞空餘葬時路。","草死花開年復年，後人知是何人墓。","憶君思君獨不眠，夜寒月照青楓樹。"]', '["白雞黄犬不將去，寂寞空餘葬时路。","草死花开年复年，後人知是何人墓。","憶君思君独不眠，夜寒月照青楓樹。"]', '诗', 'shi', '', NULL, '哭李象 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6250fd5-bdd4-4c24-9074-a3023c832ae4', '宿雲溪觀賦得秋燈引送客', '宿云溪观賦得秋灯引送客', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["雲房寄宿秋夜客，一燈熒熒照虛壁。","蟲聲呼客客未眠，幾人語話清景側。","不可離別愁紛多，秋燈秋燈奈別何。"]', '["云房寄宿秋夜客，一灯熒熒照虛壁。","蟲声呼客客未眠，幾人語話清景側。","不可離別愁紛多，秋灯秋灯奈別何。"]', '诗', 'shi', '', NULL, '宿雲溪觀賦得秋燈引送客 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d36cdf77-0cd5-4d82-acad-cf1fac698b6c', '採蓮曲', '採蓮曲', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["凝鮮霧渚夕，陽豔綠波風。","魚遊乍散藻，露重稍欹紅。","楚客傷暮節，吳娃泣敗藂。","促令芳本固，寧望雪霜中。"]', '["凝鲜霧渚夕，陽豔綠波风。","鱼游乍散藻，露重稍欹紅。","楚客傷暮節，吳娃泣敗藂。","促令芳本固，寧望雪霜中。"]', '诗', 'shi', '', NULL, '採蓮曲 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf877ff-68b5-485f-9b24-3aa7094635e9', '他鄉七夕', '他乡七夕', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["漢渚常多別，山橋忽重遊。","向雲迎翠輦，當月拜珠旒。","寢幌凝宵態，妝奩閉曉愁。","不堪鳴杼日，空對白榆秋。"]', '["漢渚常多別，山橋忽重游。","向云迎翠輦，當月拜珠旒。","寢幌凝宵態，妝奩閉晓愁。","不堪鳴杼日，空对白榆秋。"]', '诗', 'shi', '', NULL, '他鄉七夕 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33f7773-60f6-4b51-8d26-dc286c485d32', '春日偶題', '春日偶題', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["何處春先到，橋東水北亭。","[凍]花開未得，冷酒酌難醒。","就日移輕榻，遮風展小屏。","更無人勸飲，鶯語漸叮嚀。"]', '["何处春先到，橋东水北亭。","[凍]花开未得，冷酒酌难醒。","就日移轻榻，遮风展小屏。","更無人勸饮，鶯語漸叮嚀。"]', '诗', 'shi', '', NULL, '春日偶題 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cb26c22-0315-44ce-b3a5-8cf215379d5e', '題山寺', '題山寺', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["千峯白露後，雲壁挂殘燈。","曙色海邊日，經聲松下僧。","意閑門不閉，年去水空澄。","稽首如何問，森羅盡一乘。"]', '["千峯白露後，云壁挂殘灯。","曙色海邊日，經声松下僧。","意闲门不閉，年去水空澄。","稽首如何问，森羅尽一乘。"]', '诗', 'shi', '', NULL, '題山寺 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1291114-032f-41fe-8172-970bb6741132', '廣州石門寺重送李尚赴朝時兼宗正卿', '廣州石门寺重送李尚赴朝时兼宗正卿', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["象闕趨雲陛，龍宮憩石門。","清鐃猶啓路，黃髮重攀轅。","藻變朝天服，珠懷委地言。","那令蓬蒿客，茲席未離尊。"]', '["象闕趨云陛，龙宮憩石门。","清鐃猶啓路，黄髮重攀轅。","藻变朝天服，珠懷委地言。","那令蓬蒿客，茲席未離尊。"]', '诗', 'shi', '', NULL, '廣州石門寺重送李尚赴朝時兼宗正卿 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048738b5-3469-456f-818a-8d9856a06aa5', '送孔周之南海謁王尚書', '送孔周之南海謁王尚书', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["泛櫂若流萍，桂寒山更青。","望雲生碧落，看日下滄溟。","潮盡收珠母，沙閑拾翠翎。","自趨龍戟下，再爲誦芳馨。"]', '["泛櫂若流萍，桂寒山更青。","望云生碧落，看日下滄溟。","潮尽收珠母，沙闲拾翠翎。","自趨龙戟下，再爲誦芳馨。"]', '诗', 'shi', '', NULL, '送孔周之南海謁王尚書 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7393721d-7797-40f4-94e3-11f18a6698ea', '冬夜舉公房送崔秀才歸南陽', '冬夜舉公房送崔秀才归南陽', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["聞君動征櫂，犯夜故來尋。","強置一尊酒，重欵百年心。","燈白霜氣冷，室虛松韻深。","南陽三顧地，幸偶價千金。"]', '["闻君动征櫂，犯夜故来尋。","強置一尊酒，重欵百年心。","灯白霜氣冷，室虛松韻深。","南陽三顧地，幸偶價千金。"]', '诗', 'shi', '', NULL, '冬夜舉公房送崔秀才歸南陽 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4cdd165-b0ae-4946-8a1c-30251b149bf9', '送陳房謁撫州周使君', '送陳房謁撫州周使君', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["匡山一畝宮，尚有桂蘭叢。","鑿壁年雖異，穿楊志幸同。","貌羸緣塞苦，道蹇爲囊空。","去謁臨川守，因憐鶴在籠。"]', '["匡山一畝宮，尚有桂蘭叢。","鑿壁年雖異，穿楊志幸同。","貌羸緣塞苦，道蹇爲囊空。","去謁臨川守，因怜鹤在籠。"]', '诗', 'shi', '', NULL, '送陳房謁撫州周使君 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70fe4be9-af28-4661-9891-ad2650bdb22b', '山齋獨宿贈晏上人', '山斋独宿贈晏上人', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["幢幢雲樹秋，黃葉下山頭。","蟲響夜難度，夢閑神不遊。","窗燈寒几盡，簾雨曉堦愁。","何以禪棲客，灰心在沃州。"]', '["幢幢云樹秋，黄葉下山头。","蟲响夜难度，梦闲神不游。","窗灯寒几尽，簾雨晓堦愁。","何以禪棲客，灰心在沃州。"]', '诗', 'shi', '', NULL, '山齋獨宿贈晏上人 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15fbd364-bf79-451d-b7d5-e54abaa514aa', '桂州與陳羽念別', '桂州與陳羽念別', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["慘戚損志抱，因君時解顏。","重歎今夕會，復在幾夕間。","碧桂水連海，蒼梧雲滿山。","茫茫從此去，何路入秦關。"]', '["慘戚損志抱，因君时解顏。","重歎今夕會，复在幾夕间。","碧桂水連海，蒼梧云满山。","茫茫從此去，何路入秦关。"]', '诗', 'shi', '', NULL, '桂州與陳羽念別 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8608e52-1c76-45c0-be19-e64ade2aa42b', '經趙處士居', '經趙处士居', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["雲居避世客，髮白習儒經。","有地水空綠，無人山自青。","廢梁悲逝水，臥木思荒庭。","向夕霏煙斂，徒看處士星。"]', '["云居避世客，髮白習儒經。","有地水空綠，無人山自青。","廢梁悲逝水，臥木思荒庭。","向夕霏煙斂，徒看处士星。"]', '诗', 'shi', '', NULL, '經趙處士居 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941fc72b-a706-4483-b009-e0ed5404e4ce', '病中赴袁州次香館', '病中赴袁州次香館', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["病輿憩上館，繚繞向山隅。","荒葛漫欹壁，幽禽啄朽株。","力微怯升降，意欲結踟躇。","誰能挹香水，一爲濯煩紆。"]', '["病輿憩上館，繚繞向山隅。","荒葛漫欹壁，幽禽啄朽株。","力微怯升降，意欲結踟躇。","誰能挹香水，一爲濯煩紆。"]', '诗', 'shi', '', NULL, '病中赴袁州次香館 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d2d7812-6c66-4644-993c-2b8d74becc7b', '送人流雷州', '送人流雷州', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["逐客指天涯，人間此路賒。","地圖經大庾，水驛過長沙。","臘月雷州雨，秋風桂嶺花。"]', '["逐客指天涯，人间此路賒。","地圖經大庾，水驛過长沙。","臘月雷州雨，秋风桂嶺花。"]', '诗', 'shi', '', NULL, '送人流雷州 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e7a1a8-5ccf-4d82-a0e3-e5a71808447c', '送徹公', '送徹公', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["白首年空度，幽居俗豈知。","敗蕉依晚日，孤鶴立秋墀。","久客何由造，禪門不可窺。","會同塵外友，齋沐奉威儀。"]', '["白首年空度，幽居俗豈知。","敗蕉依晚日，孤鹤立秋墀。","久客何由造，禪门不可窺。","會同塵外友，斋沐奉威儀。"]', '诗', 'shi', '', NULL, '送徹公 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef7f1de2-0433-4b56-aefe-5b6dbfb9f558', '贈廬山道士', '贈廬山道士', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["寂寥高室古松寒，松下仙人字委鸞。","頭垂白髮朝鳴磬，手把青芝夜遶壇。","物像自隨塵外滅，真源長向性中看。","悠悠萬古皆如此，秋比松枝春比蘭。"]', '["寂寥高室古松寒，松下仙人字委鸾。","头垂白髮朝鳴磬，手把青芝夜遶壇。","物像自隨塵外滅，真源长向性中看。","悠悠万古皆如此，秋比松枝春比蘭。"]', '诗', 'shi', '', NULL, '贈廬山道士 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6127c8-d4df-423d-99b0-a2d061ec0cf0', '賦得直如朱絲弦', '賦得直如朱絲弦', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["寂寞瑤琴上，深知直者情。","幸傳朱鷺曲，那止素絲名。","瑞草人空仰，王言世久行。","大方聞正位，樂府動清聲。","文武音初合，宮商調屢更。","誰能向機杼，終日泣無成。"]', '["寂寞瑤琴上，深知直者情。","幸傳朱鷺曲，那止素絲名。","瑞草人空仰，王言世久行。","大方闻正位，乐府动清声。","文武音初合，宮商調屢更。","誰能向機杼，終日泣無成。"]', '诗', 'shi', '', NULL, '賦得直如朱絲弦 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e89cc0d1-1cc9-4141-8b64-2b8f60a5cac4', '早春即事', '早春即事', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["眼重朝眠足，頭輕宿醉醒。","陽光滿前戶，雪水半中庭。","候變隨天氣，春生逐地形。","北簷梅晚白，東岸柳先青。","葱壠抽羊角，松巢墮鶴翎。","老來詩更拙，吟罷少人聽。"]', '["眼重朝眠足，头轻宿醉醒。","陽光满前戶，雪水半中庭。","候变隨天氣，春生逐地形。","北簷梅晚白，东岸柳先青。","葱壠抽羊角，松巢墮鹤翎。","老来诗更拙，吟罷少人听。"]', '诗', 'shi', '', NULL, '早春即事 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d1b8cd6-b11c-403a-8cb9-ab1d386df704', '題花樹', '題花樹', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["都無看花意，偶到樹邊來。","可憐枝上色，一一爲愁開。"]', '["都無看花意，偶到樹邊来。","可怜枝上色，一一爲愁开。"]', '诗', 'shi', '', NULL, '題花樹 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cdddc3-f951-45c2-8d53-1a0950b5b0ff', '宿吉祥寺寄廬山隱者', '宿吉祥寺寄廬山隐者', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["風鳴雲外鐘，鶴宿千年松。","相思杳不見，月出山重重。"]', '["风鳴云外鐘，鹤宿千年松。","相思杳不见，月出山重重。"]', '诗', 'shi', '', NULL, '宿吉祥寺寄廬山隱者 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7760dc67-7ddf-4fb8-a489-4a913f16bf95', '邊思', '邊思', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["蘇武節旄盡，李陵音信稀。","梅當隴上發，人向隴頭歸。"]', '["蘇武節旄尽，李陵音信稀。","梅當隴上發，人向隴头归。"]', '诗', 'shi', '', NULL, '邊思 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68cf2f5d-2ff2-4081-ba12-7d20cc456749', '夜半步次古城', '夜半步次古城', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["茫茫死復生，惟有古時城。","夜半無鳥雀，花枝當月明。"]', '["茫茫死复生，惟有古时城。","夜半無鸟雀，花枝當月明。"]', '诗', 'shi', '', NULL, '夜半步次古城 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26988e9a-11dc-40af-8644-328a0b265855', '春夢', '春梦', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["空庭日照花如錦，紅妝美人當晝寢。","傍人不知夢中事，唯見玉釵時墜枕。"]', '["空庭日照花如錦，紅妝美人當晝寢。","傍人不知梦中事，唯见玉釵时墜枕。"]', '诗', 'shi', '', NULL, '春夢 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c76c16b-9be1-4923-a85f-58df8d776333', '宿青牛谷', '宿青牛谷', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["隨雲步入青牛谷，青牛道士留我宿。","可憐夜久月明中，唯有壇邊一枝竹。"]', '["隨云步入青牛谷，青牛道士留我宿。","可怜夜久月明中，唯有壇邊一枝竹。"]', '诗', 'shi', '', NULL, '宿青牛谷 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f34d0d-ac70-41f1-82be-cb794cf68a00', '槿', '槿', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["自用金錢買槿栽，二年方始一花開。","憐紅未許家人見，胡蜨爭知早到來。"]', '["自用金錢買槿栽，二年方始一花开。","怜紅未許家人见，胡蜨爭知早到来。"]', '诗', 'shi', '', NULL, '槿 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21079fb4-94a4-4bc9-bd23-541044bb45ae', '九日', '九日', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["黃菊紫菊傍籬落，摘菊泛酒愛芳新。","不堪今日望鄉意，強插茱萸隨衆人。"]', '["黄菊紫菊傍籬落，摘菊泛酒愛芳新。","不堪今日望乡意，強插茱萸隨衆人。"]', '诗', 'shi', '', NULL, '九日 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b406e77-9d06-4f08-aaaa-29630cefb3e7', '仙女詞', '仙女词', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["玉京初侍紫皇君，金縷鴛鴦滿絳裙。","仙宮一閉無消息，遙結芳心向碧雲。"]', '["玉京初侍紫皇君，金縷鴛鴦满絳裙。","仙宮一閉無消息，遙結芳心向碧云。"]', '诗', 'shi', '', NULL, '仙女詞 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b41013-3655-4b77-b536-12d617cdbc28', '句', '句', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["賢人處霄漢，荒澤自耕耘。","隴首降時雨，雷聲出夏雲。","一一鶴聲飛上天。"]', '["賢人处霄漢，荒澤自耕耘。","隴首降时雨，雷声出夏云。","一一鹤声飞上天。"]', '诗', 'shi', '', NULL, '句 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d024c9b9-948d-4145-b18e-b16162728be2', '享太廟樂章', '享太廟乐章', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["湜湜頎頎，融昭德輝。","不紐不舒，貫成九圍。","武烈文經，敷施當宜。","纂堯付啓，億萬熙熙。"]', '["湜湜頎頎，融昭德輝。","不紐不舒，貫成九圍。","武烈文經，敷施當宜。","纂堯付啓，億万熙熙。"]', '诗', 'shi', '', NULL, '享太廟樂章 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee22fe10-adc1-4c4c-add3-fffe913f4c4a', '樂天夢得有歲夜詩聊以奉和', '乐天梦得有歲夜诗聊以奉和', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["惜歲歲今盡，少年應不知。","淒涼數流輩，歡喜見孫兒。","暗減一身力，潛添滿鬢絲。","莫愁花笑老，花自幾多時。"]', '["惜歲歲今尽，少年應不知。","淒涼數流輩，歡喜见孫兒。","暗減一身力，潛添满鬢絲。","莫愁花笑老，花自幾多时。"]', '诗', 'shi', '', NULL, '樂天夢得有歲夜詩聊以奉和 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('963f314b-9b75-488d-8425-ac217712d67e', '李蘇州遺太湖石奇狀絕倫因題二十韻奉呈夢得樂天', '李蘇州遺太湖石奇狀絕倫因題二十韻奉呈梦得乐天', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["胚渾何時結，嵌空此日成。","掀蹲龍虎鬬，挾怪鬼神驚。","帶雨新水靜，輕敲碎玉鳴。","攙叉鋒刃簇，縷絡釣絲縈。","近水搖奇冷，依松助澹清。","通身鱗甲隱，透穴洞天明。","醜凸隆胡準，深凹刻兕觵。","雷風疑欲變，陰黑訝將行。","噤㾕微寒早，輪囷數片橫。","地祇愁墊壓，鰲足困支撐。","珍重姑蘇守，相憐嬾慢情。","爲探湖裏物，不怕浪中鯨。","利涉餘千里，山河僅百程。","池塘初展見，金玉自凡輕。","側眩魂猶悚，周觀意漸平。","似逢三益友，如對十年兄。","旺興添魔力，消煩破宿酲。","嫓人當綺皓，視秩即公卿。","念此園林寶，還須別識精。","詩仙有劉白，爲汝數逢迎。"]', '["胚渾何时結，嵌空此日成。","掀蹲龙虎鬬，挾怪鬼神驚。","带雨新水静，轻敲碎玉鳴。","攙叉鋒刃簇，縷絡釣絲縈。","近水搖奇冷，依松助澹清。","通身鱗甲隐，透穴洞天明。","醜凸隆胡準，深凹刻兕觵。","雷风疑欲变，陰黑訝將行。","噤㾕微寒早，輪囷數片橫。","地祇愁墊壓，鰲足困支撐。","珍重姑蘇守，相怜嬾慢情。","爲探湖裏物，不怕浪中鯨。","利涉餘千里，山河僅百程。","池塘初展见，金玉自凡轻。","側眩魂猶悚，周观意漸平。","似逢三益友，如对十年兄。","旺兴添魔力，消煩破宿酲。","嫓人當綺皓，視秩即公卿。","念此园林寶，還須別識精。","诗仙有劉白，爲汝數逢迎。"]', '诗', 'shi', '', NULL, '李蘇州遺太湖石奇狀絕倫因題二十韻奉呈夢得樂天 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17731285-cff6-4bcc-a31f-ff3a5efec520', '席上贈劉夢得', '席上贈劉梦得', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["粉署爲郎四十春，今來名輩更無人。","休論世上昇沉事，且鬬樽前見在身。","珠玉會應成咳唾，山川猶覺露精神。","莫嫌恃酒輕言語，曾把文章謁後塵。"]', '["粉署爲郎四十春，今来名輩更無人。","休論世上昇沉事，且鬬樽前见在身。","珠玉會應成咳唾，山川猶覺露精神。","莫嫌恃酒轻言語，曾把文章謁後塵。"]', '诗', 'shi', '', NULL, '席上贈劉夢得 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7843b0-3f32-4a73-85c5-cc4124f0b510', '句', '句', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["但愁封寄去，魔物或驚禪。","惟羨東都白居士，年年香積問禪師。","不是道公狂不得，恨公逢我不教狂。","地瘦草叢短，求人氣色沮。","憑酒意乃伸。"]', '["但愁封寄去，魔物或驚禪。","惟羨东都白居士，年年香積问禪師。","不是道公狂不得，恨公逢我不教狂。","地瘦草叢短，求人氣色沮。","憑酒意乃伸。"]', '诗', 'shi', '', NULL, '句 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3593efc-effc-4fa4-af6b-0500fc07c4b8', '賦得月照冰池', '賦得月照冰池', 'a4d53f86-1d49-41d2-a442-a75fb0a0d297', '唐', '["霽夕雲初歛，棲娥月未虧。","圓光生碧海，素色滿瑤池。","天迥輪空見，波凝影詎窺。","浮霜玉比彩，照像鏡同規。","皎潔寒偏淨，裴回夜轉宜。","誰憐幽境在，長與賞心隨。"]', '["霽夕云初歛，棲娥月未虧。","圓光生碧海，素色满瑤池。","天迥輪空见，波凝影詎窺。","浮霜玉比彩，照像镜同規。","皎潔寒偏淨，裴回夜轉宜。","誰怜幽境在，长與賞心隨。"]', '诗', 'shi', '', NULL, '賦得月照冰池 葉季良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6e4382-bb76-4ef5-964f-79ff81a92d3c', '賦得琢玉成器', '賦得琢玉成器', 'a4d53f86-1d49-41d2-a442-a75fb0a0d297', '唐', '["片玉寄幽石，紛綸當代名。","荆人獻始遇，良匠琢初成。","冰映寒光動，虹開晚色明。","雅容看更澈，餘響扣彌清。","自與瓊瑤比，方隨掌握榮。","因知君有用，高價佇連城。"]', '["片玉寄幽石，紛綸當代名。","荆人獻始遇，良匠琢初成。","冰映寒光动，虹开晚色明。","雅容看更澈，餘响扣彌清。","自與瓊瑤比，方隨掌握榮。","因知君有用，高價佇連城。"]', '诗', 'shi', '', NULL, '賦得琢玉成器 葉季良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a604b12-da73-4826-aa69-34551fe16307', '省試吳宮教美人戰', '省試吳宮教美人戰', 'a4d53f86-1d49-41d2-a442-a75fb0a0d297', '唐', '["強吳矜霸略，講武在深宮。","盡出嬌娥妓，先觀上將風。","揮戈羅袖卷，擐甲汗妝紅。","掩笑分旗下，含羞入隊中。","鼓停行未正，刑舉令纔崇。","自可威隣國，何勞逞戰功。"]', '["強吳矜霸略，講武在深宮。","尽出嬌娥妓，先观上將风。","揮戈羅袖卷，擐甲汗妝紅。","掩笑分旗下，含羞入隊中。","鼓停行未正，刑舉令纔崇。","自可威隣国，何勞逞戰功。"]', '诗', 'shi', '', NULL, '省試吳宮教美人戰 葉季良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('977ecb65-8497-42e8-8dd1-7a6273946650', '題歷山司徒右長史祖宅', '題歷山司徒右长史祖宅', '593ea0ec-a2b3-45af-83db-db6c76c5bed0', '唐', '["隳官長史籍，高步歷山椒。","麗句傳黃絹，香名播宋朝。","分能知止足，跡貴出塵囂。","松竹心長固，池臺興自饒。","龍宮欣訪舊，鶯谷忝遷喬。","從事叨承乏，銅章媿在腰。"]', '["隳官长史籍，高步歷山椒。","丽句傳黄絹，香名播宋朝。","分能知止足，跡貴出塵囂。","松竹心长固，池台兴自饒。","龙宮欣訪旧，鶯谷忝遷喬。","從事叨承乏，銅章媿在腰。"]', '诗', 'shi', '', NULL, '題歷山司徒右長史祖宅 湛賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e43aed7-a754-43cc-9504-7e1ae5b737fc', '伏覽呂侍郎丘員外舊題十三代祖歷山草堂詩因書記事', '伏覽呂侍郎丘員外旧題十三代祖歷山草堂诗因书記事', '593ea0ec-a2b3-45af-83db-db6c76c5bed0', '唐', '["名遂貴知己，道勝方晦跡。","高居葺蓮宮，遺文煥石壁。","桑田代已變，池草春猶碧。","識曲遇周郎，知音荷宗伯。","調逸南平兆，風清建安跡。","祖德今發揚，還同書史冊。"]', '["名遂貴知己，道勝方晦跡。","高居葺蓮宮，遺文煥石壁。","桑田代已变，池草春猶碧。","識曲遇周郎，知音荷宗伯。","調逸南平兆，风清建安跡。","祖德今發揚，還同书史冊。"]', '诗', 'shi', '', NULL, '伏覽呂侍郎丘員外舊題十三代祖歷山草堂詩因書記事 湛賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513c46a9-9e1f-4269-a29f-3b2c860f6cf5', '別慧山書堂', '別慧山书堂', '593ea0ec-a2b3-45af-83db-db6c76c5bed0', '唐', '["捲簾曉望雲平檻，下榻宵吟月半窗。","病守未能依結社，更施何術去爲邦。"]', '["捲簾晓望云平檻，下榻宵吟月半窗。","病守未能依結社，更施何術去爲邦。"]', '诗', 'shi', '', NULL, '別慧山書堂 湛賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721835c4-f691-47ed-a67d-844403e4c094', '暮春自南臺丞再除給事中', '暮春自南台丞再除給事中', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["再入青鎖闈，忝官誠自非。","拂塵驚物在，開戶似僧歸。","積草漸無逕，殘花猶灑衣。","禁垣偏日近，行坐是恩輝。"]', '["再入青鎖闈，忝官誠自非。","拂塵驚物在，开戶似僧归。","積草漸無逕，殘花猶灑衣。","禁垣偏日近，行坐是恩輝。"]', '诗', 'shi', '', NULL, '暮春自南臺丞再除給事中 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c09ae9-ce3c-4b59-9dfb-5f407ce64ac6', '御製段太尉碑', '御製段太尉碑', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["葬儀從儉禮，刊石荷堯君。","露跡垂繁字，天哀灑麗文。","詔深榮嗣子，海變記孤墳。","寶思皆涵象，皇心永念勳。","雅詞黃絹妙，渥澤紫泥分。","青史應同久，芳名萬古聞。"]', '["葬儀從儉禮，刊石荷堯君。","露跡垂繁字，天哀灑丽文。","詔深榮嗣子，海变記孤墳。","寶思皆涵象，皇心永念勳。","雅词黄絹妙，渥澤紫泥分。","青史應同久，芳名万古闻。"]', '诗', 'shi', '', NULL, '御製段太尉碑 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2f3dda-c1e0-4052-a093-bbb576f5b5ca', '御題國子監門', '御題国子監门', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["宸翰符玄造，榮題國子門。","筆鋒迴日月，字勢動乾坤。","簷下雲光絕，梁間鵲影飜。","張英聖莫擬，索靖妙難言。","爲著盤龍跡，能彰舞鳳蹲。","更隨垂露像，常以沐皇恩。"]', '["宸翰符玄造，榮題国子门。","笔鋒迴日月，字勢动乾坤。","簷下云光絕，梁间鵲影飜。","張英聖莫擬，索靖妙难言。","爲著盤龙跡，能彰舞鳳蹲。","更隨垂露像，常以沐皇恩。"]', '诗', 'shi', '', NULL, '御題國子監門 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15fac948-ab54-4256-a4cf-8c79f00bbc69', '御箭連中雙兔', '御箭連中雙兔', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["宸遊經上苑，羽獵向閑田。","狡兔初迷窟，纖驪詎著鞭。","三驅仍百步，一發遂雙連。","影射含霜草，魂消向月弦。","驩聲動寒木，喜氣滿晴天。","那似陳王意，空隨樂府篇。"]', '["宸游經上苑，羽獵向闲田。","狡兔初迷窟，纖驪詎著鞭。","三驱仍百步，一發遂雙連。","影射含霜草，魂消向月弦。","驩声动寒木，喜氣满晴天。","那似陳王意，空隨乐府篇。"]', '诗', 'shi', '', NULL, '御箭連中雙兔 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809905e2-7b41-4234-ab0f-47ea5433d192', '太學創置石經', '太学創置石經', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["聖唐復古制，德義功無替。","奧旨悅詩書，遺文分篆隸。","銀鉤互交映，石壁靡塵翳。","永與乾坤期，不逐日月逝。","儒林道益廣，學者心彌銳。","從此理化成，恩光遍遐裔。"]', '["聖唐复古制，德義功無替。","奧旨悅诗书，遺文分篆隸。","銀鉤互交映，石壁靡塵翳。","永與乾坤期，不逐日月逝。","儒林道益廣，学者心彌銳。","從此理化成，恩光遍遐裔。"]', '诗', 'shi', '', NULL, '太學創置石經 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('742fa643-9264-4e7d-b069-dd2d9b85148e', '觀南郊回仗', '观南郊回仗', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["傳警千門寂，南郊綵仗迴。","但驚龍再見，誰識日雙開。","德澤施雲雨，恩光變燼灰。","閱兵貔武振，聽樂鳳皇來。","候刻移宸輦，遵時集觀臺。","多慚遠臣賤，不得禮容陪。"]', '["傳警千门寂，南郊綵仗迴。","但驚龙再见，誰識日雙开。","德澤施云雨，恩光变燼灰。","閱兵貔武振，听乐鳳皇来。","候刻移宸輦，遵时集观台。","多慚远臣賤，不得禮容陪。"]', '诗', 'shi', '', NULL, '觀南郊回仗 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b371123-ea49-4d43-ba1a-ecdbd8b28218', '聞擊壤', '闻擊壤', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["堯年聽野老，擊壤復何云。","自謂歡由己，寧知德在君。","氣平閑易暢，聲賀作難分。","耕鑿方隨日，恩威比望雲。","簣桴均下調，和木等南薰。","無落於吾事，誰將帝已聞。"]', '["堯年听野老，擊壤复何云。","自謂歡由己，寧知德在君。","氣平闲易暢，声賀作难分。","耕鑿方隨日，恩威比望云。","簣桴均下調，和木等南薰。","無落於吾事，誰將帝已闻。"]', '诗', 'shi', '', NULL, '聞擊壤 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59098b43-3e67-4a63-855d-0b97c2b65423', '膏澤多豐年', '膏澤多豐年', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["帝德方多澤，莓莓井逕同。","八方甘雨布，四遠報年豐。","厫庾千廂在，幽流萬壑通。","候時勤稼穡，擊壤樂農功。","畎畝人無惰，田廬歲不空。","何須憂伏臘，千載賀堯風。"]', '["帝德方多澤，莓莓井逕同。","八方甘雨布，四远報年豐。","厫庾千廂在，幽流万壑通。","候时勤稼穡，擊壤乐農功。","畎畝人無惰，田廬歲不空。","何須憂伏臘，千載賀堯风。"]', '诗', 'shi', '', NULL, '膏澤多豐年 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d5cbb39-2531-4c18-b45e-fe6af04c857e', '東都父老望幸', '东都父老望幸', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["鑾輿秦地久，羽衛洛陽空。","彼土雖憑固，茲川乃得中。","龍顏覲白日，鶴髮仰清風。","望幸誠逾邈，懷來意不窮。","昔因封泰岳，今佇躡維嵩。","天地心無異，神祇理亦同。","翠華翔渭北，玉檢候關東。","衆願其難阻，明君早勒功。"]', '["鑾輿秦地久，羽衛洛陽空。","彼土雖憑固，茲川乃得中。","龙顏覲白日，鹤髮仰清风。","望幸誠逾邈，懷来意不窮。","昔因封泰岳，今佇躡維嵩。","天地心無異，神祇理亦同。","翠华翔渭北，玉檢候关东。","衆願其难阻，明君早勒功。"]', '诗', 'shi', '', NULL, '東都父老望幸 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ae2248-4126-4bd8-af7a-0fa63a811bdc', '嵩山望幸', '嵩山望幸', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["峻極位何崇，方知造化功。","降靈逢聖主，望幸表維嵩。","隱映連青壁，嵯峨向碧空。","象車因叶瑞，龍駕願升中。","萬歲聲長在，千巖氣轉雄。","東都歌盛事，西笑佇皇風。"]', '["峻極位何崇，方知造化功。","降靈逢聖主，望幸表維嵩。","隐映連青壁，嵯峨向碧空。","象车因叶瑞，龙駕願升中。","万歲声长在，千巖氣轉雄。","东都歌盛事，西笑佇皇风。"]', '诗', 'shi', '', NULL, '嵩山望幸 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8145eb-0d2a-43cd-bc58-dee0dc1f7bcd', '華清宮望幸', '华清宮望幸', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["驪岫接新豐，岧嶢駕碧空。","鑿山開秘殿，隱霧蔽仙宮。","絳闕猶棲鳳，雕梁尚帶虹。","溫泉曾浴日，華館舊迎風。","肅穆瞻雲輦，深沉閉綺櫳。","東郊望幸處，瑞氣靄濛濛。"]', '["驪岫接新豐，岧嶢駕碧空。","鑿山开秘殿，隐霧蔽仙宮。","絳闕猶棲鳳，雕梁尚带虹。","溫泉曾浴日，华館旧迎风。","肅穆瞻云輦，深沉閉綺櫳。","东郊望幸处，瑞氣靄濛濛。"]', '诗', 'shi', '', NULL, '華清宮望幸 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8442ba9-960f-4d72-9913-685653bddccd', '謁見日將至雙闕', '謁见日將至雙闕', 'd84125c5-160a-455d-b2b5-6f0e2acb63de', '唐', '["曉色臨雙闕，微臣禮位陪。","遠驚龍鳳覩，誰識冕旒開。","藹藹千年盛，顒顒萬國來。","天文標日月，時令布雲雷。","迥出黃金殿，全分白玉臺。","雕蟲竟何取，瞻戀不知迴。"]', '["晓色臨雙闕，微臣禮位陪。","远驚龙鳳覩，誰識冕旒开。","藹藹千年盛，顒顒万国来。","天文標日月，时令布云雷。","迥出黄金殿，全分白玉台。","雕蟲竟何取，瞻戀不知迴。"]', '诗', 'shi', '', NULL, '謁見日將至雙闕 薛存誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1488c5c-a16f-4e00-820f-6662d8fbd792', '南至日隔仗望含元殿爐香', '南至日隔仗望含元殿爐香', 'eda8859e-9966-4023-a1b9-50d617792769', '唐', '["冕旒初負扆，卉服盡朝天。","暘谷初移日，金爐漸起煙。","芬馨流遠近，散漫入貂蟬。","霜仗凝逾白，朱欄映轉鮮。","始看浮闕在，稍見逐風遷。","爲沐皇家慶，來瞻羽衛前。"]', '["冕旒初負扆，卉服尽朝天。","暘谷初移日，金爐漸起煙。","芬馨流远近，散漫入貂蟬。","霜仗凝逾白，朱欄映轉鲜。","始看浮闕在，稍见逐风遷。","爲沐皇家慶，来瞻羽衛前。"]', '诗', 'shi', '', NULL, '南至日隔仗望含元殿爐香 裴次元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68310aa-a666-4aa0-9319-618723638f65', '律中應鐘', '律中應鐘', 'eda8859e-9966-4023-a1b9-50d617792769', '唐', '["律窮方數寸，室暗在三重。","伶管灰先動，秦正節已逢。","商聲辭玉笛，羽調入金鐘。","密葉翻霜彩，輕冰歛水容。","望鴻南去絕，迎氣北來濃。","願託無凋性，寒林自比松。"]', '["律窮方數寸，室暗在三重。","伶管灰先动，秦正節已逢。","商声辞玉笛，羽調入金鐘。","密葉翻霜彩，轻冰歛水容。","望鴻南去絕，迎氣北来濃。","願託無凋性，寒林自比松。"]', '诗', 'shi', '', NULL, '律中應鐘 裴次元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f6d3a1-da3e-4651-a066-b9cb1c339757', '賦得亞父碎玉斗', '賦得亞父碎玉斗', 'eda8859e-9966-4023-a1b9-50d617792769', '唐', '["雄謀竟不決，寶玉將何愛。","倏爾霜刃揮，颯然春冰碎。","飛光動旗幟，散響驚環珮。","霜濃繡帳前，星流錦筵內。","圖王業已失，爲虜言空悔。","獨有青史中，英風冠千載。"]', '["雄謀竟不決，寶玉將何愛。","倏爾霜刃揮，颯然春冰碎。","飞光动旗幟，散响驚环珮。","霜濃繡帳前，星流錦筵內。","圖王業已失，爲虜言空悔。","独有青史中，英风冠千載。"]', '诗', 'shi', '', NULL, '賦得亞父碎玉斗 裴次元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e4823eb-f26d-42f8-ac31-9df86cf1a26f', '句', '句', 'eda8859e-9966-4023-a1b9-50d617792769', '唐', '["積高依郡城，迥拔凌霄漢。"]', '["積高依郡城，迥拔凌霄漢。"]', '诗', 'shi', '', NULL, '句 裴次元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00d7b9c5-cc58-49e2-b964-f2a5e9c198ea', '幷州路', '幷州路', 'ee3e1910-8b83-4c10-820d-7e1095d1549c', '唐', '["秋日幷州路，黃榆落故關。","孤城吹角罷，數騎射鵰還。","帳幕遙臨水，牛羊自下山。","征人正垂淚，烽火起雲間。"]', '["秋日幷州路，黄榆落故关。","孤城吹角罷，數騎射鵰還。","帳幕遙臨水，牛羊自下山。","征人正垂泪，烽火起云间。"]', '诗', 'shi', '', NULL, '幷州路 李宣遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e31f5acc-797a-4417-a479-7c69a70360ed', '近無西耗', '近無西耗', 'ee3e1910-8b83-4c10-820d-7e1095d1549c', '唐', '["遠戎兵壓境，遷客淚橫襟。","烽堠驚秦塞，囚居困越吟。","自憐牛馬走，未識犬羊心。","一月無消息，西看日又沈。"]', '["远戎兵壓境，遷客泪橫襟。","烽堠驚秦塞，囚居困越吟。","自怜牛马走，未識犬羊心。","一月無消息，西看日又沈。"]', '诗', 'shi', '', NULL, '近無西耗 李宣遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fca19f49-f819-464e-92ca-542790075444', '曲江亭望慈恩寺杏園花發', '曲江亭望慈恩寺杏园花發', 'a7762dc9-f4b8-42c3-b328-13dcdfdca79f', '唐', '["春晴凭水軒，仙杏發南園。","開蘂風初曉，浮香景欲暄。","光華臨御陌，色相對空門。","野雪遙添淨，山煙近借繁。","地閑分鹿苑，景勝類桃源。","況值新晴日，芳枝度彩鴛。"]', '["春晴凭水軒，仙杏發南园。","开蘂风初晓，浮香景欲暄。","光华臨御陌，色相对空门。","野雪遙添淨，山煙近借繁。","地闲分鹿苑，景勝類桃源。","況值新晴日，芳枝度彩鴛。"]', '诗', 'shi', '', NULL, '曲江亭望慈恩寺杏園花發 李君何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a25686-6eec-41e5-bb7e-f8379cb385fb', '除夜書情', '除夜书情', '2c0630bf-0b30-4f22-9e45-c807bfac6220', '唐', '["何處風塵歲，雲陽古驛前。","三冬不再稔，曉日又明年。","春入江南柳，寒歸塞北天。","還傷知候客，花景對韋編。"]', '["何处风塵歲，云陽古驛前。","三冬不再稔，晓日又明年。","春入江南柳，寒归塞北天。","還傷知候客，花景对韋編。"]', '诗', 'shi', '', NULL, '除夜書情 周弘亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('923f58d6-c2b1-49dc-aa45-3c32bdbd3b75', '曲江亭望慈恩寺杏園花發', '曲江亭望慈恩寺杏园花發', '2c0630bf-0b30-4f22-9e45-c807bfac6220', '唐', '["江亭閑望處，遠近見秦源。","古寺遲春景，新花發杏園。","萼中輕蘂密，枝上素姿繁。","拂雨雲初起，含風雪欲翻。","容輝明十地，香氣遍千門。","願莫隨桃李，芳菲不爲言。"]', '["江亭闲望处，远近见秦源。","古寺遲春景，新花發杏园。","萼中轻蘂密，枝上素姿繁。","拂雨云初起，含风雪欲翻。","容輝明十地，香氣遍千门。","願莫隨桃李，芳菲不爲言。"]', '诗', 'shi', '', NULL, '曲江亭望慈恩寺杏園花發 周弘亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28ea383-17ee-4a3e-9569-ddb2d57cba4f', '故鄉除夜', '故乡除夜', '2c0630bf-0b30-4f22-9e45-c807bfac6220', '唐', '["三百六十日云終，故鄉還與異鄉同。","非唯律變情堪恨，抑亦才疎命未通。","何處夜歌銷臘酒，誰家高燭候春風。","詩成始欲吟將看，早是去年牽課中。"]', '["三百六十日云終，故乡還與異乡同。","非唯律变情堪恨，抑亦才疎命未通。","何处夜歌銷臘酒，誰家高燭候春风。","诗成始欲吟將看，早是去年牽課中。"]', '诗', 'shi', '', NULL, '故鄉除夜 周弘亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dae62164-312c-4d78-a70e-29a05853ddfc', '曲江亭望慈恩寺杏園花發', '曲江亭望慈恩寺杏园花發', 'd057751c-99e7-4310-9451-7b03da50fe94', '唐', '["曲江晴望好，近接梵王家。","十畝開金地，千林發杏花。","映雲猶誤雪，煦日欲成霞。","紫陌傳香遠，紅泉落影斜。","園中春尚早，亭上路非賒。","芳景堪游處，其如惜物華。"]', '["曲江晴望好，近接梵王家。","十畝开金地，千林發杏花。","映云猶誤雪，煦日欲成霞。","紫陌傳香远，紅泉落影斜。","园中春尚早，亭上路非賒。","芳景堪游处，其如惜物华。"]', '诗', 'shi', '', NULL, '曲江亭望慈恩寺杏園花發 陳翥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d6632a-35d7-4327-9627-7d11084a9d66', '曲江亭望慈恩寺杏園花發', '曲江亭望慈恩寺杏园花發', '47df52b2-404f-4632-8f1f-26bc05c27f36', '唐', '["渚亭臨淨域，憑望一開軒。","晚日分初地，東風發杏園。","異香飄九陌，麗色映千門。","照灼瑤華散，葳蕤玉露繁。","未教游妓折，乍聽早鶯喧。","誰復爭桃李，含芳自不言。"]', '["渚亭臨淨域，憑望一开軒。","晚日分初地，东风發杏园。","異香飄九陌，丽色映千门。","照灼瑤华散，葳蕤玉露繁。","未教游妓折，乍听早鶯喧。","誰复爭桃李，含芳自不言。"]', '诗', 'shi', '', NULL, '曲江亭望慈恩寺杏園花發 曹著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ae2410-cf07-4c1f-8aac-5eaf2930842f', '魚上冰', '鱼上冰', 'c13d2c2b-c886-454a-b26b-08fff57746f1', '唐', '["春生寒氣減，稍動久潛魚。","乍喜東風至，來看曲岸初。","出冰朱鬣見，望日錦鱗舒。","漸覺流澌近，還欣掉尾餘。","噞喁情自樂，沿泝意寧疎。","儻得隨鯤化，終能上太虛。"]', '["春生寒氣減，稍动久潛鱼。","乍喜东风至，来看曲岸初。","出冰朱鬣见，望日錦鱗舒。","漸覺流澌近，還欣掉尾餘。","噞喁情自乐，沿泝意寧疎。","儻得隨鯤化，終能上太虛。"]', '诗', 'shi', '', NULL, '魚上冰 王公亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('725a2cdc-90a1-42c4-86ca-ba6d8a6c3dcf', '賦得竹箭有筠', '賦得竹箭有筠', '5fa2b0ce-e5d0-4c20-ac9a-f893a12fb72d', '唐', '["東南生綠竹，獨美有筠箭。","枝葉詎曾凋，風霜孰云變。","偏宜林表秀，多向歲寒見。","碧色乍蔥蘢，清光常蒨練。","皮開鳳彩出，節勁龍文現。","愛此守堅貞，含歌屬時彥。"]', '["东南生綠竹，独美有筠箭。","枝葉詎曾凋，风霜孰云变。","偏宜林表秀，多向歲寒见。","碧色乍蔥蘢，清光常蒨練。","皮开鳳彩出，節勁龙文現。","愛此守堅貞，含歌屬时彥。"]', '诗', 'shi', '', NULL, '賦得竹箭有筠 張仲方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9485631-69b1-4f42-acc3-78ae5a64a7c1', '贈毛仙翁', '贈毛仙翁', '5fa2b0ce-e5d0-4c20-ac9a-f893a12fb72d', '唐', '["毛仙翁，毛仙翁，容貌常如二八童。","幾歲頭梳雲鬢綠，無時面帶桃花紅。","眼前人世閱滄海，肘後藥成辭月宮。","方口秀眉編貝齒，瞭然炅炅雙瞳子。","芝椿稟氣本堅強，龜鶴計年應不死。","四海五山長獨游，矜貧傲富欺王侯。","靈通指下甎甓化，瑞氣爐中金玉流。","定是煙霞列仙侶，暫來塵俗救危苦。","紫霞妖女瓊華飛，秘法虔心傳付與。","陰功足，陰功成，羽駕何年歸上清。","待我休官了婚嫁，桃源洞裏覓仙兄。"]', '["毛仙翁，毛仙翁，容貌常如二八童。","幾歲头梳云鬢綠，無时面带桃花紅。","眼前人世閱滄海，肘後藥成辞月宮。","方口秀眉編貝齒，瞭然炅炅雙瞳子。","芝椿稟氣本堅強，龟鹤計年應不死。","四海五山长独游，矜貧傲富欺王侯。","靈通指下甎甓化，瑞氣爐中金玉流。","定是煙霞列仙侶，暫来塵俗救危苦。","紫霞妖女瓊华飞，秘法虔心傳付與。","陰功足，陰功成，羽駕何年归上清。","待我休官了婚嫁，桃源洞裏覓仙兄。"]', '诗', 'shi', '', NULL, '贈毛仙翁 張仲方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252908f7-8c99-4232-9021-845595914d80', '句', '句', '5fa2b0ce-e5d0-4c20-ac9a-f893a12fb72d', '唐', '["入門池色靜，登閣雨聲來。"]', '["入门池色静，登閣雨声来。"]', '诗', 'shi', '', NULL, '句 張仲方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae84339d-0128-4008-bdae-64111d23eafa', '和白樂天', '和白乐天', '75b203ab-ccf1-4b73-934c-7732fbcb3d09', '唐', '["病餘歸到洛陽頭，拭目開眉見白侯。","鳳詔恐君今歲去，龍門欠我舊時遊。","幾人樽下同歌詠，數盞燈前共獻酬。","相對憶劉劉在遠，寒宵耿耿夢長洲。"]', '["病餘归到洛陽头，拭目开眉见白侯。","鳳詔恐君今歲去，龙门欠我旧时游。","幾人樽下同歌詠，數盞灯前共獻酬。","相对憶劉劉在远，寒宵耿耿梦长洲。"]', '诗', 'shi', '', NULL, '和白樂天 崔玄亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd5c639-0cc6-4da2-9725-2952449bd592', '臨終詩', '臨終诗', '75b203ab-ccf1-4b73-934c-7732fbcb3d09', '唐', '["蹔榮蹔悴石敲火，即空即色眼生花。","許時爲客今歸去，大曆元年是我家。"]', '["蹔榮蹔悴石敲火，即空即色眼生花。","許时爲客今归去，大曆元年是我家。"]', '诗', 'shi', '', NULL, '臨終詩 崔玄亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83a78d4-0116-446c-86e3-9296672136b0', '句', '句', '75b203ab-ccf1-4b73-934c-7732fbcb3d09', '唐', '["共相呼喚醉歸來。"]', '["共相呼喚醉归来。"]', '诗', 'shi', '', NULL, '句 崔玄亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f064ff-4e03-42fd-a28b-6e1495baf93c', '省試臨淵羨魚', '省試臨淵羨鱼', '40ff76a3-7be1-4817-b7a4-06fba92cc0d6', '唐', '["清泚濯纓處，今來喜一臨。","慙無下釣處，空有羨魚心。","退省時頻改，謀身歲屢沈。","鬣成川上媚，網就水寧深。","頳尾臨波裏，朱鬚破浪潯。","此時儻不漏，江上免行吟。"]', '["清泚濯纓处，今来喜一臨。","慙無下釣处，空有羨鱼心。","退省时頻改，謀身歲屢沈。","鬣成川上媚，網就水寧深。","頳尾臨波裏，朱鬚破浪潯。","此时儻不漏，江上免行吟。"]', '诗', 'shi', '', NULL, '省試臨淵羨魚 徐牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('500fe33a-f30b-45a7-aeb2-48829ae8d1a8', '淮南游故居感舊酬西川李尚書德裕', '淮南游故居感旧酬西川李尚书德裕', 'b707e623-1a4a-4c42-9fbb-76e5145e8a29', '唐', '["昔年獻賦去江湄，今日行春到却悲。","三徑僅存新竹樹，四鄰惟見舊孫兒。","壁間潛認偷光處，川上寧忘結網時。","更見橋邊記名姓，始知題柱免人嗤。"]', '["昔年獻賦去江湄，今日行春到却悲。","三徑僅存新竹樹，四鄰惟见旧孫兒。","壁间潛認偷光处，川上寧忘結網时。","更见橋邊記名姓，始知題柱免人嗤。"]', '诗', 'shi', '', NULL, '淮南游故居感舊酬西川李尚書德裕 王播 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('112b68ed-ae0b-4340-b44a-854b52ff2af1', '題木蘭院二首 一', '題木蘭院二首 一', 'b707e623-1a4a-4c42-9fbb-76e5145e8a29', '唐', '["三十年前此院遊，木蘭花發院新修。","如今再到經行處，樹老無花僧白頭。"]', '["三十年前此院游，木蘭花發院新修。","如今再到經行处，樹老無花僧白头。"]', '诗', 'shi', '', NULL, '題木蘭院二首 一 王播 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e987d251-7f5b-45cd-b7f8-d9c08d49750b', '題木蘭院二首 二', '題木蘭院二首 二', 'b707e623-1a4a-4c42-9fbb-76e5145e8a29', '唐', '["上堂已了各西東，慚愧闍黎飯後鐘。","三十年來塵撲面，如今始得碧紗籠。"]', '["上堂已了各西东，慚愧闍黎飯後鐘。","三十年来塵撲面，如今始得碧紗籠。"]', '诗', 'shi', '', NULL, '題木蘭院二首 二 王播 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef45c9c1-e894-43ca-bae9-50ff17078e44', '上巳接清明游宴', '上巳接清明游宴', '09762d1e-3839-45e4-a64f-17dbbff9ecfc', '唐', '["上巳歡初罷，清明賞又追。","閏年侵舊曆，令節併芳時。","細雨鶯飛重，春風酒醞遲。","尋花迷白雪，看柳拆青絲。","淑氣如相待，天和意爲誰。","吁嗟名未立，空詠宴遊詩。"]', '["上巳歡初罷，清明賞又追。","閏年侵旧曆，令節併芳时。","細雨鶯飞重，春风酒醞遲。","尋花迷白雪，看柳拆青絲。","淑氣如相待，天和意爲誰。","吁嗟名未立，空詠宴游诗。"]', '诗', 'shi', '', NULL, '上巳接清明游宴 獨孤良弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec5ce8d-854b-4acc-bebd-f759aba918db', '次潭州酬唐侍御姚員外游道林嶽麓寺題示', '次潭州酬唐侍御姚員外游道林嶽麓寺題示', '0697042f-3986-4ff2-b8e0-e19c57723ab7', '唐', '["承明年老輙自論，乞得湘守東南奔。","爲聞楚國富山水，青嶂邐迤僧家園。","含香珥筆皆眷舊，謙抑自忘臺省尊。","不令執簡候亭館，直許攜手游山樊。","忽驚列岫曉來逼，朔雪洗盡煙嵐昏。","碧波迴嶼三山轉，丹檻繚郭千艘屯。","華鑣躞蹀絢砂步，大斾綵錯輝松門。","樛枝競騖龍蛇勢，折幹不滅風霆痕。","相重古殿倚嵓腹，別引新徑縈雲根。","目傷平楚虞帝魂，情多思遠聊開樽。","危弦細管逐歌飄，畫鼓繡靴隨節飜。","鏘金七言凌老杜，入木八法蟠高軒。","嗟余潦倒久不利，忍復感激論元元。"]', '["承明年老輙自論，乞得湘守东南奔。","爲闻楚国富山水，青嶂邐迤僧家园。","含香珥笔皆眷旧，謙抑自忘台省尊。","不令執簡候亭館，直許携手游山樊。","忽驚列岫晓来逼，朔雪洗尽煙嵐昏。","碧波迴嶼三山轉，丹檻繚郭千艘屯。","华鑣躞蹀絢砂步，大斾綵錯輝松门。","樛枝競騖龙蛇勢，折幹不滅风霆痕。","相重古殿倚嵓腹，別引新徑縈云根。","目傷平楚虞帝魂，情多思远聊开樽。","危弦細管逐歌飄，畫鼓繡靴隨節飜。","鏘金七言凌老杜，入木八法蟠高軒。","嗟余潦倒久不利，忍复感激論元元。"]', '诗', 'shi', '', NULL, '次潭州酬唐侍御姚員外游道林嶽麓寺題示 沈傳師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3bc156d-b418-43dc-9ba3-8ee39f9ec5e5', '和李德裕觀玉蘂花見懷之作', '和李德裕观玉蘂花见懷之作', '0697042f-3986-4ff2-b8e0-e19c57723ab7', '唐', '["曾對金鑾直，同依玉樹陰。","雪英飛舞近，煙葉動搖深。","素萼年年密，衰容日日侵。","勞君想華髮，近欲不勝簪。"]', '["曾对金鑾直，同依玉樹陰。","雪英飞舞近，煙葉动搖深。","素萼年年密，衰容日日侵。","勞君想华髮，近欲不勝簪。"]', '诗', 'shi', '', NULL, '和李德裕觀玉蘂花見懷之作 沈傳師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e399de69-6e6b-4370-bec8-fd39233fde1c', '贈毛仙翁', '贈毛仙翁', '0697042f-3986-4ff2-b8e0-e19c57723ab7', '唐', '["安期何事出雲煙，爲把仙方與世傳。","只向人間稱百歲，誰知洞裏過千年。","青牛到日迎方朔，丹竈開時共稚川。","更說桃源更深處，異花長占四時天。"]', '["安期何事出云煙，爲把仙方與世傳。","只向人间稱百歲，誰知洞裏過千年。","青牛到日迎方朔，丹竈开时共稚川。","更说桃源更深处，異花长占四时天。"]', '诗', 'shi', '', NULL, '贈毛仙翁 沈傳師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fedad3f7-f832-4743-93e3-de2618681119', '寄大府兄侍史', '寄大府兄侍史', '0697042f-3986-4ff2-b8e0-e19c57723ab7', '唐', '["積雪山陰馬過難，殘更深夜鐵衣寒。","將軍破了單于陣，更把兵書仔細看。"]', '["積雪山陰马過难，殘更深夜鐵衣寒。","將軍破了單于陣，更把兵书仔細看。"]', '诗', 'shi', '', NULL, '寄大府兄侍史 沈傳師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c83522-f832-4ced-9e03-d36bc6979811', '蒙泉', '蒙泉', '0697042f-3986-4ff2-b8e0-e19c57723ab7', '唐', '["京路馬駸駸，塵勞日向深。","蒙泉聊息駕，可以洗君心。"]', '["京路马駸駸，塵勞日向深。","蒙泉聊息駕，可以洗君心。"]', '诗', 'shi', '', NULL, '蒙泉 沈傳師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8038b0d7-c3e0-4b18-978d-3415250923de', '春從何處來', '春從何处来', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["欲識春生處，先從木德來。","入門潛報柳，度嶺暗驚梅。","透雪寒光散，消冰水鏡開。","曉迎郊騎發，夜逐斗杓迴。","淑氣空中變，新聲雨後催。","偏宜資律呂，應是候陽臺。"]', '["欲識春生处，先從木德来。","入门潛報柳，度嶺暗驚梅。","透雪寒光散，消冰水镜开。","晓迎郊騎發，夜逐斗杓迴。","淑氣空中变，新声雨後催。","偏宜資律呂，應是候陽台。"]', '诗', 'shi', '', NULL, '春從何處來 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdb4b21b-ccc1-4efe-a7cf-13785057a3f5', '貢院樓北新栽小松', '貢院楼北新栽小松', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["華省春霜曙，樓陰植小松。","移根依厚地，委質別危峰。","北戶知猶遠，東堂幸見容。","心堅終待鶴，枝嫩未成龍。","夜影看仍薄，朝嵐色漸濃。","山苗不可蔭，孤直俟秦封。"]', '["华省春霜曙，楼陰植小松。","移根依厚地，委質別危峰。","北戶知猶远，东堂幸见容。","心堅終待鹤，枝嫩未成龙。","夜影看仍薄，朝嵐色漸濃。","山苗不可蔭，孤直俟秦封。"]', '诗', 'shi', '', NULL, '貢院樓北新栽小松 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebf633c7-8a56-4ece-aa08-4beeef510ba3', '金在鎔', '金在鎔', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["巨橐方鎔物，洪鑪欲範金。","紫光看漸發，赤氣望逾深。","燄熱晴雲變，煙浮晝景陰。","堅剛由我性，鼓鑄任君心。","踴躍徒標異，沈潛自可欽。","何當得成器，待叩向知音。"]', '["巨橐方鎔物，洪鑪欲範金。","紫光看漸發，赤氣望逾深。","燄熱晴云变，煙浮晝景陰。","堅剛由我性，鼓鑄任君心。","踴躍徒標異，沈潛自可欽。","何當得成器，待叩向知音。"]', '诗', 'shi', '', NULL, '金在鎔 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5370fc4-16b6-49ca-a979-b40846f99625', '歸馬華山', '归马华山', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["牧野功成後，周王戰馬閑。","驅馳休伏皁，飲齕任依山。","逐日朝仍去，隨風暮自還。","冰生疑隴坂，葉落似榆關。","躞蹀仙峰下，騰驤渭水灣。","幸逢時偃武，不復鼓鼙間。"]', '["牧野功成後，周王戰马闲。","驱驰休伏皁，饮齕任依山。","逐日朝仍去，隨风暮自還。","冰生疑隴坂，葉落似榆关。","躞蹀仙峰下，腾驤渭水灣。","幸逢时偃武，不复鼓鼙间。"]', '诗', 'shi', '', NULL, '歸馬華山 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249ae962-2611-4d4f-aeca-7252cc60fafa', '夫子鼓琴得其人', '夫子鼓琴得其人', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["宣父窮玄奧，師襄授素琴。","稍殊流水引，全辨聖人心。","慕德聲逾感，懷人意自深。","泠泠傳妙手，摵摵振空林。","促調清風至，操弦白日沈。","曲終情不盡，千古仰知音。"]', '["宣父窮玄奧，師襄授素琴。","稍殊流水引，全辨聖人心。","慕德声逾感，懷人意自深。","泠泠傳妙手，摵摵振空林。","促調清风至，操弦白日沈。","曲終情不尽，千古仰知音。"]', '诗', 'shi', '', NULL, '夫子鼓琴得其人 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04588e31-0084-4040-952a-d698f5179092', '李都尉重陽日得蘇屬國書', '李都尉重陽日得蘇屬国书', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["降虜意何如，窮荒九月初。","三秋異鄉節，一紙故人書。","對酒情無極，開緘思有餘。","感時空寂寞，懷舊幾躊躇。","鴈盡平沙迥，煙銷大漠虛。","登臺南望處，掩淚對雙魚。"]', '["降虜意何如，窮荒九月初。","三秋異乡節，一紙故人书。","对酒情無極，开緘思有餘。","感时空寂寞，懷旧幾躊躇。","鴈尽平沙迥，煙銷大漠虛。","登台南望处，掩泪对雙鱼。"]', '诗', 'shi', '', NULL, '李都尉重陽日得蘇屬國書 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e33312-3699-4723-a276-f050f3a6db6e', '在巴南望郡南山呈樂天', '在巴南望郡南山呈乐天', '91c99d86-18e2-4a3b-8c41-dc305f1aea30', '唐', '["臨江一嶂白雲間，紅綠層層錦繡班。","不作巴南天外意，何殊昭應望驪山。"]', '["臨江一嶂白云间，紅綠層層錦繡班。","不作巴南天外意，何殊昭應望驪山。"]', '诗', 'shi', '', NULL, '在巴南望郡南山呈樂天 白行簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44e05f1-7746-4e3e-9bbb-39747d6c3b3d', '春雲', '春云', '7414ed33-40e3-4ea0-abea-d706fada9019', '唐', '["漠漠復溶溶，乘春任所從。","映林初展葉，觸石未成峰。","旭日消寒翠，晴煙點淨容。","霏微將似滅，深淺又如重。","薄彩臨溪散，輕陰帶雨濃。","空餘負樵者，嶺上自相逢。"]', '["漠漠复溶溶，乘春任所從。","映林初展葉，觸石未成峰。","旭日消寒翠，晴煙点淨容。","霏微將似滅，深淺又如重。","薄彩臨溪散，轻陰带雨濃。","空餘負樵者，嶺上自相逢。"]', '诗', 'shi', '', NULL, '春雲 裴澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc6bced5-a615-46e6-b945-85f48ba172c5', '賦得沽美玉', '賦得沽美玉', '65f8cc58-ec61-4aee-843c-a48c6151c976', '唐', '["誰憐被褐士，懷玉正求沽。","成器終期達，逢時豈見誣。","寶同珠照乘，價重劒論都。","浮彩朝虹滿，懸光夜月孤。","幾年淪瓦礫，今日出泥塗。","采斵資良匠，無令瑕掩瑜。"]', '["誰怜被褐士，懷玉正求沽。","成器終期達，逢时豈见誣。","寶同珠照乘，價重劒論都。","浮彩朝虹满，懸光夜月孤。","幾年淪瓦礫，今日出泥塗。","采斵資良匠，無令瑕掩瑜。"]', '诗', 'shi', '', NULL, '賦得沽美玉 羅立言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08b566f-fbe1-42e0-a407-5ebab46b7a6d', '寒食遣懷', '寒食遣懷', '0dc62500-4d55-41a3-9826-950c5f667738', '唐', '["繁華泣清露，悄悄落衣巾。","明日逢寒食，春風見故人。","病來羞滯楚，西去欲迷秦。","憔悴此時久，青山歸四鄰。"]', '["繁华泣清露，悄悄落衣巾。","明日逢寒食，春风见故人。","病来羞滯楚，西去欲迷秦。","憔悴此时久，青山归四鄰。"]', '诗', 'shi', '', NULL, '寒食遣懷 張燦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be4c8402-cadd-4d2d-8994-2ad5336035bc', '春日山亭', '春日山亭', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["醉來重整華陽巾，搔首驚看白髮新。","莫道愁多因病酒，只緣命薄不辭貧。","龍魚失水難爲用，龜玉蒙塵未見珍。","正是聖朝全盛日，詎知林下有閑人。"]', '["醉来重整华陽巾，搔首驚看白髮新。","莫道愁多因病酒，只緣命薄不辞貧。","龙鱼失水难爲用，龟玉蒙塵未见珍。","正是聖朝全盛日，詎知林下有闲人。"]', '诗', 'shi', '', NULL, '春日山亭 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9746efd9-bde5-4955-a36e-0ea30606c55f', '寄周韶州', '寄周韶州', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["十年學道困窮廬，空有長才重老儒。","功業要當垂永久，利名那得在須臾。","山中荆璞誰知玉，海底驪龍不見珠。","寄語故人休悵怏，古來賢達事多殊。"]', '["十年学道困窮廬，空有长才重老儒。","功業要當垂永久，利名那得在須臾。","山中荆璞誰知玉，海底驪龙不见珠。","寄語故人休悵怏，古来賢達事多殊。"]', '诗', 'shi', '', NULL, '寄周韶州 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e093f4c-1102-466b-a026-044f855cc80a', '秋夜醉歸有感而賦', '秋夜醉归有感而賦', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["銜盃誰道易更闌，沈醉歸來不自歡。","惆悵後時孤劒冷，寂寥無寐一燈殘。","竹窗涼雨鳴秋籟，江郭清砧擣夜寒。","多少客懷消不得，臨風搔首浩漫漫。"]', '["銜盃誰道易更闌，沈醉归来不自歡。","惆悵後时孤劒冷，寂寥無寐一灯殘。","竹窗涼雨鳴秋籟，江郭清砧擣夜寒。","多少客懷消不得，臨风搔首浩漫漫。"]', '诗', 'shi', '', NULL, '秋夜醉歸有感而賦 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd98eed-b2ce-4969-ae2e-4a8e95d5abdb', '寄范使君', '寄范使君', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["未秋爲別已終秋，咫尺婁江路阻脩。","心上惟君知委曲，眼前獨我逐漂流。","從來姑息難爲好，到底依棲總是諏。","西望家山成浩歎，臨風搔首不勝愁。"]', '["未秋爲別已終秋，咫尺婁江路阻脩。","心上惟君知委曲，眼前独我逐漂流。","從来姑息难爲好，到底依棲總是諏。","西望家山成浩歎，臨风搔首不勝愁。"]', '诗', 'shi', '', NULL, '寄范使君 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8833192-b078-4180-9411-0a15220ceddd', '送羅約', '送羅約', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["雨晴江館柳依依，握手那堪此別離。","獨鶴孤琴隨遠斾，紅亭綠酒惜分岐。","月明野店聞雞早，花暗關城匹馬遲。","從夜定知相憶處，東風回首不勝悲。"]', '["雨晴江館柳依依，握手那堪此別離。","独鹤孤琴隨远斾，紅亭綠酒惜分岐。","月明野店闻雞早，花暗关城匹马遲。","從夜定知相憶处，东风回首不勝悲。"]', '诗', 'shi', '', NULL, '送羅約 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df51290b-9d9f-422f-9091-847f2ac62adc', '題李昭訓山水', '題李昭訓山水', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["卜築藏修地自偏，尊前詩酒集羣賢。","半岩松暝時藏鶴，一枕秋聲夜聽泉。","風月謾勞酬逸興，漁樵隨處度流年。","南州人物依然在，山水幽居勝輞川。"]', '["卜築藏修地自偏，尊前诗酒集羣賢。","半岩松暝时藏鹤，一枕秋声夜听泉。","风月謾勞酬逸兴，漁樵隨处度流年。","南州人物依然在，山水幽居勝輞川。"]', '诗', 'shi', '', NULL, '題李昭訓山水 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ad992a-3b8d-437c-af2a-d21dca171871', '處厚遊杭作詩寄之', '处厚游杭作诗寄之', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["江村搖落暫逢秋，況是聞君獨遠遊。","浙水風煙思弔古，楚鄉人物賦登樓。","書沈寒鴈雲邊影，夢繞清猨月下愁。","念我故人勞碌久，不如投老臥滄洲。"]', '["江村搖落暫逢秋，況是闻君独远游。","浙水风煙思弔古，楚乡人物賦登楼。","书沈寒鴈云邊影，梦繞清猨月下愁。","念我故人勞碌久，不如投老臥滄洲。"]', '诗', 'shi', '', NULL, '處厚遊杭作詩寄之 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420c754b-adb6-4e52-830e-0c6ecac2db90', '山中有懷李十二', '山中有懷李十二', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["林前風景晚蒼蒼，林下懷人路杳茫。","白髮流年淹舊業，碧山茅屋臥斜陽。","客邊秋興悲張翰，病裏春情笑沈郎。","何事登樓□□□，幾迴搔首□思歸。"]', '["林前风景晚蒼蒼，林下懷人路杳茫。","白髮流年淹旧業，碧山茅屋臥斜陽。","客邊秋兴悲張翰，病裏春情笑沈郎。","何事登楼□□□，幾迴搔首□思归。"]', '诗', 'shi', '', NULL, '山中有懷李十二 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff8ef2ab-e6be-49f9-a64c-5a54fd42f0ab', '客中作', '客中作', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["異鄉歲晚悵離懷，遊子驅馳媿不才。","夜夜砧聲催客去，年年鴈影帶寒來。","半林殘葉迎霜落，三徑黃花近節開。","幾度無聊倍惆悵，臨風搔首獨興哀。"]', '["異乡歲晚悵離懷，游子驱驰媿不才。","夜夜砧声催客去，年年鴈影带寒来。","半林殘葉迎霜落，三徑黄花近節开。","幾度無聊倍惆悵，臨风搔首独兴哀。"]', '诗', 'shi', '', NULL, '客中作 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd43b692-8546-4a8b-b12c-1059d85f9a1e', '山寺律僧畫蘭竹圖', '山寺律僧畫蘭竹圖', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["偶來絕頂興無窮，獨有山僧筆最工。","綠徑日長袁戶在，紫荃秋晚謝庭空。","離花影度湘江月，遺珮香生洛浦風。","欲結歲寒盟不去，忘機相對畫圖中。"]', '["偶来絕頂兴無窮，独有山僧笔最工。","綠徑日长袁戶在，紫荃秋晚謝庭空。","離花影度湘江月，遺珮香生洛浦风。","欲結歲寒盟不去，忘機相对畫圖中。"]', '诗', 'shi', '', NULL, '山寺律僧畫蘭竹圖 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3382496a-1340-4163-b42d-8e77c9969cb6', '送客之杭', '送客之杭', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["西風吹[冷]透貂裘，行色匆匆不暫留。","帆帶夕陽投越浦，心隨明月到杭州。","風清聽漏驚鄉夢，燈下聞歌亂別愁。","懸想到杭州興地，尊前應與話離憂。"]', '["西风吹[冷]透貂裘，行色匆匆不暫留。","帆带夕陽投越浦，心隨明月到杭州。","风清听漏驚乡梦，灯下闻歌亂別愁。","懸想到杭州兴地，尊前應與話離憂。"]', '诗', 'shi', '', NULL, '送客之杭 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a13ca7f-7b16-4891-a384-6691284c482d', '有感二首 一', '有感二首 一', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["何事離懷入夢頻，貧居寂莫四無鄰。","詩因韻險難成律，酒爲愁多不顧身。","眼底故人驚歲別，尊前華髮逐時新。","十年飄泊如萍跡，一度登臨一悵神。"]', '["何事離懷入梦頻，貧居寂莫四無鄰。","诗因韻險难成律，酒爲愁多不顧身。","眼底故人驚歲別，尊前华髮逐时新。","十年飄泊如萍跡，一度登臨一悵神。"]', '诗', 'shi', '', NULL, '有感二首 一 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('808e9052-a0a5-492a-955b-4751f207c132', '有感二首 二', '有感二首 二', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["搔首臨風獨倚欄，客邊驚覺歲華殘。","栖遲未遇常鋾薦，邂逅寧彈貢禹冠。","有興不愁詩韻險，無聊只怕酒杯乾。","何如日日長如醉，付與詩人一笑看。"]', '["搔首臨风独倚欄，客邊驚覺歲华殘。","栖遲未遇常鋾薦，邂逅寧彈貢禹冠。","有兴不愁诗韻險，無聊只怕酒杯乾。","何如日日长如醉，付與诗人一笑看。"]', '诗', 'shi', '', NULL, '有感二首 二 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e929886-6739-4e8b-bebd-560091ec2028', '送沈侯之京', '送沈侯之京', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["悠悠旌斾出東樓，特出仙郎上帝州。","劉旻才高能富國，蕭何人傑足封侯。","關河弱柳垂金縷，水驛青帘拂畫樓。","欲盡故人尊酒意，春風江上暫停舟。"]', '["悠悠旌斾出东楼，特出仙郎上帝州。","劉旻才高能富国，蕭何人傑足封侯。","关河弱柳垂金縷，水驛青帘拂畫楼。","欲尽故人尊酒意，春风江上暫停舟。"]', '诗', 'shi', '', NULL, '送沈侯之京 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ced2a2-cdb0-4ad7-8504-6c43fc8bdf43', '寄羽士', '寄羽士', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["別來有路隔仙凡，幾度臨風欲去難。","樂道無時忘鶴伴，談玄何日到星壇。","山中勝景常留客，林下清風好煉丹。","使我浮生塵鞅脫，相從應得一盤桓。"]', '["別来有路隔仙凡，幾度臨风欲去难。","乐道無时忘鹤伴，談玄何日到星壇。","山中勝景常留客，林下清风好煉丹。","使我浮生塵鞅脫，相從應得一盤桓。"]', '诗', 'shi', '', NULL, '寄羽士 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93d833bc-de2c-471c-8498-8377b2725f82', '題趙支', '題趙支', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["林間曲徑掩衡茅，遶屋青青翡翠梢。","一枕秋聲鸞舞月，半窗雲影鶴歸巢。","曾聞賈誼陳奇策，肯學楊雄賦解嘲。","我有清風高節在，知君不負歲寒交。"]', '["林间曲徑掩衡茅，遶屋青青翡翠梢。","一枕秋声鸾舞月，半窗云影鹤归巢。","曾闻賈誼陳奇策，肯学楊雄賦解嘲。","我有清风高節在，知君不負歲寒交。"]', '诗', 'shi', '', NULL, '題趙支 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ceaed1a-4c6c-487e-ac43-be8b0939d2f5', '司馬遷墓', '司马遷墓', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["落落長才負不羈，中原回首益堪悲。","英雄此日誰能薦，聲價當時衆所推。","一代高風留異國，百年遺跡剩殘碑。","經過詞客空惆悵，落日寒煙賦黍離。"]', '["落落长才負不羈，中原回首益堪悲。","英雄此日誰能薦，声價當时衆所推。","一代高风留異国，百年遺跡剩殘碑。","經過词客空惆悵，落日寒煙賦黍離。"]', '诗', 'shi', '', NULL, '司馬遷墓 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc1f8ed-d210-41cc-8b71-b59d730cf0b6', '春遊', '春游', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["錦袍日暖耀冰蠶，上客陪遊酒半酣。","笑拂吟鞭邀好興，醉欹烏帽逞雄談。","樓前弱柳搖金縷，林外遙山隔翠嵐。","正是太平行樂處，春風花下且停驂。"]', '["錦袍日暖耀冰蠶，上客陪游酒半酣。","笑拂吟鞭邀好兴，醉欹烏帽逞雄談。","楼前弱柳搖金縷，林外遙山隔翠嵐。","正是太平行乐处，春风花下且停驂。"]', '诗', 'shi', '', NULL, '春遊 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d3b17d-fcf2-4e26-85cc-b20973baec0e', '水西草堂', '水西草堂', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["蘿徑蕭然曲業存，閑雲流水四無鄰。","身留白屋潛踪跡，門□□吟學隱淪。","吟對琴尊江上月，笑看花木鏡中春。","遺書自有親□處，何必驅馳擾世塵。"]', '["蘿徑蕭然曲業存，闲云流水四無鄰。","身留白屋潛踪跡，门□□吟学隐淪。","吟对琴尊江上月，笑看花木镜中春。","遺书自有親□处，何必驱驰擾世塵。"]', '诗', 'shi', '', NULL, '水西草堂 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34027b3f-c235-49e6-9fd4-990d009c453c', '送羽衣之京', '送羽衣之京', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["羽衣縹緲拂塵囂，悵別河梁贈柳條。","閬苑雲深孤鶴逈，蓬萊天近一身遙。","香浮寶輦仙風潤，花落瑤壇絳雨消。","自是長生林下客，也陪鴛鷺入清朝。"]', '["羽衣縹緲拂塵囂，悵別河梁贈柳條。","閬苑云深孤鹤逈，蓬萊天近一身遙。","香浮寶輦仙风潤，花落瑤壇絳雨消。","自是长生林下客，也陪鴛鷺入清朝。"]', '诗', 'shi', '', NULL, '送羽衣之京 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4b8d84-47a0-4187-9757-22fa3ad8677c', '題道院壁', '題道院壁', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["山中舊宅四無鄰，草淨雲和逈絕塵。","神棗胡麻能飯客，桃花流水蔭通津。","星壇火伏煙霞暝，林壑春香鳥雀馴。","若使凡緣終可脫，也應從此度閑身。"]', '["山中旧宅四無鄰，草淨云和逈絕塵。","神棗胡麻能飯客，桃花流水蔭通津。","星壇火伏煙霞暝，林壑春香鸟雀馴。","若使凡緣終可脫，也應從此度闲身。"]', '诗', 'shi', '', NULL, '題道院壁 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb43cb3-ac66-45da-80d7-28e8dcf8d21f', '贈歐陽詹', '贈歐陽詹', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["爲客囊無季子金，半生踪跡任浮沈。","服勤因念劬勞重，思養徒懷感慨深。","島外斷雲凝遠日，天涯芳草動愁心。","家林千里遙相憶，幾度停車一悵吟。"]', '["爲客囊無季子金，半生踪跡任浮沈。","服勤因念劬勞重，思養徒懷感慨深。","島外斷云凝远日，天涯芳草动愁心。","家林千里遙相憶，幾度停车一悵吟。"]', '诗', 'shi', '', NULL, '贈歐陽詹 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ce7d70-ec64-4c42-8545-fc5fa2a18790', '邵公母', '邵公母', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["搔首驚聞楚些歌，拂衣歸去淚懸河。","劬勞常想三春恨，思養其如寸草何。","淛水夢懷千里遠，蘇臺愁望白雲多。","傷心獨有黃堂客，幾度臨風詠蓼莪。"]', '["搔首驚闻楚些歌，拂衣归去泪懸河。","劬勞常想三春恨，思養其如寸草何。","淛水梦懷千里远，蘇台愁望白云多。","傷心独有黄堂客，幾度臨风詠蓼莪。"]', '诗', 'shi', '', NULL, '邵公母 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('610b6a5f-0703-4ebc-8359-dbcbd4be40c7', '客中作', '客中作', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["千里雲山戀舊遊，寒窗涼雨夜悠悠。","浮亭花竹頻勞夢，別路風煙半是愁。","芳草傍人空對酒，流年多病倦登樓。","一杯重向樽前醉，莫遣相思累白頭。"]', '["千里云山戀旧游，寒窗涼雨夜悠悠。","浮亭花竹頻勞梦，別路风煙半是愁。","芳草傍人空对酒，流年多病倦登楼。","一杯重向樽前醉，莫遣相思累白头。"]', '诗', 'shi', '', NULL, '客中作 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7fdeea9-903c-422d-9776-34ce1b808e34', '贈楊處厚', '贈楊处厚', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["十年學道苦勞神，贏得尊前一病身。","天上故人皆自貴，山中明月獨相親。","客心淡泊偏宜靜，吾道從容不厭貧。","幾度臨風一回首，笑看華髮及時新。"]', '["十年学道苦勞神，贏得尊前一病身。","天上故人皆自貴，山中明月独相親。","客心淡泊偏宜静，吾道從容不厭貧。","幾度臨风一回首，笑看华髮及时新。"]', '诗', 'shi', '', NULL, '贈楊處厚 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a692cc-c56d-42ee-9483-71823fa9bedd', '重贈張籍', '重贈張籍', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["舊日儀容只宛然，笑談不覺度流年。","凡緣未了嗟無子，薄命能孤不怨天。","一醉便同塵外客，百杯疑是酒中仙。","人生隨處堪爲樂，管甚秋香滿鬢邊。"]', '["旧日儀容只宛然，笑談不覺度流年。","凡緣未了嗟無子，薄命能孤不怨天。","一醉便同塵外客，百杯疑是酒中仙。","人生隨处堪爲乐，管甚秋香满鬢邊。"]', '诗', 'shi', '', NULL, '重贈張籍 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91268533-471e-400b-b149-b5d13d546ff7', '贈殷以道', '贈殷以道', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["世路紅塵懶步趨，長年結屋傍巖隅。","獨留鄉井誠非隱，老向山林不自愚。","肯信白圭終在璞，誰憐滄海竟遺珠。","閑來撫景窮吟處，尊酒臨風不自娛。"]', '["世路紅塵懶步趨，长年結屋傍巖隅。","独留乡井誠非隐，老向山林不自愚。","肯信白圭終在璞，誰怜滄海竟遺珠。","闲来撫景窮吟处，尊酒臨风不自娛。"]', '诗', 'shi', '', NULL, '贈殷以道 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d297f4f-d935-4c89-9c5b-f0934ca509c4', '翁母些', '翁母些', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["滿頭華髮向人垂，長逝音容逈莫追。","先壠每懷風木夜，畫堂無復綵衣時。","停車遙望孤雲影，翹首驚看弔鶴悲。","獨有賢人崇孝義，傷心共詠蓼莪詩。"]', '["满头华髮向人垂，长逝音容逈莫追。","先壠每懷风木夜，畫堂無复綵衣时。","停车遙望孤云影，翹首驚看弔鹤悲。","独有賢人崇孝義，傷心共詠蓼莪诗。"]', '诗', 'shi', '', NULL, '翁母些 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eceea571-d49a-4753-8a90-d5150f57e509', '題山莊', '題山莊', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["蘿屋蕭蕭事事幽，臨風搔首遠凝眸。","東園松菊存遺業，晚景桑榆樂舊遊。","吟對清尊江上月，笑談華髮鏡中秋。","牀頭濁酒時時漉，上客相過一任留。"]', '["蘿屋蕭蕭事事幽，臨风搔首远凝眸。","东园松菊存遺業，晚景桑榆乐旧游。","吟对清尊江上月，笑談华髮镜中秋。","牀头濁酒时时漉，上客相過一任留。"]', '诗', 'shi', '', NULL, '題山莊 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d42c39a9-e273-45e9-9b88-6198596d374a', '沈存尚林亭夜宴', '沈存尚林亭夜宴', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["草堂寂寂景偏幽，到此令人一縱眸。","松菊寒香三徑晚，桑榆煙景兩淮秋。","近山紅葉堆林屋，隔浦青帘拂畫樓。","終日忘情能自樂，清尊應得遣閑愁。"]', '["草堂寂寂景偏幽，到此令人一縱眸。","松菊寒香三徑晚，桑榆煙景兩淮秋。","近山紅葉堆林屋，隔浦青帘拂畫楼。","終日忘情能自乐，清尊應得遣闲愁。"]', '诗', 'shi', '', NULL, '沈存尚林亭夜宴 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e04a36c8-eae9-437e-880e-4cbea61baba0', '題孫君山亭', '題孫君山亭', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["長年樂道遠塵氛，靜築藏修學隱淪。","吟對琴樽庭下月，笑看花木檻前春。","閑來欲著登山屐，醉裏還披漉酒巾。","林壑能忘軒冕貴，白雲黃鶴好相親。"]', '["长年乐道远塵氛，静築藏修学隐淪。","吟对琴樽庭下月，笑看花木檻前春。","闲来欲著登山屐，醉裏還披漉酒巾。","林壑能忘軒冕貴，白云黄鹤好相親。"]', '诗', 'shi', '', NULL, '題孫君山亭 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2291a937-cdb2-4e74-ba2a-68dcc7f5688a', '題徐俞山居', '題徐俞山居', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["青山重疊巧裁攢，引水流泉夜激湍。","嵐鎖巖扉清晝瞑，雲歸松壑翠陰寒。","不因李相門前見，曾向袁生畫裏看。","老我不堪詩思杳，幾回吟倚曲欄干。"]', '["青山重叠巧裁攢，引水流泉夜激湍。","嵐鎖巖扉清晝瞑，云归松壑翠陰寒。","不因李相门前见，曾向袁生畫裏看。","老我不堪诗思杳，幾回吟倚曲欄干。"]', '诗', 'shi', '', NULL, '題徐俞山居 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4369b75b-6729-4281-807d-c7d5b154e66f', '送范啓東還京', '送范啓东還京', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["蕭蕭行李上征鞍，滿目離情欲去難。","客裏故人尊酒別，天涯遊子弊裘寒。","官橋楊柳和愁折，驛路梅花帶雪看。","重到京華舊遊處，春風佳麗好盤桓。"]', '["蕭蕭行李上征鞍，满目離情欲去难。","客裏故人尊酒別，天涯游子弊裘寒。","官橋楊柳和愁折，驛路梅花带雪看。","重到京华旧游处，春风佳丽好盤桓。"]', '诗', 'shi', '', NULL, '送范啓東還京 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2674caf2-9c0c-4db5-8f01-9ad5c898d49b', '樓城敘別', '楼城敘別', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["故人爲客上神州，傾蓋相逢感昔遊。","屈指年華嗟遠別，對牀風雨話離愁。","清樽不負花前約，白髮驚看鏡裏秋。","此際那堪重分手，緣波芳草暫停舟。"]', '["故人爲客上神州，傾蓋相逢感昔游。","屈指年华嗟远別，对牀风雨話離愁。","清樽不負花前約，白髮驚看镜裏秋。","此際那堪重分手，緣波芳草暫停舟。"]', '诗', 'shi', '', NULL, '樓城敘別 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57938398-b4bb-4494-82b3-f36c14f76658', '寫意二首 一', '寫意二首 一', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["寂寥荒館閉閑門，苔徑陰陰屐少痕。","白髮顛狂塵夢斷，青氈泠落客心存。","高山流水琴三弄，明月清風酒一樽。","醉後曲肱林下臥，此生榮辱不須論。"]', '["寂寥荒館閉闲门，苔徑陰陰屐少痕。","白髮顛狂塵梦斷，青氈泠落客心存。","高山流水琴三弄，明月清风酒一樽。","醉後曲肱林下臥，此生榮辱不須論。"]', '诗', 'shi', '', NULL, '寫意二首 一 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba64c085-07d7-4323-9f12-5b9d6f4e296a', '寫意二首 二', '寫意二首 二', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["蕭蕭華髮滿頭生，深遠蓬門倦送迎。","獨喜冥心無外慕，自憐知命不求榮。","閑情欲賦思陶令，臥病和人問馬卿。","林下貧居甘困守，儘教城市不知名。"]', '["蕭蕭华髮满头生，深远蓬门倦送迎。","独喜冥心無外慕，自怜知命不求榮。","闲情欲賦思陶令，臥病和人问马卿。","林下貧居甘困守，儘教城市不知名。"]', '诗', 'shi', '', NULL, '寫意二首 二 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d201c3e6-164a-4668-b5cd-a637b59caf4f', '贈浙西李相公', '贈浙西李相公', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["長庚烈烈獨遙天，盛世應知降謫仙。","月裏昔曾分兔藥，人間今喜得椿年。","文章政事追先達，冠蓋聲華羨昔賢。","尊酒與君稱壽畢，春風入醉綺羅筵。"]', '["长庚烈烈独遙天，盛世應知降謫仙。","月裏昔曾分兔藥，人间今喜得椿年。","文章政事追先達，冠蓋声华羨昔賢。","尊酒與君稱壽畢，春风入醉綺羅筵。"]', '诗', 'shi', '', NULL, '贈浙西李相公 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b543e7c6-827c-4426-9e56-a73dca37d38c', '天台', '天台', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["碧溪流水泛桃花，樹繞天台逈不賒。","洞裏無塵通客境，人間有路入仙家。","雞鳴犬吠三山近，草靜雲和一徑斜。","此地不知何處去，暫留瓊珮臥煙霞。"]', '["碧溪流水泛桃花，樹繞天台逈不賒。","洞裏無塵通客境，人间有路入仙家。","雞鳴犬吠三山近，草静云和一徑斜。","此地不知何处去，暫留瓊珮臥煙霞。"]', '诗', 'shi', '', NULL, '天台 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87e09967-1a44-4c5e-84ea-9c42c79ddad2', '送陳衡', '送陳衡', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["秋江煙景晚蒼蒼，江上離人促去航。","千里一官嗟獨往，十年雙髩付三霜。","雲迷樓曲親庭遠，夢遶通山客路長。","不必臨風悲冷落，古來白首尚爲郎。"]', '["秋江煙景晚蒼蒼，江上離人促去航。","千里一官嗟独往，十年雙髩付三霜。","云迷楼曲親庭远，梦遶通山客路长。","不必臨风悲冷落，古来白首尚爲郎。"]', '诗', 'shi', '', NULL, '送陳衡 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61a291be-82d4-447c-880e-02588a163229', '送沈翔', '送沈翔', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["江上西風一櫂歸，故人此別會應稀。","清朝盡道無遺逸，當路誰曾訪少微。","謾有才華嗟未達，閑尋鷗鳥暫忘機。","臨岐不用空惆悵，未必新豐老布衣。"]', '["江上西风一櫂归，故人此別會應稀。","清朝尽道無遺逸，當路誰曾訪少微。","謾有才华嗟未達，闲尋鷗鸟暫忘機。","臨岐不用空惆悵，未必新豐老布衣。"]', '诗', 'shi', '', NULL, '送沈翔 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c58691a5-35ce-435d-a5f1-bc7e217981d7', '過蠡湖', '過蠡湖', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["東湖煙水浩漫漫，湘浦秋聲入夜寒。","風外暗香飄落粉，月中清影無離鸞。","多情袁尹頻移席，有道喬仙獨倚闌。","幾度篝簾相對處，無邊詩思到吟壇。"]', '["东湖煙水浩漫漫，湘浦秋声入夜寒。","风外暗香飄落粉，月中清影無離鸾。","多情袁尹頻移席，有道喬仙独倚闌。","幾度篝簾相对处，無邊诗思到吟壇。"]', '诗', 'shi', '', NULL, '過蠡湖 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7946a8-5bb2-46aa-a315-26090c935d28', '登環翠樓', '登环翠楼', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["山中地僻好藏修，寂寂幽居架小樓。","雲樹四圍當戶瞑，煙嵐一帶隔簾浮。","舉杯對月邀詩興，撫景令人豁醉眸。","我亦人間肥遁客，也將蹤跡寄林丘。"]', '["山中地僻好藏修，寂寂幽居架小楼。","云樹四圍當戶瞑，煙嵐一带隔簾浮。","舉杯对月邀诗兴，撫景令人豁醉眸。","我亦人间肥遁客，也將蹤跡寄林丘。"]', '诗', 'shi', '', NULL, '登環翠樓 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db63521-2550-452f-ac70-9d605c61ea0e', '遊淮雲寺', '游淮云寺', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["白雲深鎖沃州山，冠蓋登臨衆仰攀。","松徑風清聞鶴唳，曇花香瞑見僧還。","玄機隱隱應難覺，塵事悠悠了不關。","興盡凡緣因未晚，裴回依舊到人間。"]', '["白云深鎖沃州山，冠蓋登臨衆仰攀。","松徑风清闻鹤唳，曇花香瞑见僧還。","玄機隐隐應难覺，塵事悠悠了不关。","兴尽凡緣因未晚，裴回依旧到人间。"]', '诗', 'shi', '', NULL, '遊淮雲寺 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a720961-a110-49ed-a0a4-032177945e48', '遊報本寺 一', '游報本寺 一', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["山房寂寂蓽門開，此日相期社友來。","雅興共尋方外樂，新詩爭羨郢中才。","茶煙褭褭籠禪榻，竹影蕭蕭掃徑苔。","醉後不知明月上，狂歌直到夜深回。"]', '["山房寂寂蓽门开，此日相期社友来。","雅兴共尋方外乐，新诗爭羨郢中才。","茶煙褭褭籠禪榻，竹影蕭蕭掃徑苔。","醉後不知明月上，狂歌直到夜深回。"]', '诗', 'shi', '', NULL, '遊報本寺 一 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b206e326-7cb5-44cc-b151-af9eba779434', '遊報本寺 二', '游報本寺 二', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["了然塵事不相關，錫杖時時獨看山。","白髮任教雙鬢改，黃金難買一生閑。","不留活計存囊底，贏得詩名滿世間。","自笑微軀長碌碌，幾時來此學無還。"]', '["了然塵事不相关，錫杖时时独看山。","白髮任教雙鬢改，黄金难買一生闲。","不留活計存囊底，贏得诗名满世间。","自笑微軀长碌碌，幾时来此学無還。"]', '诗', 'shi', '', NULL, '遊報本寺 二 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('371f7357-b097-4255-9cac-7499ccdcb856', '題陳侯竹亭', '題陳侯竹亭', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["曾向幽亭一榻分，清風滿座絕塵氛。","丹山鳳泣鉤簾聽，滄海龍吟對酒聞。","漠漠瞑陰籠砌月，盈盈寒翠動湘雲。","歲寒高節誰能識，獨有王猷愛此君。"]', '["曾向幽亭一榻分，清风满座絕塵氛。","丹山鳳泣鉤簾听，滄海龙吟对酒闻。","漠漠瞑陰籠砌月，盈盈寒翠动湘云。","歲寒高節誰能識，独有王猷愛此君。"]', '诗', 'shi', '', NULL, '題陳侯竹亭 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbe8ec8d-5657-431d-85d9-d3672bbbe8a5', '送報本寺分韻得通字', '送報本寺分韻得通字', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["幾度乘閑謁梵宮，此郎聲價重江東。","貴侯知重曾忘勢，閑客頻來也悟空。","滿地新蔬和雨綠，半林殘葉帶霜紅。","□□□□□□□，□□□□□□□。"]', '["幾度乘闲謁梵宮，此郎声價重江东。","貴侯知重曾忘勢，闲客頻来也悟空。","满地新蔬和雨綠，半林殘葉带霜紅。","□□□□□□□，□□□□□□□。"]', '诗', 'shi', '', NULL, '送報本寺分韻得通字 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2667b4fe-af45-4d3d-8ac6-1db4a3956aad', '寄永平友人 一', '寄永平友人 一', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["故人千里隔天涯，幾度臨風動遠思。","賈誼上書曾伏闕，仲舒陳策欲匡時。","高風落落誰同調，往事悠悠我獨悲。","何日歸來話疇昔，一樽重敘舊襟期。"]', '["故人千里隔天涯，幾度臨风动远思。","賈誼上书曾伏闕，仲舒陳策欲匡时。","高风落落誰同調，往事悠悠我独悲。","何日归来話疇昔，一樽重敘旧襟期。"]', '诗', 'shi', '', NULL, '寄永平友人 一 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e695912e-4d3a-4f25-9d57-c2c00ee844d6', '寄永平友人 二', '寄永平友人 二', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["朔風獵獵慘寒沙，關月寥寥咽暮笳。","放逐一心終去國，驅馳千里未還家。","青蠅點玉原非病，滄海遺珠世所嗟。","直道未容淹屈久，暫勞踪跡寄天涯。"]', '["朔风獵獵慘寒沙，关月寥寥咽暮笳。","放逐一心終去国，驱驰千里未還家。","青蠅点玉原非病，滄海遺珠世所嗟。","直道未容淹屈久，暫勞踪跡寄天涯。"]', '诗', 'shi', '', NULL, '寄永平友人 二 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b4fc113-fbd5-44ef-9815-8a084b6f7a0b', '陳使君山莊', '陳使君山莊', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["新卜幽居地自偏，士林爭羨使君賢。","數椽瀟灑臨溪屋，十畝膏腴附郭田。","流水斷橋芳草路，淡煙疎雨落花天。","秋成準擬重來此，沈醉何妨一榻眠。"]', '["新卜幽居地自偏，士林爭羨使君賢。","數椽瀟灑臨溪屋，十畝膏腴附郭田。","流水斷橋芳草路，淡煙疎雨落花天。","秋成準擬重来此，沈醉何妨一榻眠。"]', '诗', 'shi', '', NULL, '陳使君山莊 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0ef576-82d1-496b-bdd4-e3aee01dfaef', '題寺壁', '題寺壁', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["僧家勝景瞰平川，霧重嵐深馬不前。","宛轉數聲花外鳥，往來幾葉渡頭船。","青山遠隔紅塵路，碧殿深籠綠樹煙。","聞道此中堪遁跡，肯容一榻學逃禪。"]', '["僧家勝景瞰平川，霧重嵐深马不前。","宛轉數声花外鸟，往来幾葉渡头船。","青山远隔紅塵路，碧殿深籠綠樹煙。","闻道此中堪遁跡，肯容一榻学逃禪。"]', '诗', 'shi', '', NULL, '題寺壁 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7676563-d551-42d6-ba01-92ebfe231f4a', '送徐浩', '送徐浩', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["渡口潮平促去舟，莫辭尊酒暫相留。","弟兄聚散雲邊鴈，踪跡浮沈水上鷗。","千里好山青入楚，幾家深樹碧藏樓。","知君此去情偏切，堂上椿萱雪滿頭。"]', '["渡口潮平促去舟，莫辞尊酒暫相留。","弟兄聚散云邊鴈，踪跡浮沈水上鷗。","千里好山青入楚，幾家深樹碧藏楼。","知君此去情偏切，堂上椿萱雪满头。"]', '诗', 'shi', '', NULL, '送徐浩 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bac46d9-0931-4b69-beec-3f548366faad', '謝惠劒', '謝惠劒', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["感君三尺鐵，揮攉鬼神驚。","浩氣中心發，雄風兩腋生。","犬戎從此滅，巢穴不時平。","萬里橫行去，封侯賴有成。"]', '["感君三尺鐵，揮攉鬼神驚。","浩氣中心發，雄风兩腋生。","犬戎從此滅，巢穴不时平。","万里橫行去，封侯賴有成。"]', '诗', 'shi', '', NULL, '謝惠劒 牟融 shi');
